NAME = 'GerZurcher: Deutsche Zürcher Bibel von 1931.'
BOOK = 'Genesis'

CHAPTERS = {
    1: {
        1: 'IM Anfang schuf Gott den Himmel und die Erde.',
        2: 'Die Erde war aber wüst und öde, und Finsternis lag auf der Urflut, und der Geist Gottes schwebte über den Wassern.',
        3: 'Und Gott sprach: Es werde Licht! Und es ward Licht. (a) Jes 45:7',
        4: 'Und Gott sah, daß das Licht gut war, und Gott schied das Licht von der Finsternis.',
        5: 'Und Gott nannte das Licht Tag, und die Finsternis nannte er Nacht. Und es ward Abend und ward Morgen: ein erster Tag.',
        6: 'Und Gott sprach: Es werde eine Feste inmitten der Wasser, und sie scheide die Wasser voneinander! Und es geschah also.',
        7: 'Gott machte die Feste und schied die Wasser unter der Feste von den Wassern über der Feste.',
        8: 'Und Gott nannte die Feste Himmel. Und es ward Abend und ward Morgen: ein zweiter Tag.',
        9: 'Und Gott sprach: Das Wasser unter dem Himmel sammle sich an einen Ort, daß das Trockene sichtbar werde! Und es geschah also.',
        10: 'Und Gott nannte das Trockene Land, und die Ansammlung der Wasser nannte er Meer. Und Gott sah, daß es gut war.',
        11: 'Und Gott sprach: Die Erde lasse sprossen junges Grün: Kraut, das Samen trägt, und Fruchtbäume, die nach ihrer Art Früchte tragen auf der Erde, in denen ihr Same ist! Und es geschah also.',
        12: 'Die Erde ließ sprossen junges Grün: Kraut, das Samen trägt nach seiner Art, und Bäume, die Früchte tragen, in denen ihr Same ist, je nach ihrer Art. Und Gott sah, daß es gut war.',
        13: 'Und es ward Abend und ward Morgen: ein dritter Tag.',
        14: 'Und Gott sprach: Es sollen Lichter werden an der Feste des Himmels, Tag und Nacht zu scheiden, und sie sollen als Zeichen dienen und zur Bestimmung von Zeiten, Tagen und Jahren,',
        15: 'und sie seien Lichter an der Feste des Himmels, daß sie auf die Erde leuchten! Und es geschah also.',
        16: 'Gott machte die zwei großen Lichter: das größere Licht, daß es den Tag beherrsche, und das kleinere Licht, daß es die Nacht beherrsche, dazu auch die Sterne.',
        17: 'Und Gott setzte sie an die Feste des Himmels, daß sie auf die Erde leuchten',
        18: 'und Tag und Nacht beherrschen und Licht und Finsternis scheiden. Und Gott sah, daß es gut war.',
        19: 'Und es ward Abend und ward Morgen: ein vierter Tag.',
        20: 'Und Gott sprach: Es wimmle das Wasser von lebenden Wesen, und Vögel sollen fliegen über der Erde an der Feste des Himmels! Und es geschah also.',
        21: 'Gott schuf die großen Seetiere und alles, was da lebt und webt, wovon das Wasser wimmelt, und alle geflügelten Tiere, ein jegliches nach seiner Art. Und Gott sah, daß es gut war.',
        22: 'Und Gott segnete sie und sprach: Seid fruchtbar und mehret euch und füllet die Wasser des Meeres, und die Vögel sollen sich mehren auf der Erde!',
        23: 'Und es ward Abend und ward Morgen: ein fünfter Tag.',
        24: 'Und Gott sprach: Die Erde bringe hervor lebende Wesen: Vieh, kriechende Tiere und Wild des Feldes, ein jegliches nach seiner Art! Und es geschah also.',
        25: 'Gott machte alle die verschiedenen Arten des Wildes und des Viehs und alles dessen, was auf dem Erdboden kriecht. Und Gott sah, daß es gut war.',
        26: 'Und Gott sprach: Lasset uns Menschen machen nach unserm Bilde, uns ähnlich; die sollen herrschen über die Fische im Meer und die Vögel des Himmels, über das Vieh und alles Wild des Feldes und über alles Kriechende, das auf der Erde sich regt.',
        27: 'Und Gott schuf den Menschen nach seinem Bilde, nach dem Bilde Gottes schuf er ihn; als Mann und Weib schuf er sie.',
        28: 'Und Gott segnete sie und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde und machet sie euch untertan, und herrschet über die Fische im Meer und die Vögel des Himmels, über das Vieh und alle Tiere, die auf der Erde sich regen! (a) 1Mo 9:1; Ps 8:7',
        29: 'Und Gott sprach: Siehe, ich gebe euch alles Kraut, das Samen trägt, auf der ganzen Erde, und alle Bäume, an denen samenhaltige Früchte sind; das soll eure Speise sein.',
        30: 'Aber allen Tieren der Erde und allen Vögeln des Himmels und allem, was sich regt auf der Erde, was Lebensodem in sich hat, gebe ich alles Gras und Kraut zur Nahrung. Und es geschah also.',
        31: 'Und Gott sah alles an, was er gemacht hatte, und siehe, es war sehr gut. Und es ward Abend und ward Morgen: der sechste Tag.',
    },
    2: {
        1: 'Also wurden vollendet der Himmel und die Erde mit ihrem ganzen Heer.',
        2: 'Und Gott vollendete am siebenten Tage sein Werk, das er gemacht hatte, und er ruhte am siebenten Tage von all seinem Werke, das er gemacht hatte. (a) 2Mo 20:11',
        3: 'Und Gott segnete den siebenten Tag und heiligte ihn; denn an ihm hat Gott geruht von all seinem Werke, das er geschaffen und vollbracht hat.',
        4: 'Dies ist die Entstehung des Himmels und der Erde, als sie geschaffen wurden. ZUR Zeit, da Gott der Herr Erde und Himmel machte -',
        5: 'noch gab es aber kein Gesträuch des Feldes auf Erden und noch wuchs kein Kraut auf dem Felde; denn Gott der Herr hatte noch nicht regnen lassen auf die Erde, und es war kein Mensch da, den Boden zu bebauen;',
        6: 'ein Wasserschwall aber brach hervor aus der Erde und tränkte alles Land -',
        7: 'da bildete Gott der Herr den Menschen aus Erde vom Ackerboden und hauchte ihm Lebensodem in die Nase; so ward der Mensch ein lebendes Wesen. (a) Hio 33:4',
        8: 'Dann pflanzte Gott der Herr einen Garten in Eden gegen Osten und setzte den Menschen darein, den er gebildet hatte.',
        9: 'Und Gott der Herr ließ allerlei Bäume aus der Erde wachsen, lieblich anzusehen und gut zu essen, und den Baum des Lebens mitten im Garten, und den Baum der Erkenntnis des Guten und des Bösen. (a) 1Mo 3:22',
        10: 'Es entspringt aber ein Strom in Eden, den Garten zu bewässern; von da aus teilt er sich in vier Arme:',
        11: 'der erste heißt Pison; das ist der, welcher das ganze Land Hawila umfließt, wo das Gold ist;',
        12: 'und das Gold jenes Landes ist köstlich. Da findet man auch das Bdellionharz und den Edelstein Soham.',
        13: 'Der zweite Fluß heißt Gihon; das ist der, welcher das ganze Land Kusch umfließt.',
        14: 'Der dritte Fluß heißt Hiddekel; das ist der, welcher östlich von Assur fließt. Der vierte Fluß ist der Euphrat. (1) d.i: Tigris.',
        15: 'Und Gott der Herr nahm den Menschen und setzte ihn in den Garten Eden, daß er ihn bebaue und bewahre.',
        16: 'Und Gott der Herr gebot dem Menschen und sprach: Von allen Bäumen im Garten darfst du essen;',
        17: 'nur von dem Baume der Erkenntnis des Guten und des Bösen, von dem darfst du nicht essen; denn sobald du davon issest, mußt du sterben.',
        18: 'Und Gott der Herr sprach: Es ist nicht gut, daß der Mensch allein sei. Ich will ihm eine Hilfe schaffen, die zu ihm paßt.',
        19: 'Da bildete Gott der Herr aus Erde alle Tiere des Feldes und alle Vögel des Himmels und brachte sie zum Menschen, um zu sehen, wie er sie nennen würde; und ganz wie der Mensch sie nennen würde, so sollten sie heißen.',
        20: 'Und der Mensch gab allem Vieh und allen Vögeln des Himmels und allen Tieren des Feldes Namen; aber für den Menschen fand er keine Hilfe, die zu ihm paßte.',
        21: 'Da ließ Gott der Herr einen Tiefschlaf auf den Menschen fallen, sodaß er einschlief. Und er nahm eine von seinen Rippen heraus und schloß die Stelle zu mit Fleisch.',
        22: 'Und Gott der Herr baute ein Weib aus der Rippe, die er vom Menschen genommen hatte, und führte sie dem Menschen zu.',
        23: 'Da sprach der Mensch: "Diese ist nun endlich Gebein von meinem Gebein und Fleisch von meinem Fleische. Die soll Männin heißen; denn vom Mann ist sie genommen."',
        24: 'Darum verläßt der Mann Vater und Mutter und hängt seinem Weibe an, und sie werden ein Leib.',
        25: 'Und die beiden, der Mensch und sein Weib, waren nackt und schämten sich nicht.',
    },
    3: {
        1: 'DIE Schlange aber war listiger als alle Tiere des Feldes, die Gott der Herr gemacht hatte, und sie sprach zum Weibe: Gott hat wohl gar gesagt: "Ihr dürft von keinem Baume des Gartens essen!"',
        2: 'Da sprach das Weib zur Schlange: Wir dürfen essen von den Früchten der Bäume im Garten;',
        3: 'nur von den Früchten des Baumes mitten im Garten hat Gott gesagt: "Esset nicht davon; rühret sie auch nicht an, daß ihr nicht sterbet!"',
        4: 'Da sprach die Schlange zum Weibe: Mitnichten werdet ihr sterben;',
        5: 'sondern Gott weiß, daß, sobald ihr davon esset, euch die Augen aufgehen werden und ihr wie Gott sein und wissen werdet, was gut und böse ist.',
        6: 'Und das Weib sah, daß von dem Baume gut zu essen wäre und daß er lieblich anzusehen sei und begehrenswert, weil er klug machte, und sie nahm von seiner Frucht und aß und gab auch ihrem Manne neben ihr, und er aß.',
        7: 'Da gingen den beiden die Augen auf, und sie wurden gewahr, daß sie nackt waren; und sie hefteten Feigenblätter zusammen und machten sich Schurze.',
        8: 'Als sie nun hörten, wie Gott der Herr in der Abendkühle im Garten wandelte, verbarg sich der Mensch mit seinem Weibe vor dem Angesichte Gottes des Herrn unter den Bäumen im Garten.',
        9: 'Und Gott der Herr rief dem Menschen und sprach zu ihm: Wo bist du?',
        10: 'Er sprach: Ich hörte dich im Garten; da fürchtete ich mich, weil ich nackt bin, und verbarg mich.',
        11: 'Und er sprach: Wer hat dir gesagt, daß du nackt bist? Hast du etwa von dem Baume gegessen, von dem ich dir zu essen verboten habe?',
        12: 'Der Mensch sprach: Das Weib, das du mir zugesellt hast, das hat mir von dem Baume gegeben; da habe ich gegessen.',
        13: 'Da sprach Gott der Herr zum Weibe: Was hast du da getan? Das Weib antwortete: Die Schlange hat mich verführt; da habe ich gegessen.',
        14: 'Da sprach Gott der Herr zur Schlange: Weil du das getan, bist du verflucht vor allem Vieh und vor allen Tieren des Feldes. Auf deinem Bauche sollst du kriechen und Staub fressen dein Leben lang.',
        15: 'Und ich will Feindschaft setzen zwischen dir und dem Weibe und zwischen deinem Nachwuchs und ihrem Nachwuchs: er wird dir nach dem Kopfe treten, und du wirst ihm nach der Ferse schnappen.',
        16: 'Und zum Weibe sprach er: Ich will dir viel Beschwerden machen in deiner Schwangerschaft; mit Schmerzen sollst du Kinder gebären! Nach deinem Manne wirst du verlangen; er aber soll dein Herr sein! (a) 1Kor 11:3; Eph 5:22',
        17: 'Und zum Menschen sprach er: Weil du auf deines Weibes Stimme gehört und von dem Baume gegessen hast, von dem ich dir gebot: du sollst nicht davon essen, so ist um deinetwillen der Erdboden verflucht. Mit Mühsal sollst du dich von ihm nähren dein Leben lang.',
        18: 'Dornen und Disteln soll er dir tragen, und das Kraut des Feldes sollst du essen.',
        19: 'Im Schweiße deines Angesichtes sollst du dein Brot essen, bis du wieder zur Erde kehrst, von der du genommen bist; denn Erde bist du, und zur Erde mußt du zurück. (a) Pre 12:7',
        20: 'Und der Mensch nannte sein Weib Eva; denn sie wurde die Mutter aller Lebenden.',
        21: 'Und Gott der Herr machte dem Menschen und seinem Weibe Röcke von Fell und legte sie ihnen um.',
        22: 'Und Gott der Herr sprach: Siehe, der Mensch ist geworden wie unsereiner, daß er weiß, was gut und böse ist. Nun aber, daß er nur nicht seine Hand ausstrecke und auch von dem Baume des Lebens breche und ewig lebe!',
        23: 'So schickte ihn Gott der Herr fort aus dem Garten Eden, daß er den Erdboden bebaue, von dem er genommen war.',
        24: 'Und er vertrieb den Menschen und ließ östlich vom Garten Eden die Cherube sich lagern und die Flamme des zuckenden Schwertes, den Weg zum Baume des Lebens zu bewachen.',
    },
    4: {
        1: 'DER Mensch aber wohnte seinem Weibe Eva bei, und sie ward schwanger und gebar den Kain. Da sprach sie: Ich habe einen Sohn bekommen mit des Herrn Hilfe.',
        2: 'Und weiter gebar sie den Abel, seinen Bruder. Abel ward ein Schäfer, Kain aber ward ein Ackerbauer.',
        3: 'Es begab sich aber nach geraumer Zeit, daß Kain von den Früchten des Ackers dem Herrn ein Opfer brachte.',
        4: 'Und auch Abel brachte von den Erstlingen seiner Schafe dar und von ihrem Fette. Und der Herr sah wohlgefällig auf Abel und sein Opfer,',
        5: 'auf Kain aber und sein Opfer sah er nicht. Da ergrimmte Kain gar sehr und blickte finster.',
        6: 'Und der Herr sprach zu Kain: Warum ergrimmst du, und warum blickst du so finster?',
        7: "Ist's nicht also? Wenn du recht handelst, darfst du frei aufschauen; handelst du aber nicht recht, so lauert die Sünde vor der Tür, und nach dir steht ihre Begierde; du aber sollst Herr werden über sie! (a) Rö 6:12",
        8: 'Darauf sprach Kain zu seinem Bruder Abel: Laß uns aufs Feld gehen! Und als sie auf dem Felde waren, erhob sich Kain wider seinen Bruder Abel und schlug ihn tot.',
        9: 'Da sprach der Herr zu Kain: Wo ist dein Bruder Abel? Er sprach: Ich weiß nicht. Bin ich denn meines Bruders Hüter?',
        10: 'Er aber sprach: Was hast du getan! Horch, das Blut deines Bruders schreit zu mir empor vom Ackerland.',
        11: 'Und nun - verflucht bist du, verbannt vom Ackerland, das seinen Mund aufgetan hat, aus deiner Hand das Blut deines Bruders zu empfangen.',
        12: 'Wenn du den Acker bebauen wirst, soll er dir hinfort seinen Ertrag nicht mehr geben: unstet und flüchtig sollst du sein auf Erden.',
        13: 'Da sprach Kain zu dem Herrn: Meine Strafe ist größer, als daß ich sie tragen könnte.',
        14: 'Siehe, du vertreibst mich heute vom Ackerland, und ich muß mich vor deinem Angesicht verbergen; unstet und flüchtig muß ich sein auf Erden. So wird mich denn totschlagen, wer mich antrifft.',
        15: 'Der Herr aber sprach zu ihm: Nicht also! Wer immer Kain totschlägt, an dem wird es siebenfältig gerächt. Und der Herr versah Kain mit einem Zeichen, daß keiner ihn erschlüge, der ihn anträfe.',
        16: 'Also ging Kain hinweg vom Angesichte des Herrn und wohnte im Lande Nod, östlich von Eden.',
        17: 'Und Kain wohnte seinem Weibe bei; da ward sie schwanger und gebar den Henoch. Und er ward Erbauer einer Stadt; die nannte er nach seines Sohnes Namen Henoch.',
        18: 'Dem Henoch wurde Irad geboren; Irad aber zeugte Mehujael, Mehujael zeugte Methusael, Methusael zeugte Lamech.',
        19: 'Lamech aber nahm zwei Frauen; die eine hieß Ada, die andre Zilla.',
        20: 'Und Ada gebar den Jabal; der wurde der Vater derer, die in Zelten und bei Herden wohnen.',
        21: 'Sein Bruder hieß Jubal; der wurde der Vater aller derer, die Zither und Schalmei handhaben.',
        22: 'Aber auch Zilla gebar einen Sohn, den Thubal-Kain; der wurde der Vater aller derer, die Erz und Eisen schmieden. Und die Schwester Thubal-Kains war Naema.',
        23: 'Und Lamech sprach zu seinen Frauen: Ada und Zilla, hört meine Rede, / ihr Weiber Lamechs, vernehmt meinen Spruch! / Einen Mann erschlug ich für meine Wunde / und einen Jüngling für meine Strieme. /',
        24: 'Denn wird Kain siebenmal gerächt, / so Lamech siebenundsiebzigmal.',
        25: 'Und Adam wohnte seinem Weibe abermals bei, und sie gebar einen Sohn, den hieß sie Seth, denn Gott hat mir, (so sprach sie,) einen andern Sproß gegeben für Abel, weil Kain ihn erschlagen hat.',
        26: 'Und auch dem Seth ward ein Sohn geboren; den hieß er Enos. Damals fing man an, den Namen Jahwes anzurufen. (1) der bes. Name des Gottes Israels lautete ursprünglich [Jahwe]. In der Reformationszeit kam dafür irrtümlicherweise die Namensform Jehova in Gebrauch. Die meisten Üs. wählten statt dessen nach jüd. Vorgang die allgemeine Bez. "der Herr", die in der Regel auch in unsrer Zürcher Bibel beibehalten ist.',
    },
    5: {
        1: 'DIES ist das Verzeichnis der Nachkommen Adams: Als Gott den Adam erschuf, machte er ihn Gott ähnlich; (a) 1Mo 1:27',
        2: 'als Mann und Weib schuf er sie. Und er segnete sie und gab ihnen den Namen Adam, damals als sie geschaffen wurden. (1) d.i. Mensch. (a) 1Mo 1:27',
        3: 'Als Adam 130 Jahre alt war, zeugte er einen Sohn, ihm selbst ähnlich, nach seinem Bilde; den hieß er Seth.',
        4: 'Und nachdem Adam den Seth gezeugt, lebte er noch achthundert Jahre und zeugte Söhne und Töchter.',
        5: 'So betrug Adams ganze Lebenszeit 930 Jahre; dann starb er.',
        6: 'Als Seth 105 Jahre alt war, zeugte er den Enos.',
        7: 'Und nachdem Seth den Enos gezeugt, lebte er noch 807 Jahre und zeugte Söhne und Töchter.',
        8: 'So betrug Seths ganze Lebenszeit 912 Jahre; dann starb er.',
        9: 'Als Enos neunzig Jahre alt war, zeugte er den Kenan.',
        10: 'Und nachdem Enos den Kenan gezeugt, lebte er noch 815 Jahre und zeugte Söhne und Töchter.',
        11: "So betrug Enos' ganze Lebenszeit 905 Jahre; dann starb er.",
        12: 'Als Kenan siebzig Jahre alt war, zeugte er den Mahalaleel.',
        13: 'Und nachdem Kenan den Mahalaleel gezeugt, lebte er noch 840 Jahre und zeugte Söhne und Töchter.',
        14: 'So betrug Kenans ganze Lebenszeit 910 Jahre; dann starb er.',
        15: 'Als Mahalaleel 65 Jahre alt war, zeugte er den Jared.',
        16: 'Und nachdem Mahalaleel den Jared gezeugt, lebte er noch 830 Jahre und zeugte Söhne und Töchter.',
        17: 'So betrug Mahalaleels ganze Lebenszeit 895 Jahre; dann starb er.',
        18: 'Als Jared 162 Jahre alt war, zeugte er den Henoch.',
        19: 'Und nachdem Jared den Henoch gezeugt, lebte er noch achthundert Jahre und zeugte Söhne und Töchter.',
        20: 'So betrug Jareds ganze Lebenszeit 962 Jahre; dann starb er.',
        21: 'Als Henoch 65 Jahre alt war, zeugte er den Methusalah.',
        22: 'Und Henoch wandelte mit Gott; und nachdem er den Methusalah gezeugt, lebte er noch dreihundert Jahre und zeugte Söhne und Töchter.',
        23: 'So betrug Henochs ganze Lebenszeit 365 Jahre.',
        24: 'Henoch wandelte mit Gott, und auf einmal war er nicht mehr da; denn Gott hatte ihn hinweggenommen. (a) Heb 11:5',
        25: 'Als Methusalah 187 Jahre alt war, zeugte er den Lamech.',
        26: 'Und nachdem Methusalah den Lamech gezeugt, lebte er noch 782 Jahre und zeugte Söhne und Töchter.',
        27: 'So betrug Methusalahs ganze Lebenszeit 969 Jahre; dann starb er.',
        28: 'Als Lamech 182 Jahre alt war, zeugte er einen Sohn;',
        29: 'den hieß er Noah, indem er sprach: Dieser wird uns Erquickung schaffen von unsrer Arbeit und der Mühsal unsrer Hände durch den Acker, den der Herr verflucht hat.',
        30: 'Und nachdem Lamech den Noah gezeugt, lebte er noch 595 Jahre und zeugte Söhne und Töchter.',
        31: 'So betrug Lamechs ganze Lebenszeit 777 Jahre; dann starb er.',
        32: 'Als Noah fünfhundert Jahre alt war, zeugte er den Sem, den Ham und den Japhet.',
    },
    6: {
        1: 'ALS aber die Menschen anfingen, sich auf der Erde zu mehren, und ihnen Töchter geboren wurden,',
        2: 'sahen die Gottessöhne, daß die Töchter der Menschen schön waren, und sie nahmen sich zu Weibern, welche sie nur wollten.',
        3: 'Da sprach der Herr: Mein Geist soll nicht auf immer im Menschen walten, dieweil auch er Fleisch ist, und seine Lebenszeit sei 120 Jahre.',
        4: 'Zu jenen Zeiten - und auch nachmals noch -, als die Gottessöhne zu den Töchtern der Menschen sich gesellten und diese ihnen Kinder gebaren, waren die Riesen auf Erden. Das sind die Recken der Urzeit, die hochberühmten.',
        5: 'Als aber der Herr sah, daß der Menschen Bosheit groß war auf Erden, und daß alles Dichten und Trachten ihres Herzens die ganze Zeit nur böse war, (a) 1Mo 8:21',
        6: 'da reute es den Herrn, daß er den Menschen geschaffen hatte auf Erden, und es bekümmerte ihn tief.',
        7: 'Und der Herr sprach: Ich will die Menschen, die ich geschaffen habe, vom Erdboden vertilgen, die Menschen sowohl als das Vieh, auch die kriechenden Tiere und die Vögel des Himmels; denn es reut mich, daß ich sie gemacht habe.',
        8: 'Noah aber hatte Gnade gefunden vor dem Herrn.',
        9: 'Dies ist die Geschichte Noahs: Noah war ein frommer Mann, unsträflich unter seinen Zeitgenossen; mit Gott wandelte er.',
        10: 'Und Noah zeugte drei Söhne: Sem, Ham und Japhet.',
        11: 'Aber die Erde ward verderbt vor Gott, und voll ward die Erde von Frevel.',
        12: 'Da sah Gott auf die Erde, und siehe, sie war verderbt; denn alles Fleisch hatte seinen Wandel verderbt auf Erden. (a) Ps 14:3',
        13: 'Da sprach Gott zu Noah: Das Ende alles Fleisches ist bei mir beschlossen; denn die Erde ist voller Frevel von den Menschen her. So will ich sie denn von der Erde vertilgen.',
        14: 'Mache dir eine Arche von Tannenholz; aus lauter Zellen sollst du die Arche machen, und verpiche sie inwendig und auswendig mit Pech.',
        15: 'Und so sollst du sie machen: dreihundert Ellen sei die Länge der Arche, fünfzig Ellen ihre Breite und dreißig Ellen ihre Höhe;',
        16: 'nach der Elle sollst du sie fertigstellen. Ein Dach aber sollst du oben an der Arche machen, und die Türe der Arche sollst du an der Seite anbringen. Ein unteres, ein zweites und ein drittes Stockwerk sollst du darin machen. (1) aÜs: eine "Lichtöffnung".',
        17: 'Ich aber lasse jetzt die Sintflut über die Erde kommen, um alles Fleisch, das Lebensodem in sich hat, unter dem Himmel zu vertilgen; alles, was auf Erden ist, soll hinsterben.',
        18: 'Aber mit dir will ich einen Bund aufrichten: du sollst in die Arche gehen, du und deine Söhne und dein Weib und deine Schwiegertöchter mit dir.',
        19: 'Und von allen Tieren, von allem Fleisch, sollst du je ein Paar in die Arche führen, um sie bei dir am Leben zu erhalten; ein Männchen und ein Weibchen sollen es sein.',
        20: 'Von jeder Art der Vögel und des Viehs und alles dessen, was auf Erden kriecht, von allem soll je ein Paar zu dir hineingehen, um am Leben zu bleiben.',
        21: 'Du aber nimm dir von jeglicher Speise, die man ißt, und lege dir einen Vorrat an, damit er dir und ihnen zur Nahrung diene.',
        22: 'Und Noah tat es; ganz wie ihm Gott geboten hatte, so tat er.',
    },
    7: {
        1: 'Und der Herr sprach zu Noah: Gehe in die Arche, du und dein ganzes Haus; denn dich habe ich gerecht vor mir erfunden unter diesem Geschlechte.',
        2: 'Nimm dir von allen reinen Tieren je sieben, Männchen und Weibchen, von den unreinen Tieren aber je ein Paar, ein Männchen und ein Weibchen, (a) 3Mo 11',
        3: 'auch von den Vögeln des Himmels je sieben, Männchen und Weibchen, damit auf der ganzen Erde Nachwuchs am Leben bleibe.',
        4: 'Denn nach sieben Tagen will ich regnen lassen auf die Erde, vierzig Tage und vierzig Nächte lang, und will alle Wesen, die ich gemacht habe, vom Erdboden vertilgen.',
        5: 'Und Noah tat, ganz wie ihm der Herr geboten hatte.',
        6: 'Noah aber war sechshundert Jahre alt, als die Sintflut über die Erde kam.',
        7: 'Und Noah ging mit seinen Söhnen und mit seinem Weibe und seinen Schwiegertöchtern vor den Wassern der Sintflut in die Arche.',
        8: 'Von den reinen und von den unreinen Tieren, von den Vögeln und von allem, was auf Erden kriecht,',
        9: 'ging je ein Paar, ein Männchen und ein Weibchen, zu Noah in die Arche, wie Gott dem Noah geboten hatte. (a) 1Mo 6:19',
        10: 'Und nach den sieben Tagen kamen die Wasser der Sintflut über die Erde.',
        11: 'Im sechshundertsten Lebensjahre Noahs, am siebzehnten Tage des zweiten Monats, an diesem Tage brachen alle Brunnen der großen Urflut auf, und die Fenster des Himmels öffneten sich.',
        12: 'Und der Regen strömte auf die Erde, vierzig Tage und vierzig Nächte lang.',
        13: 'An eben diesem Tage ging Noah mit seinen Söhnen Sem, Ham und Japhet, mit seinem Weibe und seinen drei Schwiegertöchtern in die Arche;',
        14: 'sie und alle die verschiedenen Arten des Wildes und des Viehs und alles dessen, was auf Erden kriecht, und auch der Vögel, alles dessen, was fliegt, was Flügel hat:',
        15: 'die gingen zu Noah in die Arche, je zwei von allem Fleische, das Lebensodem in sich hatte.',
        16: 'Und die hineingingen, waren je ein Männchen und ein Weibchen von allem Fleische, wie ihm Gott geboten hatte. Und der Herr schloß hinter ihm zu.',
        17: 'Da kam die Sintflut über die Erde, vierzig Tage lang, und die Wasser wuchsen und hoben die Arche, und sie schwamm hoch über der Erde.',
        18: 'Und die Wasser nahmen mächtig überhand und wuchsen gewaltig über der Erde, und die Arche fuhr auf den Wassern dahin.',
        19: 'Und die Wasser wurden immer mächtiger über der Erde, sodaß alle hohen Berge unter dem ganzen Himmel bedeckt wurden.',
        20: 'Fünfzehn Ellen stiegen die Wasser darüber hinaus, sodaß die Berge bedeckt wurden.',
        21: 'Da starb alles Fleisch dahin, das sich auf Erden regte, an Vögeln, an Vieh, an Wild und allem, was auf Erden wimmelte, auch alle Menschen.',
        22: 'Alles, was Lebensluft atmete, was auf dem Trockenen war, das starb.',
        23: 'So vertilgte er alle Wesen, die auf dem Erdboden waren: die Menschen sowohl als das Vieh, das Kriechende und die Vögel des Himmels, die wurden vertilgt von der Erde; nur Noah blieb übrig und was mit ihm in der Arche war.',
        24: 'Und die Wasser nahmen zu auf der Erde, 150 Tage lang.',
    },
    8: {
        1: 'Da gedachte Gott des Noah und all des Wildes und des Viehs, das bei ihm in der Arche war. Und Gott ließ einen Wind über die Erde wehen, und die Wasser sanken;',
        2: 'und es schlossen sich die Brunnen der Urflut und die Fenster des Himmels. Dem Regen vom Himmel ward gewehrt,',
        3: 'und die Wasser verliefen sich nach und nach von der Erde. So nahmen die Wasser ab nach den 150 Tagen,',
        4: 'und am siebzehnten Tage des siebenten Monats ließ sich die Arche auf den Bergen von Ararat nieder.',
        5: 'Die Wasser aber sanken noch weiter, bis zum zehnten Monat; am ersten Tage des zehnten Monats wurden die Spitzen der Berge sichtbar.',
        6: 'Nach Verlauf von vierzig Tagen aber öffnete Noah das Fenster der Arche, das er gemacht hatte,',
        7: 'und ließ den Raben ausfliegen; der flog hin und her, bis die Wasser auf Erden vertrocknet waren.',
        8: 'Da wartete Noah sieben Tage; dann ließ er die Taube ausfliegen, um zu sehen, ob sich die Wasser vom Erdboden verlaufen hätten.',
        9: 'Da aber die Taube keine Stätte fand, wo ihr Fuß ruhen konnte, kam sie wieder zu ihm in die Arche; denn noch war Wasser auf der ganzen Erde. Da streckte er seine Hand aus, faßte sie und nahm sie zu sich herein in die Arche.',
        10: 'Hierauf wartete er noch weitere sieben Tage; dann ließ er die Taube abermals aus der Arche fliegen.',
        11: 'Die kam um die Abendzeit zu ihm zurück, und siehe da! sie trug ein frisches Ölblatt in ihrem Schnabel. Da merkte Noah, daß sich die Wasser von der Erde verlaufen hatten.',
        12: 'Dann wartete er noch weitere sieben Tage und ließ die Taube ausfliegen; sie kam aber nicht wieder zu ihm.',
        13: 'Im 601. Lebensjahre Noahs, am ersten Tage des ersten Monats, waren die Wasser auf Erden versiegt. Da tat Noah das Dach von der Arche, und siehe da! der Erdboden war trocken geworden.',
        14: 'Am 27. Tage des zweiten Monats war die Erde ganz trocken.',
        15: 'Da redete Gott mit Noah und sprach:',
        16: 'Geh aus der Arche, du und dein Weib und deine Söhne und deine Schwiegertöchter mit dir;',
        17: 'und alle die Tiere, die bei dir sind, alle Geschöpfe: Vögel, Vieh und alles, was auf Erden kriecht, die laß heraus mit dir, daß sie sich tummeln auf der Erde und fruchtbar seien und sich mehren auf Erden. (a) 1Mo 1:22',
        18: 'Da ging Noah hinaus mit seinen Söhnen, mit seinem Weibe und seinen Schwiegertöchtern.',
        19: 'Auch alles Wild und alles Vieh, alle Vögel und alles, was auf Erden kriecht, die gingen hinaus aus der Arche, Art um Art.',
        20: 'Noah aber baute dem Herrn einen Altar; dann nahm er von allen reinen Tieren und von allen reinen Vögeln und brachte Brandopfer auf dem Altar. (a) 3Mo 11',
        21: 'Und der Herr roch den lieblichen Duft und sprach bei sich selbst: Ich will hinfort nicht mehr die Erde um der Menschen willen verfluchen; ist doch das Trachten des menschlichen Herzens böse von Jugend auf. Und ich will hinfort nicht mehr schlagen, was da lebt, wie ich getan habe. (a) 1Mo 6:5',
        22: 'Solange die Erde steht, soll nicht aufhören Saat und Ernte, Frost und Hitze, Sommer und Winter, Tag und Nacht.',
    },
    9: {
        1: 'UND Gott segnete Noah und seine Söhne und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde! (a) 1Mo 1:28',
        2: 'Furcht und Schrecken vor euch komme über alle Tiere der Erde, über alle Vögel des Himmels, über alles, was auf Erden kriecht, und über alle Fische im Meer: in eure Hand sind sie gegeben.',
        3: 'Alles, was sich regt und lebt, das sei eure Speise; wie das Kraut, das grüne, gebe ich euch alles. (a) 1Mo 1:29',
        4: 'Nur Fleisch, das seine Seele - sein Blut - noch in sich hat, dürft ihr nicht essen. (a) 3Mo 17:14',
        5: 'Euer eignes (vergossenes) Blut aber will ich einfordern; von allen Tieren will ich es einfordern, und von den Menschen untereinander will ich das Leben des Menschen einfordern: (a) 2Mo 21:12 28',
        6: 'wer Menschenblut vergießt, dessen Blut soll auch durch Menschen vergossen werden; denn Gott hat den Menschen nach seinem Bilde gemacht. (a) 1Mo 1:27',
        7: 'Ihr nun, seid fruchtbar und mehret euch, breitet euch aus auf der Erde und herrscht über sie!',
        8: 'Dann sprach Gott zu Noah und zu seinen Söhnen, die bei ihm waren:',
        9: 'Ich aber, siehe, ich richte einen Bund auf mit euch und euren Nachkommen',
        10: 'und mit allen lebenden Wesen, die bei euch sind, Vögeln, Vieh und allem Wild des Feldes bei euch, mit allen, die aus der Arche gekommen sind.',
        11: 'Ich will einen Bund mit euch aufrichten, daß niemals wieder alles Fleisch von den Wassern der Sintflut soll ausgerottet werden und niemals wieder eine Sintflut kommen soll, die Erde zu verderben. (a) 1Mo 8:21',
        12: 'Und Gott sprach: Dies ist das Zeichen des Bundes, den ich stifte zwischen mir und euch und allen Lebewesen, die bei euch sind, auf ewige Zeiten:',
        13: 'meinen Bogen stelle ich in die Wolken; der soll ein Bundeszeichen sein zwischen mir und der Erde.',
        14: 'Wenn ich nun Wolken häufe ob der Erde und sich der Bogen in den Wolken zeigt,',
        15: 'dann will ich des Bundes gedenken, der da besteht zwischen mir und euch und allen lebenden Wesen, und niemals wieder sollen die Wasser zu einer Sintflut werden, die alles Fleisch verderbe.',
        16: 'Und wenn der Bogen in den Wolken steht, will ich ihn ansehen, um des ewigen Bundes zu gedenken zwischen Gott und allen lebenden Wesen, die auf Erden sind.',
        17: 'Und Gott sprach zu Noah: Dies ist das Zeichen des Bundes, den ich aufrichte zwischen mir und allem Fleische, das auf Erden ist.',
        18: 'Die Söhne Noahs, die aus der Arche gingen, waren Sem, Ham und Japhet. Ham aber ist der Vater Kanaans.',
        19: 'Diese drei sind die Söhne Noahs, und von ihnen aus hat sich die ganze Erde bevölkert.',
        20: 'Noah aber, der Landmann, war der erste, der Weinreben pflanzte.',
        21: 'Und da er von dem Weine trank, ward er berauscht und lag entblößt im Innern seines Zeltes.',
        22: 'Als nun Ham, der Vater Kanaans, seines Vaters Blöße sah, sagte er es seinen beiden Brüdern draußen.',
        23: 'Da nahmen Sem und Japhet das Gewand, legten es auf ihre Schultern und gingen rückwärts hinzu und bedeckten ihres Vaters Blöße, indem ihr Angesicht rückwärts gewendet war, sodaß sie ihres Vaters Blöße nicht sahen.',
        24: 'Als aber Noah von seinem Rausch erwachte und erfuhr, was ihm sein jüngster Sohn getan,',
        25: 'sprach er: Verflucht sei Kanaan! / Knecht der Knechte / sei er seinen Brüdern!',
        26: 'Und weiter sprach er: Gepriesen sei der Herr, der Gott Sems, / Kanaan aber sei ihm Knecht! /',
        27: 'Raum schaffe Gott dem Japhet, / daß er wohne in den Zelten Sems, / Kanaan aber sei ihm Knecht!',
        28: 'Noah lebte nach der Sintflut noch 350 Jahre,',
        29: 'und Noahs ganze Lebenszeit betrug 950 Jahre; dann starb er.',
    },
    10: {
        1: 'DIES sind die Nachkommen der Söhne Noahs, Sem, Ham und Japhet; diesen wurden Söhne geboren nach der Sintflut.',
        2: 'Die Söhne Japhets sind: Gomer, Magog, Madai, Jawan, Thubal, Mesech und Thiras. (1) d.i. Meder. (2) d.i. Jonier, Griechen.',
        3: 'Die Söhne Gomers sind: Askenas, Riphath und Thogarma.',
        4: 'Die Söhne Jawans sind: Elisa, Tharsis, die Chittäer und die Rhodier. (1) in Spanien. (2) d.i. Cyprier.',
        5: 'Von ihnen haben sich die Inselvölker abgezweigt. Das sind die Nachkommen Japhets nach ihren Ländern, ihren Sprachen, ihren Geschlechtern, ihren Völkerschaften.',
        6: 'Die Söhne Hams sind: Kusch, Mizraim, Put und Kanaan. (1) d.i. Ägypter.',
        7: 'Die Söhne Kuschs sind: Seba, Hawila, Sabtha, Ragma und Sabthecha. Die Söhne Ragmas sind: Saba und Dedan.',
        8: 'Kusch aber zeugte den Nimrod; der war der erste Gewaltherrscher auf Erden.',
        9: 'Dieser ward ein gewaltiger Jäger vor dem Herrn. Daher sagt man: ein gewaltiger Jäger vor dem Herrn wie Nimrod.',
        10: 'Und der Anfang seines Reiches war Babel, Erech, Akkad und Kalne im Lande Sinear. (1) d.i. Babylonien.',
        11: 'Von diesem Lande zog er aus nach Assur und baute Ninive, Rehoboth-Ir und Kelah,',
        12: 'und Resen zwischen Ninive und Kelah; dies ist die große Stadt.',
        13: 'Mizraim aber zeugte die Luditer, die Anamiter, die Lehabiter, die Naphthuhiter,',
        14: 'die Pathrusiter, die Kasluhiter und die Kaphthoriter, von denen die Philister ausgegangen sind. (1) d.i. Kreter.',
        15: 'Kanaan aber zeugte Sidon, seinen Erstgebornen, und Heth,',
        16: 'und die Jebusiter, die Amoriter, die Girgasiter,',
        17: 'die Hewiter, die Arkiter, die Siniter,',
        18: 'die Arwaditer, die Zamariter und die Hamathiter. Später zerstreuten sich die Geschlechter der Kanaaniter;',
        19: 'so reichte das Gebiet der Kanaaniter von Sidon an gegen Gerar hin bis nach Gaza und gegen Sodom, Gomorrha, Adma und Zeboim hin bis nach Lesa.',
        20: 'Das sind die Nachkommen Hams nach ihren Geschlechtern, ihren Sprachen, ihren Ländern, ihren Völkerschaften.',
        21: 'Aber auch Sem, dem Vater aller Söhne Hebers, dem ältern Bruder Japhets, wurden Söhne geboren.',
        22: 'Die Söhne Sems sind: Elam, Assur, Arpachsad, Lud und Aram. (1) d.i. Südwestpersien. (2) d.i. Syrien.',
        23: 'Die Söhne Arams aber sind: Uz, Hul, Gether und Mas.',
        24: 'Arpachsad aber zeugte Selah, und Selah zeugte Heber.',
        25: 'Heber wurden zwei Söhne geboren; einer hieß Peleg, weil zu seiner Zeit die Menschheit sich zerteilte, und sein Bruder hieß Joktan. (1) d.i. Teilung.',
        26: 'Joktan aber zeugte Almodad, Seleph, Hazarmawet, Jerah,',
        27: 'Hadoram, Usal, Dikla,',
        28: 'Obal, Abimael, Saba,',
        29: 'Ophir, Hawila und Jobab. Diese alle sind die Söhne Joktans.',
        30: 'Und ihre Wohnsitze reichten von Mesa an gegen Sephar hin bis an das Ostgebirge.',
        31: 'Das sind die Nachkommen Sems nach ihren Geschlechtern, ihren Sprachen, ihren Ländern, ihren Völkerschaften.',
        32: 'Das sind die Geschlechter der Nachkommen Noahs nach ihrer Abstammung, nach ihren Völkerschaften; und von diesen aus verzweigten sich die Völker auf der Erde nach der Sintflut.',
    },
    11: {
        1: 'ES hatte aber alle Welt einerlei Sprache und einerlei Worte.',
        2: 'Als sie nun im Osten aufbrachen, fanden sie eine Ebene im Lande Sinear, und sie liessen sich dort nieder.',
        3: 'Und sie sprachen untereinander: Wohlan, lasst uns Ziegel streichen und hart brennen! Und es diente ihnen der Ziegel als Stein, und der Asphalt diente ihnen als Mörtel.',
        4: 'Und sie sprachen: Wohlan, lasst uns eine Stadt bauen und einen Turm, dessen Spitze bis in den Himmel reicht; so wollen wir uns ein Denkmal schaffen, damit wir uns nicht über die ganze Erde zerstreuen.',
        5: 'Da fuhr der Herr hernieder, um die Stadt zu besehen und den Turm, den die Menschenkinder gebaut hatten.',
        6: 'Und der Herr sprach: Siehe, sie sind ein Volk und haben alle eine Sprache. Und dies ist erst der Anfang ihres Tuns; nunmehr wird ihnen nichts unmöglich sein, was immer sie sich vornehmen.',
        7: 'Wohlan, lasst uns hinabfahren und daselbst ihre Sprache verwirren, dass keiner mehr des andern Sprache verstehe.',
        8: 'Also zerstreute sie der Herr von dort über die ganze Erde, und sie liessen ab, die Stadt zu bauen.',
        9: 'Daher heisst ihr Name Babel, weil der Herr daselbst die Sprache aller Welt verwirrt und sie von dort über die ganze Erde zerstreut hat. (1) in dem Namen Babel hörte man einen Anklang an ein hebrW., das "verwirren" bedeutet.',
        10: 'DIES sind die Nachkommen Sems: Als Sem hundert Jahre alt war, zeugte er, zwei Jahre nach der Sintflut, den Arpachsad.',
        11: 'Und nachdem Sem den Arpachsad gezeugt, lebte er noch fünfhundert Jahre und zeugte Söhne und Töchter.',
        12: 'Als Arpachsad 35 Jahre alt war, zeugte er den Selah.',
        13: 'Und nachdem Arpachsad den Selah gezeugt, lebte er noch 403 Jahre und zeugte Söhne und Töchter.',
        14: 'Als Selah dreissig Jahre alt war, zeugte er den Heber.',
        15: 'Und nachdem Selah den Heber gezeugt, lebte er noch 403 Jahre und zeugte Söhne und Töchter.',
        16: 'Als Heber 34 Jahre alt war, zeugte er den Peleg.',
        17: 'Und nachdem Heber den Peleg gezeugt, lebte er noch 430 Jahre und zeugte Söhne und Töchter.',
        18: 'Als Peleg dreissig Jahre alt war, zeugte er den Regu.',
        19: 'Und nachdem Peleg den Regu gezeugt, lebte er noch 209 Jahre und zeugte Söhne und Töchter.',
        20: 'Als Regu 32 Jahre alt war, zeugte er den Serug.',
        21: 'Und nachdem Regu den Serug gezeugt, lebte er noch 207 Jahre und zeugte Söhne und Töchter.',
        22: 'Als Serug dreissig Jahre alt war, zeugte er den Nahor.',
        23: 'Und nachdem Serug den Nahor gezeugt, lebte er noch zweihundert Jahre und zeugte Söhne und Töchter.',
        24: 'Als Nahor 29 Jahre alt war, zeugte er den Tharah.',
        25: 'Und nachdem Nahor den Tharah gezeugt, lebte er noch zweihundert Jahre und zeugte Söhne und Töchter.',
        26: 'Als Tharah siebzig Jahre alt war, zeugte er den Abram, den Nahor und den Haran.',
        27: 'Und dies sind die Nachkommen Tharahs: Tharah zeugte den Abram, den Nahor und den Haran; und Haran zeugte den Lot.',
        28: 'Haran aber starb bei Lebzeiten seines Vaters Tharah in seiner Heimat, zu Ur in Chaldäa.',
        29: 'Da nahmen sich Abram und Nahor Frauen; Abrams Weib hiess Sarai, und Nahors Weib hiess Milka, die Tochter Harans, des Vaters der Milka und der Jiska.',
        30: 'Sarai aber war unfruchtbar; sie hatte keine Kinder.',
        31: 'Da nahm Tharah seinen Sohn Abram und seinen Enkel Lot, den Sohn Harans, und seine Schwiegertochter Sarai, das Weib seines Sohnes Abram, und führte sie hinweg aus Ur in Chaldäa, um ins Land Kanaan zu ziehen; und sie kamen bis Haran und liessen sich dort nieder.',
        32: 'Und Tharahs Lebenszeit betrug 205 Jahre; dann starb Tharah in Haran.',
    },
    12: {
        1: 'UND der Herr sprach zu Abram: Ziehe hinweg aus deinem Vaterlande und aus deiner Verwandtschaft und aus deines Vaters Hause in das Land, das ich dir zeigen werde; (a) Jos 24:3',
        2: 'so will ich dich zu einem grossen Volke machen und dich segnen und deinen Namen berühmt machen, dass er zum Segensworte wird. (1) V. 2-3: vgl. 1Mo 48:20; Jer 29:32; Ps 72:17',
        3: 'Segnen will ich, die dich segnen, und wer dir flucht, den will ich verfluchen; und mit deinem Namen werden sich Segen wünschen alle Geschlechter der Erde. (1) vgl. 1Mo 48:20; Jer 29:32; Ps 72:17 (a) 1Mo 22:18; 26:4',
        4: 'Da zog Abram hin, wie ihm der Herr geboten hatte, und Lot zog mit ihm. Abram aber war 75 Jahre alt, als er aus Haran wegzog.',
        5: 'Und Abram nahm sein Weib Sarai und Lot, seines Bruders Sohn, und all ihre Habe, die sie gewonnen, und die Leute, die sie in Haran erworben hatten, und sie wanderten aus, um ins Land Kanaan zu ziehen. Und sie kamen ins Land Kanaan.',
        6: 'Da zog Abram durch das Land bis zu der Stätte von Sichem, bis zur Orakel-Terebinthe. Damals aber waren die Kanaaniter im Lande.',
        7: 'Da erschien der Herr dem Abram und sprach zu ihm: Deinen Nachkommen will ich dieses Land geben. Und er baute daselbst dem Herrn, der ihm erschienen war, einen Altar. (a) 1Mo 13:15; 15:18',
        8: 'Darnach brach er von dannen auf nach dem Gebirge östlich von Bethel und schlug sein Zelt auf, Bethel im Westen und Ai im Osten; da baute er dem Herrn einen Altar und rief den Namen des Herrn an.',
        9: 'Dann zog Abram immer weiter nach dem Südland.',
        10: 'ES kam aber eine Hungersnot über das Land. Da zog Abram nach Ägypten hinab, um dort eine Weile zu verbleiben; denn die Hungersnot lastete schwer auf dem Lande.',
        11: 'Und da er sich Ägypten nahte, sprach er zu seinem Weibe Sarai: Ich weiss recht wohl, dass du ein schönes Weib bist.',
        12: 'Wenn dich nun die Ägypter sehen, so werden sie denken: "Das ist sein Weib", und sie werden mich erschlagen und dich am Leben lassen.',
        13: 'So sage doch, du seiest meine Schwester, auf dass es mir um deinetwillen wohl gehe und ich durch dich am Leben bleibe.',
        14: 'Als nun Abram nach Ägypten kam, sahen die Ägypter, dass das Weib sehr schön war.',
        15: 'Und die Grossen des Pharao sahen sie und rühmten sie vor dem Pharao. Da wurde das Weib in den Palast des Pharao geholt.',
        16: 'Dem Abram aber tat er Gutes um ihretwillen: er bekam Schafe, Rinder und Esel, Sklaven und Sklavinnen, Eselinnen und Kamele.',
        17: 'Doch der Herr schlug den Pharao und sein Haus mit schweren Plagen um Sarais, des Weibes Abrams, willen.',
        18: 'Da liess der Pharao den Abram rufen und sprach: Was hast du mir da angetan! Warum hast du mich nicht wissen lassen, dass sie dein Weib ist?',
        19: 'Warum hast du gesagt, sie sei deine Schwester, sodass ich sie mir zum Weibe genommen habe? Nun, da hast du dein Weib, nimm sie und ziehe hin!',
        20: 'Und der Pharao entbot seinethalben Leute; die mussten ihn und sein Weib und alles, was er hatte, geleiten.',
    },
    13: {
        1: 'ALSO zog Abram mit seinem Weibe und mit all seiner Habe, mit ihm auch Lot, aus Ägypten in das Südland hinauf.',
        2: 'Abram aber war sehr reich an Vieh, an Silber und an Gold.',
        3: 'Und er wanderte weiter von Lagerplatz zu Lagerplatz, aus dem Südland bis nach Bethel, bis zu der Stätte, wo im Anfang sein Zelt gestanden hatte, zwischen Bethel und Ai, (a) 1Mo 12:8',
        4: 'an die Stätte des Altars, den er vordem daselbst gemacht hatte, und dort rief Abram den Namen des Herrn an.',
        5: 'Lot aber, der mit Abram zog, hatte auch Schafe, Rinder und Zelte.',
        6: 'Und das Land ertrug es nicht, dass sie beieinander blieben; denn ihre Habe war gross, und darum konnten sie nicht beieinander bleiben.',
        7: 'So kam es zum Streite zwischen den Hirten über Abrams Vieh und den Hirten über Lots Vieh. Damals aber wohnten die Kanaaniter und Pheresiter im Lande.',
        8: 'Da sprach Abram zu Lot: Lass doch nicht Zank sein zwischen mir und dir, zwischen meinen Hirten und deinen Hirten; wir sind ja Brüder.',
        9: 'Steht dir nicht das ganze Land offen? So trenne dich doch von mir. Willst du zur Linken, so gehe ich zur Rechten; oder willst du zur Rechten, so gehe ich zur Linken.',
        10: 'Da erhob Lot seine Augen und sah, dass die ganze Jordanaue ein wasserreiches Land war - ehe der Herr Sodom und Gomorrha zerstörte -, wie der Garten des Herrn, wie das Land Ägypten, bis nach Zoar hin.',
        11: 'Da erwählte sich Lot die ganze Jordanaue und brach auf nach Osten. So trennten sie sich voneinander:',
        12: 'Abram blieb im Lande Kanaan, Lot aber liess sich nieder in den Städten der Aue und zog mit seinen Zelten bis gegen Sodom.',
        13: 'Aber die Leute von Sodom waren arge Sünder und Frevler wider den Herrn.',
        14: 'Als sich nun Lot von Abram getrennt hatte, sprach der Herr zu Abram: Hebe deine Augen auf und schaue von der Stätte, da du stehst, gegen Mitternacht und gegen Mittag, gegen Morgen und gegen Abend.',
        15: 'Denn das ganze Land, das du siehst - dir will ich es geben und deinen Nachkommen für ewige Zeiten. (a) 1Mo 12:7',
        16: 'Und deine Nachkommen will ich mehren wie den Staub der Erde, sodass, wenn man den Staub der Erde zählen kann, man auch deine Nachkommen wird zählen können. (a) 1Mo 28:14',
        17: 'Auf, durchziehe das Land in die Länge und in die Breite; denn dir will ich es geben.',
        18: 'Da brach Abram mit seinen Zelten auf, zog hin und liess sich nieder bei der Terebinthe Mamres zu Hebron und baute daselbst dem Herrn einen Altar.',
    },
    14: {
        1: 'UND es begab sich zur Zeit Amraphels, des Königs von Sinear, Arjochs, des Königs von Ellasar, Kedor-Laomers, des Königs von Elam, und Thideals, des Königs von Gojim,',
        2: 'dass sie Krieg anfingen mit Bera, dem König von Sodom, Birsa, dem König von Gomorrha, Sineab, dem König von Adma, Semeber, dem König von Zeboim, und dem König von Bela - das ist Zoar;',
        3: 'diese alle kamen zusammen im Tale von Siddim - das ist das Salzmeer.',
        4: 'Zwölf Jahre waren sie Kedor-Laomer untertan gewesen, im dreizehnten Jahre waren sie abgefallen.',
        5: 'Im vierzehnten Jahre aber kamen Kedor-Laomer und die Könige, die mit ihm verbündet waren, und schlugen die Rephaiter in Astharoth-Karnaim, die Susiter in Ham, die Emiter in der Ebene von Kirjathaim',
        6: 'und die Horiter auf dem Gebirge Seir bis nach El-Paran, das am Rand der Wüste liegt.',
        7: 'Darnach kehrten sie um und kamen nach En-Mispat - das ist Kades - und schlugen das ganze Land der Amalekiter sowie die Amoriter, die in Hazazon-Thamar wohnten. (1) dieser Name bed. "Rechtsquell".',
        8: 'Aber der König von Sodom, der König von Gomorrha, der König von Adma, der König von Zeboim und der König von Bela - das ist Zoar - zogen aus und stellten sich im Tale von Siddim auf, mit ihnen zu streiten:',
        9: 'mit Kedor-Laomer, dem König von Elam, Thideal, dem König von Gojim, Amraphel, dem König von Sinear, und Arjoch, dem König von Ellasar - vier Könige mit den fünfen.',
        10: 'Das Tal von Siddim aber war voll Asphaltgruben. Als nun die Könige von Sodom und Gomorrha flohen, fielen sie dort hinein, und was übrigblieb, floh ins Gebirge.',
        11: 'Da nahmen sie alle Habe von Sodom und Gomorrha und alle Nahrungsmittel darin fort und zogen davon. (1) d.h. die Feinde.',
        12: 'Sie nahmen auch Lot, den Neffen Abrams, und seine Habe mit und zogen davon; der wohnte nämlich in Sodom.',
        13: 'Da kam einer, der entronnen war, und brachte dem Hebräer Abram Kunde; der weilte bei der Terebinthe des Amoriters Mamre, des Bruders Eskols und Aners. Diese waren Abrams Bundesgenossen.',
        14: 'Als nun Abram hörte, dass sein Verwandter gefangen sei, bewaffnete er seine erprobten Leute, die in seinem Haus gebornen Sklaven, 318 Mann, und jagte (den Feinden) nach bis Dan.',
        15: 'Und er teilte seine Leute, überfiel jene bei Nacht mit seinen Sklaven, schlug sie und jagte ihnen nach bis Hoba, das nördlich von Damaskus liegt.',
        16: 'Er brachte alle Habe zurück; auch seinen Verwandten Lot und dessen Habe brachte er zurück, ebenso die Frauen und das Volk.',
        17: 'Als nun Abram von seinem Siege über Kedor-Laomer und die mit ihm verbündeten Könige zurückkam, ging der König von Sodom ihm entgegen in das Tal Sawe - das ist das Königstal.',
        18: 'Melchisedek aber, der König von Salem, brachte Brot und Wein heraus; er war ein Priester des höchsten Gottes. (a) Ps 110:4',
        19: 'Und er segnete ihn und sprach: Gesegnet ist Abram vom höchsten Gott, dem Schöpfer des Himmels und der Erde,',
        20: 'und gepriesen der höchste Gott, der deine Feinde in deine Hand gegeben hat! Und Abram gab ihm den Zehnten von allem.',
        21: 'Da sprach der König von Sodom zu Abram: Gib mir die Leute; die Habe behalte für dich.',
        22: 'Abram aber sprach zum König von Sodom: Ich hebe meine Hand auf zu dem Herrn, dem höchsten Gott, dem Schöpfer des Himmels und der Erde:',
        23: 'Nicht einen Faden noch Schuhriemen, nichts von allem, was dein ist, will ich behalten, dass du nicht sagest, du habest Abram reich gemacht.',
        24: 'Nichts will ich! nur was die Leute gegessen haben, und den Anteil der Männer, die mit mir gezogen sind; Aner, Eskol und Mamre, die mögen ihren Anteil bekommen.',
    },
    15: {
        1: 'DARNACH erging an Abram in einem Gesichte das Wort des Herrn: Fürchte dich nicht, Abram, ich bin dein Schild; dein wartet reicher Lohn.',
        2: 'Abram aber sprach: O Herr, mein Gott, was wolltest du mir geben? Muss ich doch von hinnen gehen ohne Kinder, und Erbe meines Hauses wird Elieser von Damaskus!',
        3: 'Und Abram sprach: Mir hast du ja keine Kinder gegeben; so wird mein Haussklave mich beerben.',
        4: 'Aber siehe, es erging an ihn das Wort des Herrn: Nicht er soll dein Erbe sein, sondern dein eigner leiblicher Sohn, der soll dein Erbe sein.',
        5: 'Und er führte ihn hinaus und sprach: Schaue gen Himmel und zähle die Sterne - ob du sie zählen kannst? Und er verhiess ihm: So sollen deine Nachkommen sein. (a) 1Mo 22:17',
        6: 'Abram glaubte dem Herrn, und das rechnete er ihm als Gerechtigkeit an.',
        7: 'Und Gott sprach zu ihm: Ich bin der Herr, der dich aus Ur in Chaldäa herausgeführt hat, dass ich dir dieses Land zu eigen gebe.',
        8: 'Er aber sprach: O Herr, mein Gott, woran soll ich erkennen, dass ich es besitzen werde?',
        9: 'Da gebot er ihm: Bringe mir eine dreijährige Kuh, eine dreijährige Ziege, einen dreijährigen Widder, eine Turteltaube und eine junge Taube.',
        10: 'Und er brachte ihm die Tiere alle, schnitt sie mitten entzwei und legte je einen Teil dem andern gegenüber; die Vögel aber zerschnitt er nicht.',
        11: 'Und die Raubvögel stiessen auf die Toten Tiere herab, doch Abram scheuchte sie weg.',
        12: 'Als nun die Sonne sich zum Untergange neigte, fiel ein Tiefschlaf auf Abram, und siehe, grosser Schrecken überfiel ihn.',
        13: 'Da sprach Gott zu Abram: Du sollst wissen, dass dein Geschlecht als Fremdling weilen wird in einem Lande, das nicht sein ist; und sie werden daselbst Sklaven sein, und man wird sie drücken, vierhundert Jahre lang. (a) 2Mo 1:13; 12:40',
        14: 'Doch will ich auch über das Volk, dem sie dienen müssen, Gericht halten. Darnach werden sie mit reicher Habe ausziehen.',
        15: 'Du aber sollst in Frieden zu deinen Vätern eingehen und in hohem Alter begraben werden. (a) 1Mo 25:8',
        16: 'Erst das vierte Geschlecht wird hierher zurückkehren; denn noch ist nicht voll die Schuld der Amoriter.',
        17: 'Als nun die Sonne untergegangen und es ganz finster geworden war, siehe da! ein rauchender Ofen und eine Feuerfackel, das fuhr zwischen diesen Stücken hin.',
        18: 'An jenem Tage schloss der Herr mit Abram einen Bund und sprach: Deinem Geschlechte gebe ich dieses Land, vom Bach Ägyptens bis an den grossen Strom, den Euphratstrom; (a) 1Kön 5:1',
        19: 'die Keniter, die Kenissiter und die Kadmoniter,',
        20: 'die Hethiter, die Pheresiter und die Rephaiter,',
        21: 'die Amoriter, die Kanaaniter, die Girgasiter und die Jebusiter.',
    },
    16: {
        1: 'SARAI, Abrams Weib, hatte ihm kein Kind geboren. Nun hatte sie eine ägyptische Magd, die hiess Hagar.',
        2: 'Und Sarai sprach zu Abram: Der Herr hat mir nun einmal Kinder versagt. So gehe denn zu meiner Magd; vielleicht, dass ich durch sie einen Sohn bekomme. Und Abram hörte auf Sarai.',
        3: 'Da nahm Sarai, Abrams Weib, die Ägypterin Hagar, ihre Magd, nachdem Abram zehn Jahre im Lande Kanaan gewohnt hatte, und gab sie ihrem Manne Abram zum Weibe.',
        4: 'Und er ging zu Hagar, und sie ward schwanger. Als sie nun merkte, dass sie schwanger war, sah sie auf ihre Herrin herab.',
        5: 'Da sprach Sarai zu Abram: Das Unrecht, das mir geschieht, komme über dich! Ich selbst habe dir meine Magd in die Arme gelegt. Nun, da sie sich schwanger weiss, sieht sie auf mich herab. Der Herr sei Richter zwischen mir und dir!',
        6: 'Abram aber sprach zu Sarai: Nun, deine Magd ist ja in deiner Gewalt; mache mit ihr, was dir gefällt. Da nun Sarai sie hart behandelte, entfloh sie ihr.',
        7: 'Da traf sie der Engel des Herrn am Wasserquell in der Wüste, am Quell auf dem Wege nach Sur,',
        8: 'und sprach: Hagar, Magd Sarais, wo kommst du her und wo willst du hin? Sie antwortete: Vor meiner Herrin Sarai fliehe ich.',
        9: 'Aber der Engel des Herrn sprach zu ihr: Kehre zurück zu deiner Herrin und ertrage ihre Härte.',
        10: 'Und er gab ihr die Verheissung: Zahlreich machen will ich dein Geschlecht, dass man vor Menge es nicht zählen kann.',
        11: 'Weiter sprach der Engel des Herrn zu ihr: Siehe, du bist schwanger und wirst einen Sohn gebären, den sollst du Ismael nennen, weil der Herr gehört hat, wie du littest. (1) d.i. Gott hört.',
        12: 'Er wird ein Mensch sein wie ein Wildesel - seine Hand wider jedermann und jedermanns Hand wider ihn; und allen seinen Brüdern setzt er sich vors Gesicht. (a) 1Mo 21:20; 25:18',
        13: 'Und sie nannte den Namen des Herrn, der mit ihr redete: Du bist der El-Roi. Denn, sprach sie, wahrlich, hier habe ich dem nachgeschaut, der mich erschaute. (1) d.i. Gott des Schauens.',
        14: 'Darum nennt man diesen Quell den Quell von Lahai-Roi; der liegt zwischen Kades und Bered.',
        15: 'Und Hagar gebar dem Abram einen Sohn, und Abram nannte den Sohn, den Hagar ihm geboren hatte, Ismael.',
        16: 'Abram war 86 Jahre alt, als Hagar ihm den Ismael gebar.',
    },
    17: {
        1: 'ALS Abram 99 Jahre alt war, erschien ihm der Herr und sprach zu ihm: Ich bin der allmächtige Gott, wandle vor mir, dann wirst du unsträflich sein,',
        2: 'und ich will einen Bund stiften zwischen mir und dir und will dich über alle Massen mehren.',
        3: 'Da warf sich Abram auf sein Angesicht, und Gott redete mit ihm und sprach:',
        4: 'Siehe, das ist mein Bund mit dir, dass du ein Vater vieler Völker werden sollst.',
        5: 'Darum sollst du nicht mehr Abram heissen, sondern Abraham soll dein Name sein; denn ich mache dich zum Vater vieler Völker. (1) der Erzähler hörte aus dem Namen Abraham etwas wie "Vater der Menge" heraus.',
        6: 'Ich will dich über alle Massen fruchtbar machen und dich zu Völkern werden lassen, und Könige sollen von dir abstammen. (a) 1Mo 35:11',
        7: 'Ich richte meinen Bund auf zwischen mir und dir und deinen Nachkommen von Geschlecht zu Geschlecht als einen ewigen Bund, dass ich dein und deiner Nachkommen Gott sei.',
        8: 'Und ich gebe dir und deinen Nachkommen das Land, wo du als Fremdling weilst, das ganze Land Kanaan, zu ewigem Besitz, und ich will ihnen Gott sein.',
        9: 'Und Gott sprach zu Abraham: Du aber halte meinen Bund, du und deine Nachkommen, Geschlecht für Geschlecht.',
        10: 'Das aber ist der Bund zwischen mir und euch und deinen Nachkommen, den ihr halten sollt: Alles, was männlich ist unter euch, das soll beschnitten werden.',
        11: 'An der Vorhaut sollt ihr beschnitten werden. Das soll ein Zeichen sein des Bundes zwischen mir und euch.',
        12: 'Im Alter von acht Tagen soll alles, was männlich ist unter euch, beschnitten werden, Geschlecht für Geschlecht. (Auch der Sklave,) der im Haus geborne wie der von irgendeinem Fremden um Geld gekaufte, der nicht deines Stammes ist: (a) 3Mo 12:3',
        13: 'beide sollen beschnitten werden, der in deinem Haus geborne wie der von dir um Geld gekaufte. Das soll mein Bund an eurem Leibe sein, ein ewiger Bund.',
        14: 'Ein Unbeschnittener aber - nämlich was männlich ist und unbeschnitten bleibt an der Vorhaut -, dessen Seele soll aus seinen Volksgenossen ausgerottet werden: meinen Bund hat er gebrochen.',
        15: 'Und Gott sprach zu Abraham: Dein Weib Sarai sollst du nicht mehr Sarai nennen, sondern Sara soll ihr Name sein. (1) d.i. Fürstin.',
        16: 'Ich will sie segnen, und auch von ihr gebe ich dir einen Sohn; ich will sie segnen, und sie soll zu Völkern werden, und Könige von Nationen sollen von ihr kommen.',
        17: 'Da warf sich Abraham auf sein Angesicht und lachte und sprach bei sich selbst: Einem Hundertjährigen sollte noch (ein Sohn) geboren werden? und Sara sollte mit neunzig Jahren noch gebären?',
        18: 'Und Abraham sprach zu Gott: Ach, möchte nur Ismael vor dir am Leben bleiben!',
        19: 'Da sprach Gott: Vielmehr, dein Weib Sara soll dir einen Sohn gebären, den sollst du Isaak nennen, und ich will meinen Bund mit ihm aufrichten als einen ewigen Bund, dass ich sein Gott und seiner Nachkommen Gott sei. (a) 1Mo 21:2',
        20: 'Aber auch wegen Ismaels erhöre ich dich: Siehe, ich segne ihn und mache ihn fruchtbar und überaus zahlreich; zwölf Fürsten wird er zeugen, und ich will ihn zu einem grossen Volke machen. (a) 1Mo 25:16',
        21: 'Meinen Bund aber will ich aufrichten mit Isaak, den dir Sara gebären wird um diese Zeit im nächsten Jahr.',
        22: 'Als Gott mit Abraham zu Ende geredet hatte, fuhr er auf von ihm.',
        23: 'Da nahm Abraham seinen Sohn Ismael und alle Sklaven, die in seinem Hause geboren, und alle, die von ihm um Geld gekauft waren, alles, was männlich war unter seinen Hausgenossen, und beschnitt ihre Vorhaut noch am selben Tage, wie ihm Gott geboten hatte.',
        24: 'Abraham war 99 Jahre alt, als er an der Vorhaut beschnitten wurde.',
        25: 'Sein Sohn Ismael aber war dreizehn Jahre alt, als er an der Vorhaut beschnitten wurde.',
        26: 'Noch am selben Tage wurden Abraham und sein Sohn Ismael beschnitten,',
        27: 'und alles, was männlich war in seinem Hause, der im Haus geborne wie der von Fremden um Geld gekaufte (Sklave), wurde mit ihm beschnitten.',
    },
    18: {
        1: 'UND der Herr erschien ihm bei der Terebinthe Mamres, während er am Eingang seines Zeltes sass, als der Tag am heissesten war.',
        2: 'Wie er nun seine Augen erhob und sich umschaute, siehe, da standen drei Männer vor ihm. Sobald er sie sah, eilte er ihnen vom Eingang seines Zeltes entgegen, verneigte sich zur Erde',
        3: 'und sprach: Mein Herr, habe ich Gnade gefunden vor deinen Augen, so gehe doch nicht an deinem Knechte vorüber.',
        4: 'Man soll ein wenig Wasser bringen, dass ihr euch die Füsse waschet, dann lagert euch unter dem Baume,',
        5: 'und ich will einen Bissen Brot holen, dass ihr euch erlabet; darnach mögt ihr weiterziehen. Ihr seid nun einmal bei eurem Knecht vorbeigekommen. Sie sprachen: Du magst tun, wie du gesagt hast.',
        6: 'Nun eilte Abraham ins Zelt zu Sara und sprach: Nimm schnell drei Scheffel Mehl! Knete es und backe Kuchen!',
        7: 'Auch zu den Rindern lief Abraham, holte ein zartes, schönes Kalb und gab es dem Knechte; der rüstete es eilends zu.',
        8: 'Dann nahm er Sauermilch und frische Milch und das Kalb, das er gerüstet hatte, und setzte es ihnen vor; er selbst aber wartete ihnen auf unter dem Baume, und sie assen.',
        9: 'Da sprachen sie zu ihm: Wo ist dein Weib Sara? Er antwortete: Da drinnen im Zelte.',
        10: 'Da sprach er: Ich werde wieder zu dir kommen übers Jahr um diese Zeit; dann hat dein Weib Sara einen Sohn. Sara aber hörte zu am Eingang des Zeltes hinter ihm.',
        11: 'Nun waren Abraham und Sara alt und hochbetagt, sodass es Sara nicht mehr nach der Frauen Weise ging.',
        12: 'Darum lachte Sara bei sich selbst und dachte: Nun ich welk bin, soll mich noch Liebeslust ankommen? Und auch mein Herr ist alt.',
        13: 'Da sprach der Herr zu Abraham: Warum lacht denn Sara und denkt: "Sollte ich wirklich noch Mutter werden können, da ich doch alt bin?"',
        14: 'Ist denn irgend etwas unmöglich für den Herrn? Übers Jahr um diese Zeit werde ich wieder zu dir kommen; dann hat Sara einen Sohn. (a) Lu 1:37',
        15: 'Sara leugnete und sprach: Ich habe nicht gelacht. Denn sie fürchtete sich. Aber er sprach: Doch, du hast gelacht!',
        16: 'Da erhoben sich die Männer und gingen von dannen. UND schon schauten sie hinab auf Sodom, während Abraham noch mit ihnen ging, um ihnen das Geleit zu geben.',
        17: 'Der Herr aber dachte: Soll ich vor Abraham geheimhalten, was ich tun will? (a) Am 3:7',
        18: 'Abraham soll doch ein grosses und starkes Volk werden, und alle Völker der Erde werden sich mit seinem Namen Segen wünschen. (1) vgl. Anm. zu 1Mo 12:2 3.',
        19: 'Denn ich habe ihn erkoren, dass er seinen Söhnen und seinem Hause nach ihm befehle, den Weg des Herrn zu beobachten und Gerechtigkeit und Recht zu üben, damit der Herr über Abraham kommen lasse, was er ihm verheissen hat.',
        20: 'Und der Herr sprach: Das Geschrei über Sodom und Gomorrha, das ist gross, und ihre Sünde, die ist gar schwer.',
        21: 'Darum will ich hinab und sehen, ob sie wirklich ganz so gehandelt haben, wie das Geschrei über sie verlautet, das zu mir gedrungen ist, oder nicht; das will ich erfahren!',
        22: 'Und die Männer wandten sich von dannen und gingen Sodom zu; Abraham aber blieb noch vor dem Herrn stehen.',
        23: 'Und Abraham trat herzu und sprach: Willst du mit dem Gottlosen auch den Gerechten wegraffen? (a) 4Mo 16:22',
        24: 'Vielleicht sind fünfzig Gerechte in der Stadt; willst du die auch wegraffen und nicht lieber dem Ort vergeben wegen der fünfzig Gerechten darin?',
        25: 'Ferne sei es von dir, solches zu tun, den Gerechten mit dem Gottlosen zu töten, dass es dem Gerechten erginge wie dem Gottlosen! Das sei ferne von dir! Der aller Welt Richter ist, sollte der nicht Recht üben?',
        26: 'Der Herr sprach: Finde ich zu Sodom fünfzig Gerechte in der Stadt, so will ich um ihretwillen dem ganzen Ort vergeben.',
        27: 'Abraham aber hob von neuem an und sprach: Ach, ich habe mich unterfangen, mit meinem Herrn zu reden, wiewohl ich Staub und Asche bin.',
        28: 'Vielleicht sind es fünf weniger als fünfzig Gerechte; willst du dann die ganze Stadt verderben um der fünfe willen? Er sprach: Finde ich fünfundvierzig darin, so will ich sie nicht verderben.',
        29: 'Und abermals redete er mit ihm und sprach: Vielleicht sind nur vierzig darin zu finden. Er sprach: Ich will es nicht tun, um der vierzig willen.',
        30: 'Er sprach: Mein Herr zürne nicht, wenn ich nochmals rede. Vielleicht sind nur dreissig darin zu finden. Er sprach: Finde ich dreissig darin, so will ich es nicht tun.',
        31: 'Er sprach: Ach, ich habe mich unterfangen, mit meinem Herrn zu reden; vielleicht sind nur zwanzig darin zu finden. Er sprach: Ich will sie nicht verderben, um der zwanzig willen.',
        32: 'Er sprach: Mein Herr zürne nicht, wenn ich noch diesmal rede. Vielleicht sind nur zehn darin zu finden. Er sprach: Ich will sie nicht verderben, um der zehne willen.',
        33: 'Dann ging der Herr hinweg, als er mit Abraham zu Ende geredet hatte. Abraham aber kehrte zurück an seinen Ort.',
    },
    19: {
        1: 'UND die zwei Engel kamen am Abend nach Sodom, als Lot gerade im Tore von Sodom sass. Sobald er sie sah, stand er auf, ging ihnen entgegen, verneigte sich mit dem Angesicht zur Erde',
        2: 'und sprach: Ach, ihr Herren, kehrt doch im Hause eures Knechtes ein und bleibt übernacht und waschet eure Füsse; morgen früh mögt ihr dann eures Weges ziehen. Sie aber sprachen: Nein, wir wollen da auf dem Platze übernacht bleiben.',
        3: 'Da er aber sehr in sie drang, kehrten sie bei ihm ein und kamen in sein Haus. Und er rüstete ihnen ein Mahl und buk ungesäuerte Kuchen, und sie assen.',
        4: 'Doch ehe sie sich schlafen legten, hatten schon die Männer der Stadt, die Männer von Sodom, jung und alt, alle insgesamt, das Haus umzingelt.',
        5: 'Und sie riefen Lot und sprachen zu ihm: Wo sind die Männer, die heute abend zu dir gekommen sind? Bringe sie zu uns heraus, dass wir ihnen beiwohnen.',
        6: 'Da trat Lot zu ihnen hinaus vor die Türe und schloss hinter sich zu',
        7: 'und sprach: Ach, liebe Brüder, tut doch nichts Schlechtes!',
        8: 'Seht, ich habe zwei Töchter, die noch nichts vom Manne wissen, die will ich euch herausgeben; macht mit ihnen, was euch gefällt. Nur diesen Männern tut nichts; denn sie sind nun einmal unter den Schatten meines Daches getreten.',
        9: 'Sie aber schrieen: Weg mit dir! und sagten: Kommt der da ganz allein als Fremdling her und will den Richter spielen! Nun, wir wollen dir Schlimmeres antun als ihnen. So drangen sie mit Gewalt auf den Mann, auf Lot, ein und machten sich daran, die Türe zu erbrechen.',
        10: 'Aber die Männer streckten die Hand aus und zogen Lot zu sich ins Haus herein, und die Türe schlossen sie zu.',
        11: 'Die Leute vor der Haustüre aber schlugen sie mit Blindheit, klein und gross, sodass sie sich umsonst abmühten, die Türe zu finden. (a) 2Kön 6:18',
        12: 'Dann sprachen die Männer zu Lot: Hast du noch jemand hier? Deine Söhne und Töchter, und wer in der Stadt dir angehört, die führe hinweg aus diesem Orte.',
        13: 'Denn wir werden diese Stadt verderben, weil lautes Geschrei über sie vor den Herrn gekommen ist; und so hat uns der Herr gesandt, sie zu verderben.',
        14: 'Da ging Lot hinaus und redete mit seinen Tochtermännern, die seine Töchter heiraten wollten, und sprach: Auf, geht hinweg aus diesem Orte! Denn der Herr wird diese Stadt verderben. Aber seine Tochtermänner glaubten, er scherze.',
        15: 'Als nun die Morgenröte heraufkam, trieben die Engel Lot zur Eile an und sprachen: Auf, nimm dein Weib und deine beiden Töchter, die hier sind, dass du nicht weggerafft werdest durch die Schuld der Stadt.',
        16: 'Da er aber noch zögerte, ergriffen die Männer ihn und sein Weib und seine beiden Töchter bei der Hand, weil der Herr ihn verschonen wollte, führten ihn hinaus und liessen ihn draussen vor der Stadt.',
        17: 'Und als sie dieselben hinausgeführt hatten, sprach er: Rette dich! es gilt dein Leben! Sieh nicht hinter dich und bleibe nirgends stehen im ganzen Umkreis! Ins Gebirge rette dich, dass du nicht weggerafft werdest!',
        18: 'Aber Lot sprach zu ihm: Ach nein, Herr!',
        19: 'Dein Knecht hat ja doch Gnade gefunden vor deinen Augen, und du hast mir grosse Barmherzigkeit erwiesen, dass du mich am Leben erhalten hast. Aber ins Gebirge kann ich mich nicht retten; es könnte das Verderben mich ereilen, dass ich sterben müsste.',
        20: 'Siehe, die Stadt da ist nahe, sodass ich dahin fliehen könnte; und sie ist ja klein. Ach, lass mich dahin fliehen! Ist die Stadt nicht klein? So könnte ich am Leben bleiben.',
        21: 'Da sprach er zu ihm: Siehe, ich will dir auch in diesem Stück willfahren und die Stadt nicht zerstören, von der du geredet hast.',
        22: 'Schnell, rette dich dorthin; denn ich kann nichts tun, bis du dort hineingekommen bist. Daher heisst die Stadt Zoar. (1) d.i. Kleinheit.',
        23: 'Und eben, als die Sonne über der Erde aufgegangen war, kam Lot nach Zoar.',
        24: 'Der Herr aber liess Schwefel und Feuer auf Sodom und Gomorrha regnen, von dem Herrn vom Himmel herab, (a) 5Mo 29:23; Jes 13:19',
        25: 'und vernichtete so die Städte und den ganzen Umkreis und alle Bewohner der Städte und was auf dem Lande gewachsen war.',
        26: 'Lots Weib aber sah sich hinter ihm um und ward zur Salzsäule.',
        27: 'Am andern Morgen in der Frühe machte sich Abraham auf an den Ort, wo er vor dem Herrn gestanden hatte,',
        28: 'und schaute hinab auf Sodom und Gomorrha und auf das ganze umliegende Land. Da sah er den Qualm aufsteigen von dem Lande, wie Qualm von einem Schmelzofen.',
        29: 'Und als Gott die Städte in der Niederung vernichtete, da gedachte er Abrahams, und er geleitete Lot hinweg aus der Zerstörung, als er die Städte zerstörte, in denen Lot gewohnt hatte.',
        30: 'Lot aber zog von Zoar hinauf und liess sich mit seinen beiden Töchtern im Gebirge nieder; denn er fürchtete sich, in Zoar zu bleiben. Und er wohnte mit seinen Töchtern in einer Höhle.',
        31: 'Da sprach die ältere zur jüngern: Unser Vater ist alt, und es ist kein Mann mehr im Lande, der zu uns kommen könnte nach aller Welt Brauch.',
        32: 'Komm, wir wollen unserm Vater Wein zu trinken geben und uns zu ihm legen, dass wir durch unsern Vater unsern Stamm erhalten.',
        33: 'Also gaben sie in jener Nacht ihrem Vater Wein zu trinken. Dann ging die ältere hinein und legte sich zu ihrem Vater, und er merkte nichts davon, weder wie sie sich hinlegte, noch wie sie aufstand.',
        34: 'Am Morgen sprach die ältere zur jüngern: Sieh, ich habe gestern bei meinem Vater gelegen. Nun wollen wir ihm auch heute nacht Wein zu trinken geben; dann geh du hinein und lege dich zu ihm, dass wir durch unsern Vater unsern Stamm erhalten.',
        35: 'Also gaben sie ihrem Vater auch in jener Nacht Wein zu trinken. Dann stand die jüngere auf und legte sich zu ihm, und er merkte nichts davon, weder wie sie sich hinlegte, noch wie sie aufstand.',
        36: 'So wurden die beiden Töchter Lots schwanger von ihrem Vater.',
        37: 'Und die ältere gebar einen Sohn und nannte ihn Moab; der ist der Stammvater der Moabiter bis auf den heutigen Tag. (1) Meab = vom Vater.',
        38: 'Und auch die jüngere gebar einen Sohn und nannte ihn Ben-Ammi; der ist der Stammvater der Ammoniter bis auf den heutigen Tag. (1) d.i. Sohn meines Verwandten.',
    },
    20: {
        1: 'ABRAHAM aber zog von dort in das Gebiet des Südlands und blieb zwischen Kades und Sur. Als er nun in Gerar weilte,',
        2: 'sagte er von seinem Weibe Sara: Sie ist meine Schwester. Da sandte Abimelech, der König von Gerar, hin und liess Sara holen.',
        3: 'Des Nachts aber kam Gott zu Abimelech im Traum und sprach zu ihm: Fürwahr, du bist des Todes um des Weibes willen, das du genommen hast; denn sie ist ein Eheweib.',
        4: 'Abimelech jedoch hatte sie noch nicht berührt, und so sprach er: Herr, willst du wirklich Unschuldige umbringen?',
        5: 'Hat er nicht selbst zu mir gesagt: "Sie ist meine Schwester"? Und auch sie hat gesagt: "Er ist mein Bruder." In aller Unschuld und mit reinen Händen habe ich das getan.',
        6: 'Da antwortete ihm Gott im Traum: Auch ich weiss wohl, dass du das in aller Unschuld getan hast, und ich selber habe dich davor behütet, dich an mir zu versündigen; darum habe ich dir nicht gestattet, sie zu berühren.',
        7: 'So gib nun dem Manne sein Weib zurück, denn er ist ein Prophet, und er wird dann für dich bitten, sodass du am Leben bleibst. Gibst du sie aber nicht zurück, so wisse, dass du mit all den Deinen sterben musst.',
        8: 'Am andern Morgen rief Abimelech alsbald seine Knechte und erzählte ihnen alles, was sich zugetragen hatte; und die Leute fürchteten sich sehr.',
        9: 'Dann liess Abimelech den Abraham rufen und sprach zu ihm: Was habe ich dir getan, und womit habe ich an dir gesündigt, dass du so grosse Sünde über mich und mein Reich gebracht hast? Du hast an mir gehandelt, wie man nicht handeln soll.',
        10: 'Und weiter sprach Abimelech zu Abraham: Was hast du denn beabsichtigt, dass du das getan hast?',
        11: 'Abraham antwortete: Ich dachte eben: es gibt sicher keine Gottesfurcht an diesem Orte, und so werden sie mich umbringen um meines Weibes willen.',
        12: 'Auch ist sie wirklich meine Schwester, die Tochter meines Vaters, nur nicht die Tochter meiner Mutter; so konnte sie mein Weib werden.',
        13: 'Als mich nun Gott aus meines Vaters Hause in die Ferne wandern hiess, sprach ich zu ihr: Das musst du mir zuliebe tun, dass du überall, wohin wir kommen, von mir sagst, ich sei dein Bruder.',
        14: 'Da nahm Abimelech Schafe und Rinder, Sklaven und Sklavinnen und schenkte sie Abraham; und sein Weib Sara gab er ihm zurück.',
        15: 'Und Abimelech sprach: Sieh, mein Land steht dir offen; bleibe, wo es dir gefällt.',
        16: 'Zu Sara aber sprach er: Sieh, da schenke ich deinem Bruder tausend Lot Silber; das soll eine Ehrenrettung für dich sein vor allen, die bei dir sind, und so bist du vor jedermann gerechtfertigt.',
        17: 'Nun betete Abraham zu Gott, und Gott heilte Abimelech, sein Weib und seine Mägde, dass sie Kinder bekamen.',
        18: 'Der Herr hatte nämlich jeden Mutterschoss im Hause Abimelechs verschlossen, um Saras, des Weibes Abrahams, willen.',
    },
    21: {
        1: 'DER Herr aber nahm sich Saras an, wie er verheissen hatte, und tat an ihr nach seinem Worte: (a) 1Mo 18:10 14',
        2: 'Sara ward schwanger und gebar dem Abraham in seinem Alter einen Sohn, um die Zeit, die Gott angekündigt hatte. (a) 1Mo 18:10 14',
        3: 'Und Abraham nannte den Sohn, der ihm von Sara geboren worden war, Isaak.',
        4: 'Am achten Tage aber beschnitt Abraham seinen Sohn Isaak, wie ihm Gott geboten hatte. (a) 1Mo 17:11 12',
        5: 'Abraham war hundert Jahre alt, als ihm sein Sohn Isaak geboren wurde.',
        6: 'Da sprach Sara: Ein Lachen hat mir Gott bereitet! Wer davon hört, wird über mich lachen.',
        7: 'Und sie sprach: Wer hat je dem Abraham verkünden können, dass Sara Kinder stillt? Und doch habe ich ihm in seinem Alter einen Sohn geboren!',
        8: 'Und das Kind wuchs und ward entwöhnt; und Abraham veranstaltete ein grosses Mahl an dem Tage, da Isaak entwöhnt ward.',
        9: 'Als nun Sara den Sohn der Ägypterin Hagar, den diese dem Abraham geboren hatte, mit ihrem Sohne Isaak spielen sah,',
        10: 'sprach sie zu Abraham: Jage die Magd da mit ihrem Sohne fort; denn der Sohn dieser Magd soll nicht Erbe werden mit meinem Sohn, mit Isaak.',
        11: 'Dieses Wort missfiel Abraham sehr um seines Sohnes willen.',
        12: "Aber Gott sprach zu Abraham: Lass dir's nicht leid sein um den Knaben und um deine Magd. In allem, was Sara zu dir sagt, höre auf sie. Denn nur nach Isaak soll dein Geschlecht benannt werden.",
        13: 'Doch auch den Sohn der Magd will ich zu einem Volke machen, weil er deines Stammes ist.',
        14: 'Am andern Morgen in der Frühe nahm Abraham Brot und einen Schlauch voll Wasser und gab es Hagar, den Knaben aber setzte er ihr auf die Schulter; so schickte er sie fort. Da ging sie hin und irrte in der Wüste von Beerseba umher.',
        15: 'Als nun das Wasser in dem Schlauche ausgegangen war, warf sie den Knaben unter einen Strauch,',
        16: 'ging hin und setzte sich gegenüber, etwa einen Bogenschuss weit. Denn sie sprach: Ich kann den Tod des Knaben nicht mitansehen. So sass sie ihm gegenüber; der Knabe aber begann laut zu weinen.',
        17: 'Da hörte Gott die Stimme des Knaben, und der Engel Gottes rief der Hagar vom Himmel zu und sprach zu ihr: Was hast du, Hagar? Fürchte dich nicht; denn Gott hat die Stimme des Knaben gehört, dort wo er liegt.',
        18: 'Stehe auf, nimm den Knaben und halte ihn fest an der Hand; denn zu einem grossen Volke will ich ihn machen.',
        19: 'Und Gott öffnete ihr die Augen, dass sie einen Wasserquell sah. Da ging sie hin, füllte den Schlauch mit Wasser und gab dem Knaben zu trinken.',
        20: 'Und Gott war mit dem Knaben: er wuchs auf und wohnte in der Wüste und ward ein Bogenschütze.',
        21: 'Er wohnte in der Wüste Paran, und seine Mutter nahm ihm ein Weib aus dem Lande Ägypten.',
        22: 'ZU derselben Zeit sprachen Abimelech und sein Feldhauptmann Pichol zu Abraham: Gott ist mit dir in allem, was du tust.',
        23: 'So schwöre mir nun bei Gott, dass du weder an mir noch an meinen Kindern und Kindeskindern treulos handeln willst; sondern die Freundschaft, die ich dir erwiesen habe, sollst du auch mir erweisen und dem Lande, darin du als Fremdling weilst.',
        24: 'Da sprach Abraham: Ich schwöre.',
        25: 'Abraham aber stellte den Abimelech zur Rede wegen des Wasserquells, den Abimelechs Knechte mit Gewalt genommen hatten.',
        26: 'Abimelech entgegnete: Ich weiss nicht, wer das getan hat; du hast mir nichts davon gesagt, und ich habe auch bis heute nichts davon gehört.',
        27: 'Da nahm Abraham Schafe und Rinder und gab sie Abimelech, und sie schlossen miteinander einen Bund.',
        28: 'Als nun Abraham sieben Lämmer beiseite stellte,',
        29: 'fragte Abimelech den Abraham: Was sollen diese sieben Lämmer hier, die du beiseite gestellt hast?',
        30: 'Er antwortete: Die sieben Lämmer musst du von mir annehmen, damit sie mir als Zeugnis dienen, dass ich diesen Brunnen gegraben habe.',
        31: 'Daher nannte man den Ort "Beer-Seba", weil sie einander dort geschworen haben. (1) d.i. Schwurbrunnen.',
        32: 'So schlossen sie einen Bund zu Beerseba. Dann machte sich Abimelech mit seinem Feldhauptmann Pichol auf, und sie kehrten ins Philisterland zurück.',
        33: 'Abraham aber pflanzte in Beerseba eine Tamariske und rief daselbst den Namen des Herrn an, des ewigen Gottes.',
        34: 'Und er weilte noch lange Zeit als Fremdling im Philisterland.',
    },
    22: {
        1: 'NACH diesen Begebenheiten wollte Gott den Abraham prüfen. Er sprach zu ihm: Abraham! Er antwortete: Hier bin ich!',
        2: 'Er sprach: Nimm deinen Sohn, deinen einzigen, den du liebhast, den Isaak, und gehe hin ins Land Moria und opfere ihn daselbst als Brandopfer auf einem der Berge, den ich dir nennen werde.',
        3: 'Da bepackte Abraham am andern Morgen in der Frühe seinen Esel und nahm seine beiden Knechte und seinen Sohn Isaak mit sich; und er spaltete das Holz zum Brandopfer, machte sich auf und ging an den Ort, den ihm Gott genannt hatte.',
        4: 'Am dritten Tage, als Abraham seine Augen erhob, sah er die Stätte von ferne.',
        5: 'Da sprach Abraham zu seinen Knechten: Bleibet ihr hier mit dem Esel, ich aber und der Knabe wollen dorthin gehen, und wenn wir angebetet haben, wollen wir zu euch zurückkommen.',
        6: 'Dann nahm Abraham das Holz zum Brandopfer und lud es seinem Sohne Isaak auf; er selbst nahm den Feuerbrand und das Messer, und so gingen die beiden miteinander.',
        7: 'Da sprach Isaak zu seinem Vater Abraham: Vater! Abraham antwortete: Was willst du, mein Sohn? Er sprach: Siehe, hier ist wohl der Feuerbrand und das Holz; wo ist aber das Lamm zum Opfer?',
        8: 'Abraham antwortete: Gott wird sich das Lamm zum Opfer selbst ersehen, mein Sohn. So gingen die beiden miteinander.',
        9: 'Als sie nun an die Stätte kamen, die Gott ihm genannt hatte, baute Abraham daselbst den Altar und schichtete das Holz darauf; dann band er seinen Sohn Isaak und legte ihn auf den Altar, oben auf das Holz.',
        10: 'Hierauf streckte Abraham seine Hand aus und ergriff das Messer, um seinen Sohn zu schlachten.',
        11: 'Da rief ihm vom Himmel her der Engel des Herrn zu: Abraham, Abraham! Er antwortete: Hier bin ich!',
        12: 'Er sprach: Lege deine Hand nicht an den Knaben und tue ihm nichts; denn nun weiss ich, dass du Gott fürchtest: du hast deinen Sohn, deinen einzigen, mir nicht vorenthalten.',
        13: 'Wie nun Abraham seine Augen erhob, sah er einen Widder, der sich mit seinen Hörnern im Gebüsch verfangen hatte. Da ging Abraham hin, nahm den Widder und opferte ihn als Brandopfer anstatt seines Sohnes.',
        14: 'Und Abraham nannte die Stätte "Gottessicht"; daher man noch heutigen Tages sagt: auf dem Berge "Gottessicht".',
        15: 'Und der Engel des Herrn rief Abraham abermals zu vom Himmel her:',
        16: 'Ich schwöre bei mir selbst, spricht der Herr: weil du das getan und deinen Sohn, deinen einzigen, mir nicht vorenthalten hast,',
        17: 'darum will ich dich segnen und dein Geschlecht so zahlreich machen wie die Sterne des Himmels und wie den Sand am Gestade des Meeres, und dein Geschlecht wird das Tor seiner Feinde besitzen;',
        18: 'mit dem Namen deines Stammes werden sich Segen wünschen alle Völker der Erde, weil du mir gehorcht hast. (1) vgl. Anm. zu 1Mo 12:2 3.',
        19: 'Hierauf kehrte Abraham zu seinen Knechten zurück, und sie machten sich auf und zogen zusammen nach Beerseba, und Abraham blieb in Beerseba wohnen.',
        20: 'NACH diesen Begebenheiten ward dem Abraham gemeldet: Auch Milka hat deinem Bruder Nahor Söhne geboren:',
        21: 'seinen Erstgebornen Uz und dessen Bruder Bus, und Kemuel, den Vater Arams,',
        22: 'Chesed und Haso, Pildas, Jidlaph und Bethuel.',
        23: 'Bethuel aber hat die Rebekka gezeugt. Diese acht gebar Milka dem Nahor, dem Bruder Abrahams;',
        24: 'und seine Nebenfrau, mit Namen Rehuma, gebar auch Kinder: Tebah und Gaham, Thahas und Maacha.',
    },
    23: {
        1: 'SARA wurde 127 Jahre alt; so lange lebte sie.',
        2: 'Dann starb Sara in Kirjath-Arba - das ist Hebron - im Lande Kanaan. Da ging Abraham hinein, die Totenklage um Sara zu halten und sie zu beweinen.',
        3: 'Darnach stand Abraham auf von seiner Toten und sprach zu den Hethitern:',
        4: 'Ich bin bei euch ein Fremdling und Beisasse; gebt mir eine Grabstätte bei euch zu eigen, dass ich meine Tote hinausbringe und begrabe.',
        5: 'Die Hethiter antworteten dem Abraham:',
        6: 'Möchtest du uns doch anhören, Herr! Du bist ein Gottesfürst mitten unter uns; im besten unsrer Gräber magst du deine Tote begraben! Keiner von uns wird dir sein Grab verweigern, deine Tote darin zu begraben.',
        7: 'Da stand Abraham auf, verneigte sich tief vor den Leuten des Landes, den Hethitern,',
        8: 'und sprach zu ihnen: Ist es denn euer Wille, dass ich meine Tote hinausbringe und begrabe, so höret mich an und tretet für mich ein bei Ephron, dem Sohne Zohars,',
        9: 'dass er mir die Höhle Machpela gebe, die ihm gehört, am Ende seines Grundstücks; um gutes Geld gebe er sie mir unter euch als Grabstätte zu eigen.',
        10: 'Ephron aber sass mitten unter den Hethitern. Da antwortete der Hethiter Ephron dem Abraham vor den Hethitern, vor allen, die im Tore seiner Stadt erschienen waren, und sprach:',
        11: 'Möchtest du mich doch anhören, Herr! Ich schenke dir das Grundstück; auch die Höhle daselbst schenke ich dir, vor meinen Volksgenossen schenke ich sie dir. Begrabe nur deine Tote.',
        12: 'Da verneigte sich Abraham tief vor den Leuten des Landes',
        13: 'und sprach zu Ephron, dass die Leute des Landes es hörten: Doch nur, wenn du - bitte, höre mich an: ich bezahle das Geld für das Grundstück, nimm es von mir an; dann will ich meine Tote dort begraben.',
        14: 'Ephron aber antwortete dem Abraham:',
        15: 'Möchtest du mich doch anhören, Herr! Ein Stück Land, vierhundert Lot Silber wert, was bedeutet das zwischen mir und dir? Begrabe nur deine Tote.',
        16: 'Und Abraham willfahrte dem Ephron, und Abraham wog Ephron die Summe dar, die er vor den Hethitern genannt hatte: vierhundert Lot Silber nach dem im Handel üblichen Gewicht.',
        17: 'So wurde Ephrons Grundstück bei Machpela, gegenüber Mamre, das Grundstück samt der Höhle und allen Bäumen auf dem Grundstück in seinem ganzen Umfang, (a) 1Mo 25:9 10; 50:13',
        18: 'Abrahams Eigentum in Gegenwart der Hethiter, aller, die im Tore seiner Stadt erschienen waren.',
        19: 'Darnach begrub Abraham sein Weib Sara in der Höhle auf dem Grundstück Machpela gegenüber Mamre - das ist Hebron - im Lande Kanaan.',
        20: 'So ging das Grundstück samt der Höhle von den Hethitern als Grabstätte in Abrahams Besitz über.',
    },
    24: {
        1: 'ABRAHAM aber war alt geworden und hochbetagt, und der Herr hatte ihn in allem gesegnet.',
        2: 'Nun sprach Abraham zu dem ältesten Knechte seines Hauses, der Verwalter aller seiner Güter war: lege doch deine Hand unter meine Hüfte;',
        3: 'ich will dich schwören lassen bei dem Herrn, dem Gott des Himmels und dem Gott der Erde, dass du meinem Sohne kein Weib nehmest von den Töchtern der Kanaaniter, unter denen ich wohne, (a) 1Mo 28:1 2; 5Mo 7:3',
        4: 'sondern in mein Vaterland und zu meiner Verwandtschaft sollst du ziehen, ein Weib für meinen Sohn Isaak zu holen.',
        5: 'Da sprach der Knecht zu ihm: Wie? wenn mir das Weib in dieses Land nicht folgen will? Soll ich alsdann deinen Sohn in jenes Land zurückbringen, aus dem du weggezogen bist?',
        6: 'Abraham sprach zu ihm: Hüte dich wohl, meinen Sohn dorthin zurückzubringen!',
        7: 'Der Herr, der Gott des Himmels, der mich aus meines Vaters Hause und aus dem Lande meiner Verwandtschaft genommen, der mit mir geredet und mir geschworen hat: "Deinen Nachkommen will ich dieses Land geben", - der wird seinen Engel vor dir her senden, dass du dort ein Weib für meinen Sohn bekommst. (a) 1Mo 12:1 7',
        8: 'Wenn aber das Weib nicht mit dir ziehen will, so bist du dieses Eides ledig; doch meinen Sohn darfst du nicht wieder dorthin bringen.',
        9: 'Da legte der Knecht seine Hand unter die Hüfte Abrahams, seines Herrn, und schwur, nach seinem Wort zu tun.',
        10: 'Dann nahm der Knecht zehn Kamele von den Kamelen seines Herrn und allerlei Kostbarkeiten seines Herrn mit sich, brach auf und zog nach Syrien am Euphrat, nach der Stadt Nahors.',
        11: 'Da liess er die Kamele sich lagern, draussen vor der Stadt am Wasserquell, abends um die Zeit, da die Frauen herauskommen, um zu schöpfen.',
        12: 'Und er sprach: O Herr, du Gott meines Herrn Abraham, lass es mir doch heute glücken und erweise dich gütig gegen Abraham, meinen Herrn!',
        13: 'Ich stelle mich jetzt hier an den Wasserquell, wenn die Töchter der Stadtbewohner herauskommen, um Wasser zu schöpfen:',
        14: 'das Mädchen nun, zu dem ich sage: "Neige doch deinen Krug, dass ich trinke", und das dann spricht: "Trinke, und auch deine Kamele will ich tränken" - die soll es sein, die du deinem Knechte Isaak bestimmt hast; daran will ich erkennen, dass du dich gegen meinen Herrn gütig erweisest.',
        15: 'Und ehe er noch ausgeredet hatte, siehe, da kam auch schon Rebekka heraus, die Tochter Bethuels, des Sohnes der Milka, des Weibes Nahors, des Bruders Abrahams; die trug ihren Krug auf der Achsel.',
        16: 'Das Mädchen war sehr schön von Ansehen, eine Jungfrau; noch kein Mann hatte sie berührt. Sie stieg zum Quell hinab, füllte ihren Krug und stieg wieder herauf.',
        17: 'Da lief ihr der Knecht entgegen und sprach: Lass mich doch ein wenig Wasser aus deinem Kruge trinken.',
        18: 'Sie sprach: Trinke, Herr! Und schnell nahm sie ihren Krug herab auf die Hand und gab ihm zu trinken.',
        19: 'Und als sie ihm genug zu trinken gegeben, sprach sie: Auch deinen Kamelen will ich schöpfen, bis sie genug getrunken haben.',
        20: 'Und eilends leerte sie den Krug in die Tränkrinne; dann lief sie abermals zum Brunnen, um zu schöpfen, und schöpfte für alle seine Kamele.',
        21: 'Der Mann aber schaute ihr verwundert zu und schwieg stille, um zu erkennen, ob der Herr seine Reise habe gelingen lassen oder nicht.',
        22: 'Als nun die Kamele genug getrunken hatten, nahm der Mann einen goldenen Nasenring, ein halbes Lot schwer, und zwei Spangen für ihre Arme, zehn Lot Gold schwer.',
        23: 'Und er sprach: Wessen Tochter bist du? Sage es mir doch! Finden wir in deines Vaters Hause wohl Platz zum Übernachten?',
        24: 'Sie sprach zu ihm: Ich bin die Tochter Bethuels, des Sohnes der Milka, den sie dem Nahor geboren hat. (a) 1Mo 22:23',
        25: 'Dann sagte sie zu ihm: Wir haben Stroh und Futter in Fülle und auch Platz zum Übernachten.',
        26: 'Da verneigte sich der Mann, fiel vor dem Herrn nieder',
        27: 'und sprach: Gelobt sei der Herr, der Gott meines Gebieters Abraham, der seine Huld und Treue meinem Gebieter nicht entzogen hat! Mich hat Gott wahrhaftig den Weg zum Hause des Bruders meines Herrn geführt!',
        28: 'Das Mädchen aber lief hin und erzählte alles im Hause ihrer Mutter.',
        29: 'Nun hatte Rebekka einen Bruder, der hiess Laban.',
        30: 'Als der den Nasenring sah und die Spangen an den Armen seiner Schwester, und als er hörte, wie seine Schwester Rebekka erzählte: "So und so hat der Mann zu mir geredet", lief er zu dem Manne hinaus an den Brunnen; und wie er zu dem Manne kam, stand der noch immer bei den Kamelen am Brunnen.',
        31: 'Und Laban sprach zu ihm: Komm herein, du Gesegneter des Herrn! Warum bleibst du da draussen stehen? Ich habe schon das Haus aufgeräumt und auch für die Kamele Platz gemacht.',
        32: 'Da kam der Mann ins Haus, und Laban zäumte die Kamele ab und gab ihnen Stroh und Futter, ihm aber und seinen Leuten Wasser, um sich die Füsse zu waschen;',
        33: 'dann setzte er ihm zu essen vor. Er aber sprach: Ich esse nicht, bis ich meinen Auftrag ausgerichtet habe. Er erwiderte: So rede!',
        34: 'Da sprach er: Ich bin der Knecht Abrahams.',
        35: 'Der Herr hat meinen Gebieter reichlich gesegnet, sodass er reich geworden ist; er hat ihm Schafe und Rinder, Silber und Gold, Knechte und Mägde, Kamele und Esel gegeben.',
        36: 'Und Sara, das Weib meines Herrn, hat ihm noch in seinem Alter einen Sohn geboren; dem hat er all sein Gut übergeben.',
        37: 'Nun hat mein Herr einen Eid von mir genommen und gesagt: Du sollst meinem Sohn kein Weib nehmen von den Töchtern der Kanaaniter, in deren Land ich wohne;',
        38: 'sondern zu meines Vaters Hause sollst du ziehen und zu meinem Geschlechte, für meinen Sohn ein Weib zu holen.',
        39: 'Ich aber sprach zu meinem Herrn: Wie? wenn sie nun nicht mit mir ziehen will?',
        40: 'Da sprach er zu mir: Der Herr, vor dessen Angesichte ich gewandelt bin, wird seinen Engel mit dir senden und deine Reise wohl gelingen lassen, dass du für meinen Sohn ein Weib bekommst aus meinem Geschlechte und aus meines Vaters Hause.',
        41: 'Dann sollst du deines Eides ledig sein: wenn du zu meinem Geschlechte kommst und man sie dir nicht gibt, so bist du deines Eides ledig.',
        42: 'Als ich nun heute zum Quell kam, sprach ich: O Herr, du Gott meines Gebieters Abraham, wenn du wirklich meine Reise, auf der ich jetzt bin, wolltest gelingen lassen -,',
        43: 'ich stelle mich jetzt hier an den Wasserquell: die Jungfrau nun, die herauskommt, um zu schöpfen, und zu der ich sage: "Gib mir aus deinem Kruge ein wenig Wasser zu trinken",',
        44: 'und die dann zu mir spricht: "Trinke du, und auch für deine Kamele will ich schöpfen", die sei das Weib, das der Herr dem Sohne meines Gebieters bestimmt hat.',
        45: 'Und ehe ich noch bei mir selber ausgeredet, siehe, da kommt auch schon Rebekka heraus, ihren Krug auf der Achsel, steigt zum Quell hinab und schöpft. Da sprach ich zu ihr: "Gib mir zu trinken."',
        46: 'Und schnell nahm sie den Krug von der Achsel und sprach: "Trinke, und auch deine Kamele will ich tränken." So trank ich, und sie tränkte auch die Kamele.',
        47: 'Und ich fragte sie: "Wessen Tochter bist du?" Sie antwortete: "Die Tochter Bethuels, des Sohnes Nahors, den ihm Milka geboren hat." Da legte ich ihr den Ring an die Nase und die Spangen an die Arme,',
        48: 'und ich verneigte mich, fiel vor dem Herrn nieder und pries den Herrn, den Gott meines Gebieters Abraham, der mich den rechten Weg geführt hatte, um die Tochter des Bruders meines Herrn für seinen Sohn zu bekommen.',
        49: 'Und nun, wollt ihr meinem Herrn Huld und Treue beweisen, so sagt es mir; wo nicht, sagt es mir auch, dass ich mich zur Rechten oder zur Linken wende.',
        50: 'Da antworteten Laban und Bethuel: Das ist von dem Herrn gefügt! Wir können nichts dazu sagen, weder Gutes noch Schlimmes.',
        51: 'Da hast du Rebekka! Nimm sie und ziehe hin, dass sie das Weib des Sohnes deines Gebieters werde, wie der Herr es bestimmt hat.',
        52: 'Als Abrahams Knecht ihre Worte hörte, warf er sich vor dem Herrn zur Erde nieder;',
        53: 'dann holte er silbernes und goldenes Geschmeide und Gewänder hervor und gab sie Rebekka, auch ihrem Bruder und ihrer Mutter gab er Kostbarkeiten.',
        54: 'Darnach assen und tranken sie, er und die Männer, die bei ihm waren, und blieben daselbst übernacht. Am Morgen aber, als sie aufstanden, sprach er: Entlasst mich nun zu meinem Herrn.',
        55: 'Aber ihr Bruder und ihre Mutter erwiderten: Lass doch das Mädchen noch eine Zeitlang bei uns bleiben, wenigstens zehn Tage; darnach magst du ziehen.',
        56: 'Da sprach er zu ihnen: Haltet mich nicht auf, da doch der Herr meine Reise hat gelingen lassen; entlasst mich, dass ich zu meinem Gebieter ziehe.',
        57: 'Sie sprachen: Wir wollen das Mädchen rufen und sie selbst befragen.',
        58: 'So riefen sie Rebekka und sprachen zu ihr: Willst du mit diesem Manne ziehen? Sie antwortete: Ja, ich will.',
        59: 'Also liessen sie ihre Schwester Rebekka samt ihrer Amme mit dem Knechte Abrahams und seinen Leuten ziehen.',
        60: 'Und sie segneten Rebekka und sprachen zu ihr: Du unsre Schwester, werde zu vieltausendmal Tausenden, und dein Geschlecht gewinne das Tor seiner Feinde!',
        61: 'Da machten sich Rebekka und ihre Mägde auf; sie setzten sich auf die Kamele und folgten dem Manne. Und der Knecht nahm Rebekka und zog von dannen.',
        62: 'Isaak aber war in die Steppe des Brunnens von Lahai-Roi gezogen, und er wohnte im Gebiet des Südlands. (a) 1Mo 16:14',
        63: 'Einst ging nun Isaak um die Abendzeit aufs Feld hinaus, um nachzusinnen, und als er seine Augen erhob, sah er Kamele des Weges kommen.',
        64: 'Und als Rebekka ihre Augen erhob und Isaak sah, liess sie sich vom Kamele herab',
        65: 'und sprach zu dem Knechte: Wer ist der Mann dort, der uns auf dem Felde entgegenkommt? Der Knecht antwortete: Das ist mein Herr. Da nahm sie den Schleier und verhüllte sich.',
        66: 'Der Knecht aber erzählte Isaak alles, was er ausgerichtet hatte.',
        67: 'Da führte Isaak die Rebekka ins Zelt hinein, und er nahm sie sich zum Weibe und gewann sie lieb. So tröstete sich Isaak nach seiner Mutter Tod.',
    },
    25: {
        1: 'ABRAHAM aber nahm nochmals ein Weib, die hiess Ketura.',
        2: 'Sie gebar ihm Simran und Joksan, Medan und Midian, Jisbak und Suah.',
        3: 'Jodsan aber zeugte Saba und Dedan; und die Söhne Dedans waren die Assuriter, Letusiter und Lehummiter.',
        4: 'Die Söhne Midians aber sind Epha, Epher, Hanoch, Abida und Eldaa; alle diese sind Nachkommen der Ketura.',
        5: 'Und Abraham gab all sein Gut dem Isaak.',
        6: 'Den Söhnen der Nebenfrauen aber, die Abraham hatte, gab er Geschenke und schickte sie noch zu seinen Lebzeiten von seinem Sohne Isaak hinweg gegen Osten hin, ins Ostland.',
        7: 'Dies ist die Zeit der Lebensjahre Abrahams, die er gelebt hat: 175 Jahre;',
        8: 'dann verschied er. So starb Abraham in schönem Alter, alt und lebenssatt, und ward versammelt zu seinen Stammesgenossen.',
        9: 'Und seine Söhne Isaak und Ismael begruben ihn in der Höhle Machpela auf dem Grundstück des Hethiters Ephron, des Sohnes Zohars, das gegenüber Mamre liegt,',
        10: 'auf dem Grundstück, das Abraham von den Hethitern gekauft hatte. Daselbst wurden Abraham und sein Weib Sara begraben. (a) 1Mo 23:17 18',
        11: 'Und nach dem Tode Abrahams segnete Gott seinen Sohn Isaak. Isaak aber wohnte bei dem Brunnen von Lahai-Roi. (a) 1Mo 24:62',
        12: 'Dies ist das Geschlechtsregister Ismaels, des Sohnes Abrahams, den die Ägypterin Hagar, die Magd Saras, dem Abraham geboren hatte.',
        13: 'Dies sind die Namen der Söhne Ismaels, nach ihren Namen und Geschlechtern: Nebajoth, der Erstgeborne Ismaels, dann Kedar, Adbeel und Mibsam,',
        14: 'Misma, Duma und Massa,',
        15: 'Hadad und Thema, Jetur, Naphis und Kedma.',
        16: 'Dies also sind die Söhne Ismaels, und dies sind ihre Namen nach ihren Gehöften und Zeltlagern: zwölf Fürsten nach ihren Stämmen. (a) 1Mo 17:20',
        17: 'Und dies ist die Lebenszeit Ismaels: 137 Jahre; dann verschied er und starb und ward versammelt zu seinen Stammesgenossen.',
        18: 'Sie wohnten von Hawila an bis nach Sur, das östlich von Ägypten liegt, gegen Assur hin. All seinen Brüdern setzte er sich vors Gesicht. (a) 1Mo 16:12',
        19: 'DIES ist die Geschichte Isaaks, des Sohnes Abrahams: Abraham zeugte den Isaak.',
        20: 'Und Isaak war vierzig Jahre alt, als er sich die Tochter des Syrers Bethuel aus Mesopotamien, die Schwester des Syrers Laban, zum Weibe nahm.',
        21: 'Isaak aber bat den Herrn für sein Weib, denn sie war unfruchtbar; und der Herr liess sich von ihm erbitten, und sein Weib Rebekka wurde schwanger.',
        22: 'Da sich aber die Kinder in ihrem Leibe stiessen, sprach sie: Wenn es so ist, warum lebe ich dann? Und sie ging hin, den Herrn zu befragen.',
        23: 'Und der Herr sprach zu ihr: Zwei Völker sind in deinem Leibe, / und zwei Stämme werden sich aus deinem Schosse scheiden; / ein Stamm wird dem andern überlegen sein, / und der ältere wird dem jüngern dienen.',
        24: 'Als nun die Zeit kam, dass sie gebären sollte, siehe, da waren Zwillinge in ihrem Leibe.',
        25: 'Der erste, der herauskam, war rötlich, ganz und gar wie ein behaarter Mantel, und man nannte ihn Esau.',
        26: 'Darnach kam sein Bruder heraus, der hielt mit seiner Hand die Ferse Esaus, und man nannte ihn Jakob. Isaak aber war sechzig Jahre alt, da sie geboren wurden. (1) d.i. Fersenhalter.',
        27: 'Und als die Knaben heranwuchsen, ward Esau ein tüchtiger Jäger, ein Mann des freien Feldes; Jakob aber war ein gesitteter Mann, der in Zelten wohnte.',
        28: 'Isaak hatte den Esau lieber, weil er gern Wildbret ass; Jakob aber war der Liebling Rebekkas.',
        29: 'Nun kochte Jakob einst ein Gericht. Da kam Esau müde vom Felde heim,',
        30: 'und Esau sprach zu Jakob: Lass mich doch schnell von dem roten Ding essen, dem roten da; denn ich bin müde. Daher heisst er Edom. (1) d.i. Rot.',
        31: 'Aber Jakob sprach: Verkaufe mir zuvor deine Erstgeburt!',
        32: 'Esau antwortete: Sieh, ich muss ja doch sterben; was soll mir da die Erstgeburt?',
        33: 'Jakob sprach: So schwöre mir zuvor! Und er schwur ihm und verkaufte also dem Jakob seine Erstgeburt.',
        34: 'Da gab Jakob dem Esau Brot und das Linsengericht; der ass und trank, stand auf und ging davon. So achtete Esau die Erstgeburt gering.',
    },
    26: {
        1: 'ES kam aber eine Hungersnot über das Land, ausser der früheren, die zu Abrahams Zeiten gewesen war. Darum zog Isaak nach Gerar zu Abimelech, dem König der Philister. (a) 1Mo 12:10',
        2: 'Da erschien ihm der Herr und sprach: Ziehe nicht hinab nach Ägypten; bleibe in dem Lande, das ich dir nennen werde.',
        3: 'Weile als Fremdling in diesem Lande, ich will mit dir sein und will dich segnen; denn dir und deinem Geschlechte will ich all diese Länder geben und so den Eid erfüllen, den ich deinem Vater Abraham geschworen habe:',
        4: 'ich will dein Geschlecht so zahlreich machen wie die Sterne des Himmels und will deinem Geschlecht all diese Länder geben, und mit dem Namen deines Geschlechtes werden sich Segen wünschen alle Völker der Erde, (1) vgl. Anm. zu 1Mo 12:2 3. (a) 1Mo 12:7; 15:5; 22:17 18',
        5: 'weil Abraham auf mein Wort gehört und alles gehalten hat, was er mir zu halten hatte: meine Gebote, Satzungen und Gesetze.',
        6: 'Also blieb Isaak in Gerar.',
        7: 'Als nun die Leute des Ortes nach seinem Weibe fragten, sprach er: "Sie ist meine Schwester." Denn er fürchtete sich zu sagen: "Sie ist mein Weib"(, weil er dachte): die Leute des Ortes könnten mich um Rebekkas willen töten, da sie so schön ist.',
        8: 'Als er aber schon längere Zeit dort wohnte, begab es sich, dass einst Abimelech, der König der Philister, zum Fenster hinausschaute; da sah er Isaak mit seinem Weibe Rebekka kosen.',
        9: 'Nun liess Abimelech den Isaak rufen und sprach: Sie ist ja dein Weib! Wie konntest du denn sagen, sie sei deine Schwester? Isaak antwortete ihm: Ich dachte eben, ich müsste um ihretwillen vielleicht sterben.',
        10: 'Abimelech aber sprach: Was hast du uns da angetan! Wie leicht hätte einer aus dem Volke deinem Weibe Gewalt antun können, und du hättest eine Schuld über uns gebracht.',
        11: 'Darnach gebot Abimelech dem ganzen Volke: Wer diesen Mann oder sein Weib anrührt, ist des Todes!',
        12: 'Und Isaak säte in dem Lande, und er erntete in jenem Jahre hundertfältig; denn der Herr segnete ihn.',
        13: 'So wurde der Mann reich und immer reicher, bis er über die Massen reich war;',
        14: 'er hatte Herden von Schafen und Herden von Rindern und ein grosses Gesinde. Darum beneideten ihn die Philister.',
        15: 'Alle Brunnen aber, welche die Knechte seines Vaters gegraben hatten in den Tagen seines Vaters Abraham, die hatten die Philister zugeschüttet und mit Erde gefüllt.',
        16: 'Und Abimelech sprach zu Isaak: Ziehe von uns hinweg, denn du bist uns viel zu mächtig geworden.',
        17: 'Da zog Isaak von dannen. Und er lagerte sich im Tale von Gerar und blieb daselbst.',
        18: 'Und Isaak liess die Wasserbrunnen, welche die Knechte seines Vaters Abraham gegraben und welche die Philister nach dem Tode Abrahams zugeschüttet hatten, wieder aufgraben und benannte sie mit denselben Namen, mit denen sein Vater sie benannt hatte.',
        19: 'Als nun Isaaks Knechte im Tale gruben, fanden sie daselbst einen Brunnen mit Quellwasser.',
        20: 'Aber die Hirten von Gerar zankten mit den Hirten Isaaks und sprachen: Uns gehört das Wasser! Da nannte er den Brunnen Esek, weil sie sich dort mit ihm gezankt hatten. (1) d.i. Zank.',
        21: 'Hernach gruben sie einen andern Brunnen, um den stritten sie auch; darum nannte er ihn Sitna. (1) d.i. Streit.',
        22: 'Da brach er von dannen auf und grub abermals einen Brunnen, um den zankten sie nicht; darum nannte er ihn Rehobot und sprach: Nun hat uns der Herr weiten Raum geschafft, dass wir im Lande wachsen können. (1) d.i. weiter Raum.',
        23: 'Von dort zog er hinauf nach Beerseba.',
        24: 'Und der Herr erschien ihm in jener Nacht und sprach: Ich bin der Gott deines Vaters Abraham. Fürchte dich nicht, denn ich bin mit dir; ich will dich segnen und dein Geschlecht mehren um meines Knechtes Abraham willen.',
        25: 'Da baute er an der Stelle einen Altar und rief den Namen des Herrn an. Und Isaak schlug dort sein Zelt auf, und seine Knechte gruben daselbst einen Brunnen.',
        26: 'Nun kam einst Abimelech zu ihm von Gerar mit seinem Freunde Ahussat und seinem Feldhauptmann Pichol.',
        27: 'Da sprach Isaak zu ihnen: Warum kommt ihr zu mir, da ihr mich doch hasset und mich von euch weggeschickt habt?',
        28: 'Sie sprachen: Wir sehen nun in der Tat, dass der Herr mit dir ist; darum dachten wir: es soll ein Vertrag zwischen uns beschworen werden, zwischen uns und dir, und wir wollen einen Bund mit dir schliessen,',
        29: 'dass du uns nichts zuleide tuest, wie auch wir dich nicht angerührt und dir nur Gutes getan und dich in Frieden haben ziehen lassen. Du bist nun einmal der Gesegnete des Herrn.',
        30: 'Da bereitete er ihnen ein Mahl, und sie assen und tranken.',
        31: 'Und am andern Morgen in der Frühe schwuren sie einander den Eid. Dann entliess sie Isaak, und sie schieden von ihm in Frieden.',
        32: 'An demselben Tage kamen Isaaks Knechte und sagten ihm von dem Brunnen, den sie gegraben hatten, und sprachen zu ihm: Wir haben Wasser gefunden.',
        33: 'Da nannte er ihn Sebua. Daher heisst der Ort "Beer-Seba" bis auf den heutigen Tag. (1) d.i. Eid. (2) d.i. Eidbrunnen. (a) 1Mo 21:31',
        34: 'Als Esau vierzig Jahre alt war, nahm er zum Weibe Judith, die Tochter des Hethiters Beeri, ferner Basmath, die Tochter des Hethiters Elon;',
        35: 'die waren für Isaak und Rebekka ein schwerer Kummer.',
    },
    27: {
        1: 'UND es begab sich, als Isaak alt geworden war und seine Augen trübe wurden, sodass er nicht mehr sehen konnte, da rief er Esau, seinen ältern Sohn, und sprach zu ihm: Mein Sohn! Er antwortete ihm: Hier bin ich.',
        2: 'Da sprach er: Sieh, ich bin alt geworden und weiss nicht, wann ich sterben muss.',
        3: 'So nimm nun dein Jagdgerät, Köcher und Bogen, geh aufs Feld und jage mir ein Wildbret;',
        4: 'dann bereite mir ein gutes Gericht, wie ich es gerne habe, und bring es mir herein zum Essen, auf dass dich meine Seele segne, ehe ich sterbe.',
        5: 'Rebekka aber hörte zu, wie Isaak mit seinem Sohne Esau redete. Als nun Esau aufs Feld ging, für seinen Vater ein Wildbret zu jagen,',
        6: 'sprach Rebekka zu ihrem Sohne Jakob: Sieh, ich habe gehört, wie dein Vater zu deinem Bruder Esau sagte:',
        7: '"Bringe mir ein Wildbret und bereite mir ein gutes Gericht, dass ich esse; dann will ich dich segnen vor dem Angesicht des Herrn, ehe ich sterbe."',
        8: 'So höre nun, mein Sohn, auf mich und tue, was ich dich heisse:',
        9: 'Gehe zu der Herde und hole mir von dort zwei schöne Ziegenböcklein; dann will ich deinem Vater ein gutes Gericht bereiten, wie er es gerne hat.',
        10: 'Das sollst du deinem Vater hineintragen, dass er esse und dich vor seinem Tode segne.',
        11: 'Jakob aber sprach zu seiner Mutter Rebekka: Sieh, mein Bruder Esau ist behaart, und ich bin glatt.',
        12: 'Vielleicht könnte mein Vater mich betasten; dann stünde ich vor ihm als einer, der seinen Spott mit ihm treibt, und ich brächte über mich einen Fluch und nicht einen Segen.',
        13: "Da sprach seine Mutter zu ihm: Der Fluch komme über mich, mein Sohn! Höre du nur auf mich, geh und hole mir's.",
        14: 'Da ging er hin, holte die Böcklein und brachte sie seiner Mutter. Und seine Mutter bereitete ein gutes Gericht, wie es sein Vater gerne hatte.',
        15: 'Dann nahm Rebekka die Feierkleider Esaus, ihres ältern Sohnes, die sie bei sich im Hause hatte, und legte sie Jakob, ihrem jüngern Sohne, an.',
        16: 'Die Felle von den Ziegenböcklein aber tat sie ihm um die Arme und um seinen glatten Hals.',
        17: 'Dann gab sie das gute Gericht, das sie bereitet hatte, und das Brot ihrem Sohne Jakob in die Hand.',
        18: 'So ging er zu seinem Vater hinein und sprach: Vater! Er antwortete: Hier bin ich; wer bist du, mein Sohn?',
        19: 'Jakob sprach zu seinem Vater: Ich bin Esau, dein Erstgeborner; ich habe getan, wie du mir befohlen hast. Setze dich auf und iss von meinem Wildbret, auf dass mich deine Seele segne.',
        20: 'Isaak aber sprach zu seinem Sohne: Mein Sohn, wie hast du es so bald gefunden? Er antwortete: Der Herr, dein Gott, hat es mir begegnen lassen.',
        21: 'Da sprach Isaak zu Jakob: Tritt herzu, mein Sohn, dass ich dich betaste, ob du wirklich mein Sohn Esau seiest oder nicht.',
        22: 'Nun trat Jakob zu seinem Vater Isaak, und als er ihn betastet hatte, sprach er: Die Stimme ist Jakobs Stimme, aber die Arme sind Esaus Arme.',
        23: 'Und er erkannte ihn nicht; denn seine Arme waren behaart, wie die Arme seines Bruders Esau. So segnete er ihn denn.',
        24: 'Und er sprach zu ihm: Bist du wirklich mein Sohn Esau? Er antwortete: Ja, das bin ich.',
        25: 'Da sprach er: So trage mir auf, dass ich esse von dem Wildbret meines Sohnes, auf dass dich meine Seele segne. Da trug er ihm auf, und er ass; und er brachte ihm auch Wein, und er trank.',
        26: 'Dann sprach sein Vater Isaak zu ihm: Komm her, mein Sohn, und küsse mich.',
        27: 'Und er trat herzu und küsste ihn. Da roch er den Geruch seiner Kleider, und er segnete ihn und sprach: Siehe, der Geruch meines Sohnes / ist wie der Geruch des Feldes, / das der Herr gesegnet hat. /',
        28: 'Gott gebe dir vom Tau des Himmels / und vom Fett der Erde / und Korn und Wein die Fülle! /',
        29: 'Völker sollen dir dienen / und Nationen sich vor dir beugen! / Sei ein Herr über deine Brüder, / und deiner Mutter Söhne sollen sich vor dir beugen! / Verflucht ist, wer dir flucht, / und gesegnet, wer dich segnet! (a) 1Mo 25:23; 12:3',
        30: 'Als nun Isaak den Segen über Jakob eben vollendet hatte und Jakob kaum von seinem Vater Isaak hinausgegangen war, da kam sein Bruder Esau von der Jagd heim;',
        31: 'der bereitete auch ein gutes Gericht und trug es seinem Vater hinein. Und er sprach zu seinem Vater: Richte dich auf, Vater, und iss von dem Wildbret deines Sohnes, auf dass mich deine Seele segne.',
        32: 'Sein Vater Isaak aber sprach zu ihm: Wer bist du? Er antwortete: Ich bin dein Sohn, dein Erstgeborner, Esau.',
        33: 'Da entsetzte sich Isaak über alle Massen und sprach: Wer war denn der, der ein Wild gejagt und es mir hereingebracht hat? Nun habe ich eben schon gegessen, ehe du kamst, und habe ihn gesegnet; er wird auch gesegnet bleiben.',
        34: 'Als Esau die Worte seines Vaters hörte, schrie er gar laut und kläglich auf und sprach zu seinem Vater: Segne mich auch, Vater!',
        35: 'Er aber sprach: Dein Bruder ist gekommen mit Hinterlist und hat dir den Segen vorweggenommen.',
        36: 'Da sprach er: Mit Recht heisst er Jakob; denn er hat mich nun zweimal hintergangen. Die Erstgeburt hat er mir genommen, und nun nimmt er mir auch den Segen. Und er sprach: Hast du mir keinen Segen vorbehalten? (1) d.i. der Hinterlistige. (a) 1Mo 25:33',
        37: 'Isaak antwortete und sprach zu Esau: Sieh, ich habe ihn zum Herrn über dich gesetzt und alle seine Brüder ihm zu Knechten gegeben; mit Korn und Wein habe ich ihn versehen. Was kann ich da für dich noch tun, mein Sohn?',
        38: 'Esau sprach zu seinem Vater: Hast du denn nur den einen Segen, Vater? Segne mich auch, Vater! Und Esau hob laut zu weinen an.',
        39: 'Da antwortete sein Vater Isaak und sprach zu ihm: Sieh, fern vom Fett der Erde soll deine Wohnung sein / und fern vom Tau des Himmels droben. /',
        40: "Von deinem Schwerte musst du leben, / und deinem Bruder sollst du dienen. / Doch wird's geschehen: wenn du dich mühst, / wirst du sein Joch von deinem Halse reissen. (a) 2Kön 8:20",
        41: 'Esau aber ward dem Jakob feind um des Segens willen, mit dem ihn sein Vater gesegnet hatte. Und Esau sprach bei sich selbst: Bald kommt die Zeit der Trauer um meinen Vater; dann will ich meinen Bruder Jakob töten.',
        42: 'Als nun der Rebekka die Worte ihres ältern Sohnes Esau hinterbracht wurden, schickte sie hin und liess ihren jüngern Sohn Jakob rufen und sprach zu ihm: Sieh, dein Bruder Esau will an dir Rache nehmen und dich töten.',
        43: 'So höre nun auf mich, mein Sohn: mache dich auf und fliehe zu meinem Bruder Laban nach Haran, (a) 1Mo 24:29',
        44: 'und bleibe eine Zeitlang bei ihm, bis deines Bruders Grimm sich legt,',
        45: 'bis sich der Zorn deines Bruders von dir wendet und er vergisst, was du ihm angetan hast; dann will ich nach dir schicken und dich von dort holen lassen. Warum sollte ich euch beide an einem Tag verlieren?',
        46: 'UND Rebekka sprach zu Isaak: Mir ist das Leben verleidet ob der Hethiterinnen; wenn Jakob auch ein solches Weib nimmt, eine von den Töchtern der Hethiter, eine Einheimische, was soll mir da das Leben? (a) 1Mo 26:34 35',
    },
    28: {
        1: 'Da rief Isaak den Jakob und segnete ihn; und er gebot ihm und sprach: Du sollst dir kein Weib nehmen von den Töchtern Kanaans. (a) 1Mo 24:3',
        2: 'Mache dich auf und ziehe nach Mesopotamien, zum Hause Bethuels, des Vaters deiner Mutter, und hole dir dort ein Weib von den Töchtern Labans, des Bruders deiner Mutter. (a) 1Mo 24:29',
        3: 'Und der allmächtige Gott segne dich und mache dich fruchtbar und mehre dich, dass du zu einer Gemeinde von Völkern werdest;',
        4: 'und er gebe dir den Segen Abrahams, dir samt deinem Geschlechte, dass das Land, in dem du als Fremdling weilst, das Gott dem Abraham gegeben hat, dein eigen werde.',
        5: 'So entliess Isaak den Jakob, und er zog nach Mesopotamien zu Laban, dem Sohne Bethuels, des Syrers, dem Bruder der Rebekka, der Mutter Jakobs und Esaus.',
        6: 'Als nun Esau sah, dass Isaak den Jakob gesegnet und ihn nach Mesopotamien gesandt hatte, damit er sich dort ein Weib hole - indem er ihn segnete und ihm gebot: "Du sollst dir kein Weib nehmen von den Töchtern Kanaans" -',
        7: 'und dass Jakob seinem Vater und seiner Mutter gehorsam war und nach Mesopotamien zog,',
        8: 'da merkte Esau, dass sein Vater Isaak die Töchter Kanaans nicht gerne sah.',
        9: 'Daher ging Esau hin zu Ismael und nahm zu den Frauen, die er schon hatte, Mahalath, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajoths, zum Weibe.',
        10: 'JAKOB aber zog aus von Beerseba und machte sich auf den Weg nach Haran.',
        11: 'Da traf es sich, dass er an die (heilige) Stätte (von Bethel) kam, und er blieb daselbst übernacht; denn die Sonne war untergegangen. Und er nahm einen von den Steinen der Stätte, tat ihn unter sein Haupt und legte sich an dieser Stätte schlafen.',
        12: 'Da träumte ihm, eine Leiter sei auf die Erde gestellt, die mit der Spitze an den Himmel rührte, und die Engel Gottes stiegen daran auf und nieder.',
        13: 'Und siehe, der Herr stand vor ihm und sprach: Ich bin der Herr, der Gott deines Vaters Abraham und der Gott Isaaks; das Land, auf dem du ruhst, will ich dir und deinen Nachkommen geben.',
        14: 'Und deine Nachkommen sollen (zahlreich) werden wie der Staub der Erde; gegen Abend und Morgen, gegen Mitternacht und Mittag sollst du dich ausbreiten, und mit deinem und deines Geschlechtes Namen werden sich Segen wünschen alle Geschlechter der Erde. (1) vgl. Anm. zu 1Mo 12:2 3.',
        15: 'Siehe, ich bin mit dir und will dich behüten allenthalben, wo du hinziehst, und dich in dieses Land zurückbringen. Denn ich will dich nicht verlassen, bis dass ich getan, was ich dir verheissen habe.',
        16: 'Als Jakob von seinem Schlaf erwachte, sprach er: Fürwahr, der Herr ist an dieser Stätte, und ich wusste es nicht.',
        17: 'Und er fürchtete sich und sprach: Wie furchtbar ist diese Stätte! Hier ist nichts anderes als Gottes Haus, hier ist die Pforte des Himmels.',
        18: 'Am andern Morgen aber in der Frühe nahm Jakob den Stein, den er unter sein Haupt gelegt hatte, richtete ihn auf als Malstein und goss Öl oben darauf;',
        19: 'und er nannte die Stätte Bethel. Früher aber hiess die Stadt Lus. (1) d.i. Gotteshaus. (a) 1Mo 35:6 7',
        20: 'Und Jakob tat ein Gelübde und sprach: Wenn Gott mit mir ist und mich behütet auf dem Wege, den ich jetzt ziehe, wenn er mir Brot zu essen gibt und Kleider anzuziehen',
        21: 'und ich wohlbehalten wieder zu meines Vaters Haus zurückkomme, so soll der Herr mein Gott sein,',
        22: 'und dieser Stein, den ich als Malstein aufgerichtet habe, soll ein Gotteshaus werden, und alles, was du mir geben wirst, will ich dir getreulich verzehnten.',
    },
    29: {
        1: 'DANN machte sich Jakob auf den Weg und wanderte nach dem Land im Osten.',
        2: 'Und als er um sich schaute, sah er auf dem Felde einen Brunnen; an dem lagerten gerade drei Herden Schafe; denn aus dem Brunnen pflegte man die Herden zu tränken. Der Stein über der Öffnung des Brunnens aber war gross.',
        3: 'Und wenn alle Herden dort beisammen waren, wälzte man den Stein von der Öffnung des Brunnens und tränkte die Schafe; dann brachte man den Stein wieder über die Öffnung des Brunnens an seine Stelle.',
        4: 'Jakob sprach zu den Leuten: Meine Brüder, wo seid ihr her? Sie antworteten: Wir sind von Haran.',
        5: 'Er sprach zu ihnen: Kennt ihr Laban, den Sohn Nahors? Sie antworteten: Gewiss, wir kennen ihn.',
        6: 'Er sprach zu ihnen: Steht es wohl um ihn? Sie antworteten: Ja, es steht wohl um ihn; doch sieh, da kommt eben seine Tochter Rahel mit den Schafen.',
        7: 'Er sprach: Es ist ja noch hoch am Tage und noch nicht Zeit, das Vieh einzutreiben; tränkt die Schafe und dann lasst sie wieder weiden.',
        8: 'Sie antworteten: Das können wir nicht, bis alle Herden beisammen sind; dann wälzt man den Stein von der Öffnung des Brunnens, und wir tränken die Schafe.',
        9: 'Während er noch mit ihnen redete, war Rahel mit den Schafen ihres Vaters herangekommen; denn sie pflegte sie zu hüten.',
        10: 'Als Jakob aber Rahel, die Tochter seines Oheims Laban, und die Schafe seines Oheims Laban sah, trat er herzu, wälzte den Stein von der Öffnung des Brunnens und tränkte die Schafe seines Oheims Laban.',
        11: 'Und Jakob küsste Rahel und begann laut zu weinen.',
        12: 'Dann sagte Jakob der Rahel, dass er der Verwandte ihres Vaters, der Sohn Rebekkas, sei. Da lief sie hin und sagte es ihrem Vater.',
        13: 'Als nun Laban die Kunde von Jakob, dem Sohne seiner Schwester, hörte, lief er ihm entgegen, umarmte und küsste ihn und führte ihn in sein Haus. Und er erzählte dem Laban seine ganze Geschichte.',
        14: 'Da sprach Laban zu ihm: Ja, du bist von meinem Fleisch und Bein. Und er blieb einen Monat bei ihm.',
        15: 'Darnach sprach Laban zu Jakob: Du bist ja doch mein Verwandter; solltest du mir umsonst dienen? Sag an: was soll dein Lohn sein?',
        16: 'Nun hatte Laban zwei Töchter; die ältere hiess Lea und die jüngere Rahel.',
        17: 'Lea hatte matte Augen, Rahel aber war schön von Gestalt und schön von Angesicht;',
        18: 'und Jakob hatte Rahel lieb. So sprach er: Ich will dir sieben Jahre um Rahel, deine jüngere Tochter, dienen.',
        19: 'Laban antwortete: Es ist besser, ich gebe sie dir, als dass ich sie einem fremden Manne gebe; bleibe bei mir.',
        20: 'Also diente Jakob um Rahel sieben Jahre, und sie kamen ihm vor wie ein paar Tage, so lieb hatte er sie.',
        21: 'Dann sprach Jakob zu Laban: Gib mir nun mein Weib - denn meine Zeit ist um -, dass ich ihr beiwohne.',
        22: 'Da lud Laban alle Leute des Ortes ein und veranstaltete ein Festmahl.',
        23: 'Am Abend aber nahm er seine Tochter Lea und führte sie zu ihm hinein, und er wohnte ihr bei.',
        24: 'Und Laban gab seine Magd Silpa seiner Tochter Lea zur Magd.',
        25: 'Am Morgen aber, siehe, da war es Lea! Da sprach Jakob zu Laban: Was hast du mir angetan! Habe ich dir nicht um Rahel gedient? Warum hast du mich betrogen?',
        26: 'Laban antwortete: Es ist hierzuland nicht Sitte, dass man die jüngere vor der ältern weggebe.',
        27: 'Vollende mit dieser die Festwoche, dann wollen wir dir auch die andre geben um den Dienst, den du bei mir noch weitere sieben Jahre tun sollst.',
        28: 'Jakob tat es und vollendete die Woche. Dann gab ihm jener seine Tochter Rahel zum Weibe.',
        29: 'Und Laban gab seine Magd Bilha seiner Tochter Rahel zur Magd.',
        30: 'Da wohnte Jakob auch der Rahel bei; Rahel aber hatte er lieber als Lea. Und er diente bei ihm noch weitere sieben Jahre.',
        31: 'ALS aber der Herr sah, dass Lea zurückgesetzt war, machte er sie fruchtbar, während Rahel unfruchtbar blieb.',
        32: 'So ward Lea schwanger und gebar einen Sohn; den nannte sie Ruben. Denn sie sprach: Der Herr hat mein Elend angesehen; nun wird mich mein Mann liebhaben. (1) aus den Namen der Söhne Jakobs hörte man Anklänge an die Wörter heraus, deren Üs. jeweilen -+kursiv- gedruckt ist.',
        33: 'Und sie ward abermals schwanger und gebar einen Sohn; und sie sprach: Der Herr hat gehört, dass ich zurückgesetzt bin; darum hat er mir auch diesen gegeben. Und sie nannte ihn Simeon.',
        34: 'Dann ward sie abermals schwanger und gebar einen Sohn; und sie sprach: Nun endlich wird mein Mann mir anhänglich sein; denn ich habe ihm drei Söhne geboren. Darum nannte sie ihn Levi.',
        35: 'Und noch einmal ward sie schwanger und gebar einen Sohn; und sie sprach: Nunmehr will ich den Herrn preisen! Darum nannte sie ihn Juda. Darnach hörte sie auf zu gebären.',
    },
    30: {
        1: 'Als Rahel sah, dass sie dem Jakob keine Kinder gebar, da ward sie eifersüchtig auf ihre Schwester und sprach zu Jakob: Schaffe mir Kinder; wo nicht, so sterbe ich.',
        2: 'Jakob aber wurde zornig über Rahel und sprach: Bin ich denn an Gottes Statt, der dir Leibesfrucht versagt? (a) Ps 127:3',
        3: 'Darauf sprach sie: Da hast du meine Magd Bilha; wohne ihr bei; damit sie auf meinem Schoss gebäre und durch sie auch ich zu Kindern komme.',
        4: 'Also gab sie ihm ihre Magd Bilha zum Weibe, und Jakob wohnte ihr bei.',
        5: 'Und Bilha ward schwanger und gebar dem Jakob einen Sohn.',
        6: 'Da sprach Rahel: Gott hat mir Recht geschafft, er hat mich auch erhört und mir einen Sohn gegeben. Darum nannte sie ihn Dan.',
        7: 'Und Bilha, Rahels Magd, ward abermals schwanger und gebar dem Jakob einen zweiten Sohn.',
        8: 'Da sprach Rahel: Einen Gotteskampf habe ich mit meiner Schwester gekämpft, habe auch obgesiegt. Darum nannte sie ihn Naphthali.',
        9: 'Als nun Lea sah, dass sie aufgehört hatte zu gebären, nahm sie ihre Magd Silpa und gab sie Jakob zum Weibe.',
        10: 'Und Silpa, Leas Magd, gebar dem Jakob einen Sohn.',
        11: 'Da sprach Lea: "Glück auf!" und nannte ihn Gad.',
        12: 'Darnach gebar Silpa, Leas Magd, dem Jakob einen zweiten Sohn.',
        13: 'Da sprach Lea: "Ich Glückliche! Die Töchter des Volkes werden mich glücklich preisen!" und sie nannte ihn Asser.',
        14: 'Nun ging einst Ruben aufs Feld, zur Zeit der Weizenernte; dort fand er Liebesäpfel und brachte sie seiner Mutter Lea heim. Da sprach Rahel zu Lea: Gib mir von den Liebesäpfeln deines Sohnes!',
        15: "Sie aber antwortete ihr: Ist's nicht genug, dass du mir meinen Mann genommen hast? Nun willst du auch noch die Liebesäpfel meines Sohnes haben! Da sprach Rahel: Nun, so mag er heute nacht bei dir schlafen für die Liebesäpfel deines Sohnes.",
        16: 'Als nun Jakob am Abend vom Felde kam, ging Lea ihm entgegen und sprach: Zu mir musst du kommen, denn ich habe dich erkauft um die Liebesäpfel meines Sohnes. Also schlief er jene Nacht bei ihr.',
        17: 'Und Gott erhörte Lea, und sie ward schwanger und gebar dem Jakob einen fünften Sohn.',
        18: 'Da sprach Lea: "Gott hat mir\'s gelohnt, dass ich meinem Manne meine Magd gegeben habe", und sie nannte ihn Issaschar.',
        19: 'Dann ward Lea abermals schwanger und gebar dem Jakob einen sechsten Sohn.',
        20: 'Da sprach Lea: Gott hat mir eine reiche Gabe gegeben; nun endlich wird mein Mann bei mir Wohnung nehmen, denn ich habe ihm sechs Söhne geboren. Und sie nannte ihn Sebulon.',
        21: 'Darnach gebar sie eine Tochter und nannte sie Dina.',
        22: 'Gott aber gedachte der Rahel: er erhörte ihr Gebet und machte sie fruchtbar.',
        23: 'Da ward sie schwanger und gebar einen Sohn; und sie sprach: Gott hat meine Schmach von mir genommen.',
        24: 'Und sie nannte ihn Joseph und sprach: Der Herr wolle mir noch einen Sohn dazu geben!',
        25: 'ALS nun Rahel den Joseph geboren hatte, sprach Jakob zu Laban: Entlasse mich, ich möchte an meinen Ort und in mein Land ziehen.',
        26: 'Gib mir meine Frauen, um die ich dir gedient habe, und meine Kinder, dass ich hinziehen kann; du weisst ja selber, wie ich dir gedient habe.',
        27: 'Laban sprach zu ihm: Wenn du mir doch einen Gefallen tun wolltest! Ich habe erkundet, dass mich Gott um deinetwillen gesegnet hat.',
        28: 'Dann sprach er: Bestimme den Lohn, den du von mir haben willst; ich will ihn dir geben.',
        29: 'Er erwiderte ihm: Du weisst ja selber, wie ich dir gedient habe und was aus deinen Herden unter mir geworden ist.',
        30: 'Nur wenig hattest du, ehe ich herkam; nun aber ist es gewaltig gewachsen, und der Herr hat dich gesegnet, seit ich hier bin. Und nun, wann soll auch ich für mein Haus sorgen?',
        31: 'Er aber sprach: Was soll ich dir geben? Jakob antwortete: Du sollst mir gar nichts geben. Wenn du mir tun willst, was ich nun sage, so will ich wieder deine Schafe weiden und hüten:',
        32: 'ich will heute durch deine ganze Herde gehen; daraus magst du alle schwarzen Tiere unter den Lämmern, und was unter den Ziegen gefleckt und gesprenkelt ist, absondern - die sollen mein Lohn sein.',
        33: 'Und darin wird meine Rechtschaffenheit an einem künftigen Tage für mich zeugen: wenn du kommst, meinen Lohn zu besehen, so soll alles, was unter den Ziegen nicht gesprenkelt oder gefleckt und unter den Lämmern nicht schwarz ist, als von mir gestohlen gelten.',
        34: 'Da sprach Laban: Gut, es sei, wie du gesagt hast.',
        35: 'Und er sonderte am selben Tage die gestreiften und gefleckten Böcke und alle gesprenkelten und gefleckten Ziegen aus, alles, woran etwas Weisses war, und alles, was schwarz war unter den Lämmern, und übergab sie seinen Söhnen.',
        36: 'Und er machte einen Zwischenraum von drei Tagereisen zwischen sich und Jakob; Jakob aber weidete die übrige Herde Labans.',
        37: 'Nun nahm Jakob frische Ruten von Weisspappeln, Mandelbäumen und Platanen und schälte daran weisse streifen aus, sodass das Weisse an den Ruten blossgelegt wurde;',
        38: 'dann stellte er die Ruten, die er geschält hatte, in die Tröge, in die Tränkrinnen, wohin die Herden zum Trinken kamen, vor die Tiere hin, und die Tiere begatteten sich, wenn sie zur Tränke kamen.',
        39: 'So begatteten sich die Tiere vor den Ruten und warfen dann Gestreifte, Gesprenkelte und Gefleckte.',
        40: 'Die Lämmer aber schied Jakob aus. Und er kehrte das Gesicht der Tiere gegen die gestreiften und schwarzen in der Herde Labans. So machte er sich eigne Herden; die tat er nicht zu den Tieren Labans.',
        41: 'Sooft die starken Tiere brünstig waren, stellte Jakob die Ruten in die Tränkrinnen vor die Augen der Tiere, sodass sie sich vor den Ruten begatteten;',
        42: 'wenn aber die Tiere schwächlich waren, stellte er sie nicht hin. So fielen Laban die schwächlichen Tiere zu, Jakob aber die starken.',
        43: 'Daher ward der Mann über die Massen reich, sodass er viel Vieh, Mägde und Knechte, Kamele und Esel hatte.',
    },
    31: {
        1: 'DA vernahm er, dass die Söhne Labans sagten: Jakob hat unsres Vaters ganzes Gut an sich gebracht, und von unsres Vaters Gut hat er all diesen Reichtum erworben.',
        2: 'Und Jakob sah an Labans Miene, dass er gegen ihn nicht mehr war wie ehedem.',
        3: 'Der Herr aber sprach zu Jakob: Kehre zurück in das Land deiner Väter und zu deiner Verwandtschaft; ich will mit dir sein.',
        4: 'Da sandte Jakob hin und liess Rahel und Lea aufs Feld zu seiner Herde rufen',
        5: 'und sprach zu ihnen: Ich sehe an der Miene eures Vaters, dass er gegen mich nicht mehr ist wie ehedem; aber der Gott meines Vaters ist mit mir gewesen.',
        6: 'Ihr selber wisst doch, dass ich eurem Vater aus allen meinen Kräften gedient habe,',
        7: 'euer Vater aber hat mich betrogen und mir den Lohn zehnmal verändert; aber Gott hat ihm nicht gestattet, dass er mir Schaden tue.',
        8: 'Wenn er sprach: "Die Gesprenkelten sollen dein Lohn sein", so warf die ganze Herde Gesprenkelte. Und wenn er sprach: "Die Gestreiften sollen dein Lohn sein", so warf die ganze Herde Gestreifte.',
        9: 'So hat Gott eurem Vater die Habe genommen und sie mir gegeben.',
        10: 'Denn als die Brunstzeit der Schafe kam, erhob ich meine Augen und sah im Traume, wie die Böcke, welche die Schafe besprangen, gestreift, gesprenkelt und scheckig waren.',
        11: 'Und der Engel Gottes sprach zu mir im Traume: Jakob! Ich antwortete: Hier bin ich.',
        12: 'Er aber sprach: Erhebe deine Augen und sieh, wie alle Böcke, welche die Schafe bespringen, gestreift, gesprenkelt und scheckig sind. Denn ich habe alles gesehen, was dir Laban antut.',
        13: 'Ich bin der Gott, der dir zu Bethel erschienen ist, wo du einen Malstein gesalbt und wo du mir ein Gelübde getan hast. Nun mache dich auf, ziehe hinweg aus diesem Lande und kehre in dein Heimatland zurück. (a) 1Mo 28:18 19',
        14: 'Da antworteten Rahel und Lea und sprachen zu ihm: Haben wir noch Teil und Erbe in unsers Vaters Hause?',
        15: 'Gelten wir ihm nicht als Fremde? Er hat uns ja verkauft und längst das Geld dafür verbraucht!',
        16: 'So gehört denn all der Reichtum, den Gott unserm Vater weggenommen hat, uns und unsern Kindern. Und nun tue alles, was dir Gott gesagt hat.',
        17: 'Da machte sich Jakob auf, lud seine Kinder und Frauen auf die Kamele',
        18: 'und trieb all sein Vieh hinweg und seine ganze Habe, die er erworben, seinen Besitz an Vieh, den er in Mesopotamien erworben hatte, um zu seinem Vater Isaak ins Land Kanaan zu ziehen.',
        19: 'Laban aber war hingegangen, seine Schafe zu scheren. Da stahl Rahel den Theraphim ihres Vaters.',
        20: 'So überlistete Jakob den Syrer Laban, indem er ihn nicht merken liess, dass er fliehen wollte.',
        21: 'Und er floh mit allem, was sein war, machte sich auf, setzte über den (Euphrat-)Strom und nahm die Richtung nach dem Gebirge Gilead.',
        22: 'Am dritten Tage erhielt Laban die Kunde, dass Jakob entflohen sei.',
        23: 'Da nahm er seine Verwandten mit und jagte ihm nach, sieben Tagereisen weit, und er erreichte ihn auf dem Gebirge Gilead.',
        24: 'Aber Gott kam des Nachts im Traume zu dem Syrer Laban und sprach zu ihm: Hüte dich, Jakob mit irgendeinem Wort zur Rede zu stellen!',
        25: 'Als nun Laban den Jakob einholte - Jakob aber hatte sein Zelt auf dem Berge aufgeschlagen, und Laban hatte sein Zelt auf dem Gebirge Gilead aufgeschlagen, (1) der Name dieses Berges scheint ausgefallen zu sein.',
        26: 'da sprach Laban zu Jakob: Was hast du getan, dass du mich hintergangen und meine Töchter weggeführt hast wie Kriegsgefangene?',
        27: 'Warum bist du heimlich entflohen und hast mich getäuscht und mir nichts gesagt, dass ich dich mit Jubel und Gesängen, mit Handpauken und Harfen hätte geleiten können,',
        28: 'und hast mich meine Enkel und Töchter nicht küssen lassen? Da hast du töricht gehandelt.',
        29: 'Ich hätte wohl die Macht, dir Übles zu tun, aber der Gott deines Vaters hat heute nacht zu mir gesprochen: Hüte dich, Jakob mit irgendeinem Wort zur Rede zu stellen!',
        30: 'Nun, du bist eben weggezogen, weil dich so sehnlich nach deines Vaters Haus verlangte; aber warum hast du meinen Gott gestohlen?',
        31: 'Jakob antwortete und sprach zu Laban: Ich fürchtete mich; denn ich dachte, du würdest mir deine Töchter entreissen.',
        32: 'Der aber, bei dem du deinen Gott findest, der soll nicht am Leben bleiben! Vor unsern Verwandten untersuche, was ich bei mir habe, und nimm ihn an dich. Jakob wusste nämlich nicht, dass Rahel ihn gestohlen hatte.',
        33: 'Da ging Laban in das Zelt Jakobs und in das Zelt Leas und in das Zelt der beiden Mägde, aber er fand ihn nicht. Dann ging er aus dem Zelte Leas in das Zelt Rahels.',
        34: 'Rahel aber hatte den Theraphim genommen, ihn in den Kamelsattel gelegt und sich darauf gesetzt. Und Laban durchsuchte das ganze Zelt und fand ihn nicht.',
        35: 'Da sprach sie zu ihrem Vater: Mein Herr, zürne nicht, dass ich mich nicht vor dir erheben kann; denn es geht mir, wie es den Frauen geht. Also durchsuchte er alles, doch den Theraphim fand er nicht.',
        36: 'Jakob aber ward zornig und zankte mit Laban. Und Jakob hob an und sprach zu ihm: Was habe ich verbrochen, was habe ich gefehlt, dass du mich so hitzig verfolgt hast?',
        37: 'Du hast nun alle meine Sachen durchsucht; was hast du von all den Sachen deines Hauses gefunden? Lege es hier vor meine und deine Verwandten, dass sie zwischen uns beiden Recht sprechen!',
        38: 'Seit zwanzig Jahren bin ich jetzt bei dir; deine Schafe und Ziegen haben nicht fehlgeworfen, und die Widder deiner Herde habe ich nicht gegessen.',
        39: 'Was von wilden Tieren zerrissen war, durfte ich dir nicht bringen; ich selber musste es ersetzen, von meiner Hand fordertest du es, ob es am Tage geraubt war oder in der Nacht.',
        40: 'Am Tage verzehrte mich die Hitze und des Nachts der Frost, und der Schlaf floh meine Augen.',
        41: 'Zwanzig Jahre habe ich dir jetzt in deinem Hause gedient, vierzehn Jahre um deine beiden Töchter und sechs Jahre um deine Herde, und du hast mir den Lohn zehnmal verändert.',
        42: 'Wenn nicht der Gott meines Vaters, der Gott Abrahams und der Gefürchtete Isaaks, für mich gewesen wäre, du hättest mich jetzt mit leeren Händen ziehen lassen; mein Elend und die Arbeit meiner Hände hat Gott gesehen, und er hat heute nacht Recht gesprochen.',
        43: 'Laban antwortete und sprach zu Jakob: Die Töchter sind meine Töchter, die Kinder sind meine Kinder, und das Vieh ist mein Vieh, und alles, was du da siehst, ist mein; aber was kann ich heute für diese meine Töchter tun oder für ihre Kinder, die sie geboren haben?',
        44: 'So komm nun, wir wollen einen Vertrag schliessen, ich und du; wir wollen einen Steinhaufen machen, der soll Zeuge sein zwischen mir und dir.',
        45: 'Da nahm Jakob einen Stein und richtete ihn auf als Malstein.',
        46: 'Und Laban sprach zu seinen Verwandten: Leset Steine zusammen. Und sie lasen Steine auf und machten einen Haufen und hielten daselbst das Mahl auf dem Haufen.',
        47: 'Und Laban nannte ihn (in seiner Sprache) Jegar-Sahadutha, Jakob aber nannte ihn Gal-Ed.',
        48: 'Da sprach Laban: Der Haufe hier ist heute Zeuge zwischen mir und dir. Daher nannte er ihn Gal-Ed (1) d.i. Steinhaufe des Zeugnisses.',
        49: 'und Mizpa; denn er sprach: Der Herr möge wachen zwischen mir und dir, wenn wir einander nicht mehr sehen. (1) d.i. Hochwacht.',
        50: 'Solltest du je meine Töchter schlecht behandeln oder andre Frauen zu meinen Töchtern hinzunehmen - ob auch kein Mensch bei uns ist, siehe wohl zu: Gott ist Zeuge zwischen mir und dir!',
        51: 'Dann sprach Laban zu Jakob: Siehe, der Steinhaufe hier, und siehe, der Malstein hier, den ich errichtet haben zwischen mir und dir -',
        52: 'dieser Haufe ist Zeuge, und dieser Malstein ist Zeuge: ich darf nicht über diesen Haufen hinaus zu dir hinüber, und du darfst nicht über diesen Haufen und diesen Malstein hinaus zu mir herüber in böser Absicht.',
        53: 'Der Gott Abrahams und der Gott Nahors sei Richter zwischen uns! Und Jakob schwur bei dem Gefürchteten Isaaks, seines Vaters.',
        54: 'Darnach schlachtete er ein Opfer auf dem Berge und lud seine Verwandten ein, das Mahl zu halten. Und als sie gegessen hatten, blieben sie auf dem Berge übernacht.',
        55: 'Am andern Morgen aber in der Frühe küsste Laban seine Enkel und seine Töchter und segnete sie; dann zog Laban hin und kehrte zurück an seinen Ort. (1) die Lutherbibel hat für Kap. 31,55; 32,1-32 die Zählung 32,1-33.',
    },
    32: {
        1: 'AUCH Jakob zog seines Weges; da begegneten ihm auf einmal die Engel Gottes.',
        2: 'Als Jakob sie sah, sprach er: Dies ist das Heerlager Gottes. Darum nannte er jene Stätte Mahanaim. (1) d.i. Lager. (a) Ps 34:8',
        3: 'Darnach schickte Jakob Boten vor sich her zu seinem Bruder Esau in das Land Seir, ins Gefilde Edoms.',
        4: 'Und er befahl ihnen: So sollt ihr zu meinem Herrn Esau sprechen: Dein Knecht Jakob lässt dir sagen: Ich bin bei Laban in der Fremde gewesen und habe mich bis jetzt dort aufgehalten.',
        5: 'Ich habe Rinder, Esel und Schafe, Knechte und Mägde erworben, und nun sende ich meinem Herrn Botschaft, dass ich Gnade finde vor deinen Augen.',
        6: 'Die Boten kehrten zu Jakob zurück und sprachen: Wir sind zu deinem Bruder Esau gekommen; er zieht dir schon entgegen mit vierhundert Mann.',
        7: 'Da fürchtete sich Jakob sehr, und es ward ihm bange. Darum teilte er die Leute, die bei ihm waren, und die Schafe, Rinder und Kamele in zwei Lager;',
        8: 'denn er dachte: Wenn Esau auf das eine Lager trifft und schlägt es, so kann doch das andre Lager entrinnen.',
        9: 'Und Jakob sprach: O Gott meines Vaters Abraham und Gott meines Vaters Isaak, Herr, der du mir gesagt hast: "Kehre zurück in dein Land und zu deiner Verwandtschaft, ich will dir Gutes tun!" - (a) 1Mo 28:15; 31:3',
        10: 'ich bin zu gering aller Barmherzigkeit und aller Treue, die du an deinem Knechte getan hast. Denn nur mit meinem Stabe bin ich über den Jordan da gegangen, und nun bin ich zu zwei Heeren geworden.',
        11: 'Errette mich doch aus der Hand meines Bruders, aus der Hand Esaus; denn ich fürchte, er möchte kommen und mich schlagen, die Mutter samt den Kindern.',
        12: 'Du hast doch gesagt: "Ich will dir Gutes tun und dein Geschlecht zahlreich machen wie den Sand am Meer, den man nicht zählen kann vor Menge."',
        13: 'Und er blieb jene Nacht daselbst. Dann nahm er von dem, was er erworben hatte, ein Geschenk für seinen Bruder Esau:',
        14: 'zweihundert Ziegen und zwanzig Böcke, zweihundert Schafe und zwanzig Widder,',
        15: 'dreissig säugende Kamele mit ihren Füllen, vierzig Kühe und zehn Stiere, zwanzig Eselinnen mit zehn Füllen.',
        16: 'Und er übergab sie seinen Knechten, jede Herde besonders, und sprach zu seinen Knechten: Ziehet vor mir her und lasset Raum zwischen den einzelnen Herden.',
        17: 'Und dem ersten gebot er: Wenn dir mein Bruder Esau begegnet und dich fragt: "Wem gehörst du, und wo willst du hin? und wem gehören diese (Tiere, die du) vor dir (hertreibst)?"',
        18: 'so sollst du sagen: "Deinem Knecht Jakob; es ist ein Geschenk, das er meinem Herrn Esau sendet. Siehe, er kommt selber hinter uns her."',
        19: 'Gleicherweise gebot er auch dem zweiten und dem dritten und allen, die hinter den Herden hergingen: So, wie ich euch gesagt habe, sollt ihr zu Esau sprechen, wenn ihr ihn antrefft.',
        20: 'Ihr sollt sagen: "Siehe, dein Knecht Jakob kommt selber hinter uns her." Denn er dachte: Ich will ihn mit dem Geschenk, das vor mir her zieht, versöhnen; dann erst will ich sein Angesicht sehen, vielleicht nimmt er mich gnädig auf.',
        21: 'So zog das Geschenk vor ihm her; er aber blieb jene Nacht im Lager.',
        22: 'Noch in der Nacht stand er dann auf, nahm seine beiden Frauen und seine beiden Mägde und seine elf Söhne und ging über die Furt des Jabbok.',
        23: 'Er nahm sie und führte sie über den Fluss; auch all seine Habe brachte er hinüber.',
        24: 'Jakob aber blieb allein zurück. Da rang ein Mann mit ihm, bis die Morgenröte anbrach. (a) Hos 12:4',
        25: 'Als der sah, dass er ihn nicht zu überwältigen vermochte, schlug er ihn auf das Hüftgelenk. Und Jakobs Hüftgelenk wurde verrenkt, als er mit ihm rang.',
        26: 'Und er sprach: lass mich los; die Morgenröte bricht an. Aber er antwortete: Ich lasse dich nicht, du segnest mich denn.',
        27: 'Er sprach zu ihm: Wie heissest du? Er antwortete: Jakob.',
        28: 'Da sprach er: Du sollst nicht mehr Jakob heissen, sondern Israel. Denn du hast mit Gott und mit Menschen gestritten und hast obgesiegt. (1) d.i. Gottesstreiter. (a) 1Mo 35:10',
        29: 'Und Jakob fragte ihn: Sag an, wie heissest du? Er aber sprach: Warum fragst du, wie ich heisse? Und er segnete ihn daselbst. (a) Ri 13:17 18',
        30: 'Und Jakob nannte die Stätte Pniel; denn (sagte er) ich habe Gott von Angesicht zu Angesicht geschaut und bin am Leben geblieben. (1) d.i. Angesicht Gottes.',
        31: 'Und als er an Pniel vorüber war, ging die Sonne auf; er hinkte aber an der Hüfte.',
        32: 'Daher essen die Israeliten bis auf den heutigen Tag den Muskelstrang nicht, der auf dem Hüftgelenk liegt, weil er Jakob auf das Hüftgelenk schlug, auf den Muskelstrang.',
    },
    33: {
        1: 'ALS nun Jakob seine Augen erhob, sah er Esau herankommen und vierhundert Mann mit ihm. Da verteilte er die Kinder auf Lea und Rahel und die beiden Mägde,',
        2: 'und er stellte die Mägde mit ihren Kindern voran, dahinter Lea mit ihren Kindern, Rahel aber mit Joseph zuletzt.',
        3: 'Er selbst ging vor ihnen her und verneigte sich siebenmal zur Erde, bis er zu seinem Bruder kam.',
        4: 'Esau aber eilte ihm entgegen und umarmte ihn, fiel ihm um den Hals und küsste ihn, und sie weinten.',
        5: 'Als er nun seine Augen erhob und die Frauen mit den Kindern sah, sprach er: Wer sind diese da bei dir? Er antwortete: Es sind die Kinder, die Gott deinem Knechte aus Gnaden beschert hat.',
        6: 'Und die Mägde traten herzu mit ihren Kindern und verneigten sich.',
        7: 'Dann trat auch Lea herzu mit ihren Kindern, und sie verneigten sich. Darnach traten Joseph und Rahel herzu und verneigten sich.',
        8: 'Und er sprach: Was willst du denn mit diesem ganzen Heer, dem ich begegnet bin? Er antwortete: Dass ich Gnade finde vor meinem Herrn.',
        9: 'Esau sprach: Ich habe genug, mein Bruder; behalte, was du hast.',
        10: 'Jakob antwortete: Nicht doch! Habe ich Gnade vor dir gefunden, so nimm das Geschenk von mir an; denn ich habe ja dein Angesicht schauen dürfen, wie man Gottes Angesicht schaut, und du hast mich gütig aufgenommen.',
        11: 'Nimm doch die Gabe an, die ich dir gebracht habe; denn Gott hat es mir in Gnaden beschert, und ich habe vollauf. So drang er in ihn, bis er es annahm.',
        12: 'Und Esau sprach: Lass uns nun aufbrechen und fortziehen; ich will vor dir her ziehen.',
        13: 'Er aber sprach zu ihm: Mein Herr sieht, dass die Kinder noch zart sind und dass ich für die säugenden Schafe und Rinder zu sorgen habe; übertriebe man sie auch nur einen Tag, so würde mir die ganze Herde sterben.',
        14: 'Mein Herr ziehe doch seinem Knechte voraus. Ich will gemächlich nachtreiben, wie eben das Vieh vor mir und die Kinder wandern können, bis ich zu meinem Herrn nach Seir komme.',
        15: 'Esau sprach: So will ich doch von den Leuten, die ich bei mir habe, etliche bei dir lassen. Er antwortete: Wozu das? Möge ich nur Gnade finden vor meinem Herrn.',
        16: 'Da zog Esau an jenem Tage wieder seines Weges nach Seir.',
        17: 'Jakob aber zog nach Sukkoth und baute sich ein Haus; für sein Vieh aber machte er Hütten. Daher nannte er die Stätte Sukkoth. (1) d.i. Hütten.',
        18: 'Darnach kam Jakob wohlbehalten zu der Stadt Sichem im Lande Kanaan, als er aus Mesopotamien kam, und lagerte vor der Stadt.',
        19: 'Und er kaufte das Grundstück, auf dem er sein Zelt aufgeschlagen hatte, von den Söhnen Hemors, des Vaters Sichems, um hundert Taler.',
        20: 'Dort richtete er einen Malstein auf und baute einen Altar und nannte ihn "El, Gott Israels".',
    },
    34: {
        1: 'DINA aber, die Tochter Jakobs, die Lea ihm geboren hatte, ging einst aus, um sich die Mädchen des Landes anzusehen.',
        2: 'Als nun Sichem, der Sohn des Hewiters Hemor, des Landesfürsten, sie sah, ergriff er sie und wohnte ihr bei und tat ihr so Gewalt an.',
        3: 'Aber sein Herz hing an Dina, der Tochter Jakobs, und er hatte das Mädchen lieb und redete ihr freundlich zu.',
        4: 'Und Sichem sprach zu seinem Vater Hemor: Wirb für mich um dieses Mädchen!',
        5: 'Jakob aber erfuhr, dass er seine Tochter Dina geschändet habe; doch weil seine Söhne mit dem Vieh auf dem Felde waren, schwieg Jakob stille, bis sie heimkamen.',
        6: 'Da ging Hemor, Sichems Vater, hinaus zu Jakob, um mit ihm zu reden.',
        7: 'Als nun die Söhne Jakobs vom Felde heimkamen, hörten sie davon; da wurden die Männer aufgebracht und sehr zornig, dass er eine Schandtat in Israel begangen hatte, indem er Jakobs Tochter beiwohnte; dergleichen durfte nicht geschehen!',
        8: 'Hemor aber redete mit ihnen und sprach: Mein Sohn Sichem hängt mit ganzer Seele an eurer Tochter; gebt sie ihm doch zum Weibe!',
        9: 'Verschwägert euch mit uns: ihr mögt uns eure Töchter geben und euch unsre Töchter nehmen,',
        10: 'und bleibt bei uns wohnen; das Land soll euch offenstehen: bleibt, tut euch darin um und werdet hier ansässig!',
        11: 'Und Sichem sprach zu ihrem Vater und zu ihren Brüdern: Tut mir doch den Gefallen! Was ihr von mir verlangt, das will ich geben.',
        12: 'Ihr mögt von mir einen noch so grossen Brautpreis fordern und Geschenke, ich will sie geben, wie ihr sie von mir fordert; nur gebt mir das Mädchen zum Weibe! (a) 2Mo 22:16',
        13: 'Da antworteten Jakobs Söhne dem Sichem und seinem Vater Hemor mit hinterlistiger Rede, weil er ihre Schwester geschändet hatte;',
        14: 'sie sprachen zu ihnen: Es ist uns unmöglich, unsre Schwester einem unbeschnittenen Manne zu geben; denn das gilt uns für eine Schande.',
        15: 'Nur unter der Bedingung wollen wir euch zu Willen sein, wenn ihr uns gleich werdet, indem ihr alles, was unter euch männlich ist, beschneiden lasst.',
        16: 'Dann wollen wir euch unsre Töchter geben und uns eure Töchter nehmen, wir wollen bei euch wohnen und ein Volk (mit euch) werden.',
        17: 'Wenn ihr euch aber nicht, wie wir verlangen, wollt beschneiden lassen, so nehmen wir unsre Tochter und ziehen von dannen.',
        18: 'Diese Worte gefielen Hemor und seinem Sohne Sichem.',
        19: 'Und der junge Mann zögerte nicht, darnach zu tun; denn er hatte Gefallen gefunden an der Tochter Jakobs, und er war der Angesehenste in seines Vaters Hause.',
        20: 'So gingen denn Hemor und sein Sohn Sichem unter das Tor ihrer Stadt und sprachen zu den Bürgern ihrer Stadt:',
        21: 'Diese Leute sind friedlich gesinnt, so lasst sie bei uns im Lande wohnen und darin sich umtun; das Land hat ja nach allen Seiten Raum genug für sie. Wir wollen uns ihre Töchter zu Frauen nehmen und ihnen unsre Töchter geben.',
        22: 'Allein, nur dann willigen die Leute ein, bei uns zu wohnen und ein Volk (mit uns) zu werden, wenn wir alles, was unter uns männlich ist, beschneiden lassen, gleich wie sie beschnitten sind.',
        23: 'Uns gehören ja dann ihre Herden, ihre Habe und all ihr Vieh. Ja, lasst uns ihnen zu Willen sein, dass sie bei uns wohnen bleiben.',
        24: 'Da willfahrten sie Hemor und seinem Sohne Sichem, alle die im Tore seiner Stadt aus und ein gingen, und liessen sich beschneiden, alles, was männlich war, alle, die im Tore seiner Stadt aus und ein gingen.',
        25: 'Am dritten Tage aber, als es sie schmerzte, nahmen zwei der Söhne Jakobs, Simeon und Levi, Dinas Brüder, ein jeder sein Schwert, drangen ungefährdet in die Stadt ein und töteten alles, was männlich war.',
        26: 'Auch Hemor und seinen Sohn Sichem töteten sie mit der Schärfe des Schwertes, nahmen Dina aus dem Hause Sichems und gingen davon.',
        27: 'Die Söhne Jakobs fielen über die Kranken her und plünderten die Stadt, weil sie ihre Schwester geschändet hatten.',
        28: 'Ihre Schafe, Rinder und Esel, was in der Stadt und was auf dem Felde war, nahmen sie weg,',
        29: 'all ihre Habe, all ihre Kinder und Frauen führten sie fort und plünderten alles, was in den Häusern war.',
        30: 'Da sprach Jakob zu Simeon und Levi: Ihr bringt mich ins Unglück, indem ihr mich bei den Bewohnern des Landes, den Kanaanitern und Pheresitern, verhasst macht, wo ich doch nur wenig Leute habe. Wenn sie sich nun wider mich zusammentun, so werden sie mich schlagen, und ich werde samt meinem Hause vertilgt.',
        31: 'Aber sie antworteten: Soll er unsere Schwester wie eine Dirne behandeln dürfen?',
    },
    35: {
        1: 'UND Gott sprach zu Jakob: Mache dich auf, ziehe hinauf nach Bethel und bleibe daselbst, und baue dort einen Altar dem Gott, der dir erschienen ist, als du vor deinem Bruder Esau flohst. (a) 1Mo 28:11-22',
        2: 'Da sprach Jakob zu seinem Hause und zu allen, die bei ihm waren: Schafft die fremden Götter weg, die unter euch sind, und reinigt euch und wechselt eure Kleider. (a) 1Mo 31:19; Jos 24:2',
        3: 'Dann wollen wir uns aufmachen und hinauf nach Bethel ziehen; dort will ich einen Altar bauen dem Gott, der mich zur Zeit meiner Drangsal erhört hat und mit mir gewesen ist auf dem Wege, den ich gezogen bin.',
        4: 'Da gaben sie Jakob alle fremden Götter, die sie bei sich hatten, und ihre Ohrringe, und er vergrub sie unter der Terebinthe, die bei Sichem steht.',
        5: 'Darnach brachen sie auf; der Schrecken Gottes aber kam über die Städte ringsumher, sodass sie die Söhne Jakobs nicht verfolgten.',
        6: 'So kam Jakob nach Lus im Lande Kanaan - das ist Bethel -, er und alle Leute, die bei ihm waren.',
        7: 'Und er baute dort einen Altar und nannte die Stätte El-Bethel, weil sich Gott ihm dort geoffenbart hatte, als er vor seinem Bruder floh. (1) d.i. der Gott von Bethel.',
        8: 'Da starb Debora, die Amme der Rebekka, und ward begraben unterhalb Bethel unter der Eiche; dieser gab er den Namen "Klageeiche". (a) 1Mo 24:59',
        9: 'Und Gott erschien dem Jakob abermals, als er aus Mesopotamien kam, und segnete ihn.',
        10: 'Und Gott sprach zu ihm: Du heissest Jakob; aber du sollst nicht mehr Jakob heissen, sondern Israel soll dein Name sein. Und er nannte ihn Israel. (a) 1Mo 32:28',
        11: 'Dann sprach Gott zu ihm: Ich bin der allmächtige Gott, sei fruchtbar und mehre dich; ein Volk, ja eine Gemeinde von Völkern soll von dir kommen, und Könige sollen aus deinen Lenden hervorgehen. (a) 1Mo 17:1',
        12: 'Und das Land, das ich Abraham und Isaak gegeben habe, dir will ich es geben, und auch deinen Nachkommen will ich das Land geben.',
        13: 'Dann fuhr Gott auf von ihm, an der Stätte, wo er mit ihm geredet hatte.',
        14: 'Jakob aber errichtete ein Mal an der Stätte, wo er mit ihm geredet hatte, ein steinernes Mal, und er spendete ein Trankopfer darauf und goss Öl darüber.',
        15: 'Und Jakob nannte die Stätte, wo Gott mit ihm geredet hatte, Bethel.',
        16: 'Darnach brachen sie von Bethel auf, und als sie nur noch ein Stück Weges bis Ephrath hatten, gebar Rahel, und die Geburt kam sie schwer an.',
        17: 'Und da sie eine so schwere Geburt hatte, sprach die Hebamme zu ihr: Sei getrost, du hast wieder einen Sohn.',
        18: 'Als aber ihre Seele entfloh - denn sie musste sterben -, da nannte sie ihn Ben-Oni; sein Vater aber nannte ihn Ben-Jamin. (1) d.i. Sohn meines Schmerzes. (2) d.i. Sohn des Glücks.',
        19: 'So starb Rahel und ward begraben am Wege nach Ephrath, das ist Bethlehem.',
        20: 'Und Jakob errichtete auf ihrem Grabe einen Malstein. Das ist der Malstein des Rahelgrabes bis auf den heutigen Tag.',
        21: 'Dann zog Israel weiter und schlug sein Zelt auf jenseits von Migdal-Eder.',
        22: 'In der Zeit nun, da Israel dortzulande wohnte, ging Ruben hin und schlief bei Bilha, dem Nebenweibe seines Vaters. Israel aber erfuhr es und ward zornig darob. Jakob hatte zwölf Söhne.',
        23: 'Die Söhne Leas waren: Ruben der Erstgeborne Jakobs, Simeon, Levi, Juda, Issaschar und Sebulon;',
        24: 'die Söhne Rahels: Joseph und Benjamin;',
        25: 'die Söhne Bilhas, der Magd Rahels: Dan und Naphthali;',
        26: 'die Söhne Silpas, der Magd Leas: Gad und Asser. Dies sind die Söhne Jakobs, die ihm in Mesopotamien geboren wurden.',
        27: 'Und Jakob kam zu seinem Vater Isaak nach Mamre, nach Kirjath-Arba - das ist Hebron -, wo Abraham und Isaak Fremdlinge gewesen waren.',
        28: 'Isaak aber wurde 180 Jahre alt.',
        29: 'Dann verschied Isaak und starb und ward versammelt zu seinen Stammesgenossen, alt und lebenssatt; und seine Söhne Esau und Jakob begruben ihn.',
    },
    36: {
        1: 'DIES ist die Nachkommenschaft Esaus - das ist Edom.',
        2: 'Esau hatte seine Frauen aus den Töchtern Kanaans genommen: Ada, die Tochter des Hethiters Elon, und Oholibama, die Tochter Anas, des Sohnes Zibeons, des Horiters, (a) 1Mo 26:34; 28:9',
        3: 'und Basmath, die Tochter Ismaels, die Schwester Nebajoths.',
        4: 'Ada gebar dem Esau den Eliphas, Basmath gebar den Reguel,',
        5: 'und Oholibama gebar den Jehus, den Jaelam und den Korah. Dies sind die Söhne Esaus, die ihm im Lande Kanaan geboren wurden.',
        6: 'Und Esau nahm seine Frauen, seine Söhne und Töchter und alle Seelen seines Hauses, auch seine Habe und all sein Vieh und allen Besitz, den er im Lande Kanaan erworben hatte, und zog von seinem Bruder Jakob weg ins Land Seir.',
        7: 'Denn ihr Besitz war zu gross, als dass sie beieinander bleiben konnten; und das Land, wo sie als Fremdlinge weilten, vermochte sie nicht zu erhalten wegen ihrer Herden. (a) 1Mo 13:6',
        8: 'So liess sich Esau auf dem Gebirge Seir nieder - Esau, das ist Edom.',
        9: 'Das ist die Nachkommenschaft Esaus, des Vaters der Edomiter auf dem Gebirge Seir.',
        10: 'Dies sind die Namen der Söhne Esaus: Eliphas, der Sohn Adas, des Weibes Esaus; Reguel, der Sohn Basmaths, des Weibes Esaus.',
        11: 'Die Söhne des Eliphas aber waren Theman, Omar, Zepho, Gaetham und Kenas.',
        12: 'Und Thimna war ein Nebenweib des Eliphas, des Sohnes Esaus; sie gebar dem Eliphas den Amalek. Das sind die Söhne Adas, des Weibes Esaus.',
        13: 'Dies sind die Söhne Reguels: Nahath, Serah, Samma und Missa. Das waren die Söhne Basmaths, des Weibes Esaus.',
        14: 'Und dies waren die Söhne Oholibamas, des Weibes Esaus, der Tochter Anas, des Sohnes Zibeons: sie gebar dem Esau den Jehus, den Jaelam und den Korah.',
        15: 'Dies sind die Fürsten der Söhne Esaus: die Söhne des Eliphas, des Erstgebornen Esaus: der Fürst von Theman, der Fürst von Omar, der Fürst von Zepho, der Fürst von Kenas,',
        16: 'der Fürst von Korah, der Fürst von Gaetham, der Fürst von Amalek. Das sind die Fürsten von Eliphas im Lande Edom; das sind die Söhne der Ada.',
        17: 'Dies sind die Söhne Reguels, des Sohnes Esaus: der Fürst von Nahath, der Fürst von Serah, der Fürst von Samma, der Fürst von Missa. Das sind die Fürsten von Reguel im Lande Edom; das sind die Söhne der Basmath, des Weibes Esaus.',
        18: 'Dies sind die Söhne Oholibamas, des Weibes Esaus: der Fürst von Jehus, der Fürst von Jaelam, der Fürst von Korah. Das sind die Fürsten von Oholibama, der Tochter Anas, dem Weibe Esaus.',
        19: 'Das sind die Söhne Esaus, und das sind ihre Fürsten - das ist Edom.',
        20: 'Dies sind die Söhne Seirs, des Horiters, die (Ur-)Einwohner des Landes: Lotan, Sobal, Zibeon, Ana,',
        21: 'Dison, Ezer und Disan. Das sind die Fürsten der Horiter, die Söhne Seirs im Lande Edom.',
        22: 'Die Söhne Lotans waren Hori und Hemam; und Lotans Schwester war Thimna.',
        23: 'Dies sind die Söhne Sobals: Alwan, Manahath, Ebal, Sepho und Onam.',
        24: 'Dies sind die Söhne Zibeons: Aja und Ana. Das ist der Ana, der die heissen Quellen in der Wüste fand, als er die Esel seines Vaters Zibeon hütete.',
        25: 'Dies sind die Söhne Anas: Dison; und Oholibama ist die Tochter Anas.',
        26: 'Dies sind die Söhne Disons: Hemdan, Esban, Jithran und Cheran.',
        27: 'Dies sind die Söhne Ezers: Bilhan, Saewan und Akan.',
        28: 'Dies sind die Söhne Disans: Uz und Aran.',
        29: 'Dies sind die Fürsten der Horiter: der Fürst von Lotan, der Fürst von Sobal, der Fürst von Zibeon, der Fürst von Ana,',
        30: 'der Fürst von Dison, der Fürst von Ezer, der Fürst von Disan. Das sind die Fürsten der Horiter nach ihren Fürstentümern im Lande Seir.',
        31: 'Dies sind die Könige, die im Lande Edom regiert haben, ehe ein König regierte in Israel:',
        32: 'Bela, der Sohn Beors, ward König über Edom; seine Stadt hiess Dinhaba.',
        33: 'Als Bela starb, ward Jobab, der Sohn Serahs aus Bozra, König an seiner Statt.',
        34: 'Als Jobab starb, ward Husam aus dem Land der Themaniter König an seiner Statt.',
        35: 'Als Husam starb, ward Hadad, der Sohn Bedads, König an seiner Statt; der schlug die Midianiter im Gefilde Moabs; seine Stadt hiess Awith.',
        36: 'Als Hadad starb, ward Samla aus Masreka König an seiner Statt.',
        37: 'Als Samla starb, ward Saul aus Rehoboth am Flusse König an seiner Statt.',
        38: 'Als Saul starb, ward Baal-Hanan, der Sohn Achbors, König an seiner Statt.',
        39: 'Als Baal-Hanan, der Sohn Achbors, starb, ward Hadar König an seiner Statt; seine Stadt hiess Pahu, und sein Weib hiess Mehetabel, die Tochter der Matred, der Tochter Mesahabs.',
        40: 'Dies sind die Namen der Fürsten Esaus nach ihren Geschlechtern, ihren Orten, ihren Namen: der Fürst von Thimna, der Fürst von Alwa, der Fürst von Jetheth,',
        41: 'der Fürst von Oholibama, der Fürst von Ela, der Fürst von Pinon,',
        42: 'der Fürst von Kenas, der Fürst von Theman, der Fürst von Mibzar,',
        43: 'der Fürst von Magdiel, der Fürst von Iram. Das sind die Fürsten von Edom nach ihren Wohnsitzen in dem Lande, das sie besetzt hatten - das ist von Esau, dem Vater der Edomiter.',
    },
    37: {
        1: 'Jakob aber blieb in dem Lande, wo sein Vater als Fremdling geweilt hatte, im Lande Kanaan.',
        2: 'DIES ist die Geschichte Jakobs: Als Joseph siebzehn Jahre alt war, hütete er die Schafe mit seinen Brüdern - er war aber noch jung -, mit den Söhnen Bilhas und Silpas, der Frauen seines Vaters, und was man ihnen Schlimmes nachsagte, hinterbrachte Joseph ihrem Vater.',
        3: 'Israel aber hatte Joseph lieber als alle seine andern Söhne, weil er ihm erst im Alter geboren war, und er liess ihm einen Rock mit Ärmeln machen.',
        4: 'Als nun seine Brüder sahen, dass ihr Vater ihn lieber hatte als alle seine andern Söhne, wurden sie ihm feind und mochten ihm kein freundliches Wort mehr gönnen.',
        5: 'Einst hatte Joseph einen Traum und erzählte ihn seinen Brüdern.',
        6: 'Und er sprach zu ihnen: Hört einmal, was mir geträumt hat!',
        7: 'Wir waren am Garbenbinden auf dem Felde; da richtete sich auf einmal meine Garbe auf und blieb stehen, eure Garben aber stellten sich ringsherum und verneigten sich vor meiner Garbe.',
        8: 'Da sprachen seine Brüder zu ihm: Du willst wohl gar unser König werden oder über uns herrschen? Und sie hassten ihn noch mehr um seiner Träume und um seiner Worte willen.',
        9: 'Darnach hatte er noch einen andern Traum; den erzählte er seinen Brüdern auch und sprach: Seht, ich habe noch einen Traum gehabt: die Sonne und der Mond und elf Sterne verneigten sich vor mir.',
        10: 'Das erzählte er seinem Vater und seinen Brüdern. Da schalt ihn sein Vater und sprach zu ihm: Was ist das für ein Traum, den du da gehabt hast? Sollen etwa ich und deine Mutter und deine Brüder kommen und vor dir niederfallen?',
        11: 'Und seine Brüder wurden neidisch auf ihn, sein Vater aber behielt die Sache im Sinn.',
        12: 'Als nun seine Brüder hingingen, die Schafe ihres Vaters bei Sichem zu weiden,',
        13: 'sprach Israel zu Joseph: Du weisst, deine Brüder weiden bei Sichem. Komm, ich will dich zu ihnen senden. Er erwiderte: Hier bin ich.',
        14: 'Und er sprach zu ihm: Geh hin und schau, ob es wohlsteht um deine Brüder und ob es wohlsteht um die Herde, und bringe mir Bericht. So sandte er ihn hin aus dem Tal von Hebron, und er kam nach Sichem.',
        15: 'Da traf ihn ein Mann, wie er auf dem Felde umherirrte. Der Mann fragte ihn: Was suchst du?',
        16: 'Er antwortete: Ich suche meine Brüder; sage mir doch, wo sie hüten.',
        17: 'Der Mann sprach: Sie sind von hier weggezogen; denn ich hörte, wie sie sagten: "Lasst uns nach Dothan gehen." Da ging Joseph seinen Brüdern nach und fand sie bei Dothan.',
        18: 'Als sie ihn nun von ferne sahen, machten sie, bevor er nahe zu ihnen herankam, einen Anschlag, ihn zu töten,',
        19: 'und sprachen zueinander: Seht, da kommt der Träumer her!',
        20: 'Wohlan, wir wollen ihn töten und in eine der Zisternen werfen und hernach sagen, ein wildes Tier habe ihn gefressen; dann werden wir ja sehen, was aus seinen Träumen wird.',
        21: 'Als Ruben das hörte, suchte er ihn aus ihrer Hand zu erretten und sprach: Ans Leben wollen wir ihm nicht!',
        22: 'Dann sprach Ruben zu ihnen: Vergiesst kein Blut! Werft ihn in diese Zisterne da in der Wüste, doch legt nicht Hand an ihn! Er wollte ihn aber aus ihrer Hand erretten, um ihn zu seinem Vater zurückzubringen.',
        23: 'Als nun Joseph zu seinen Brüdern kam, zogen sie ihm seinen Rock aus, den Ärmelrock, den er anhatte.',
        24: 'Und sie ergriffen ihn und warfen ihn in die Zisterne; die Zisterne aber war leer, es war kein Wasser darin.',
        25: 'Dann setzten sie sich nieder, um zu essen. Als sie nun ihre Augen erhoben, sahen sie eine Karawane von Ismaelitern daherkommen, aus Gilead, die ihre Kamele mit Gummi, Balsam und Harz beladen hatten und damit nach Ägypten hinab unterwegs waren.',
        26: 'Da sprach Juda zu seinen Brüdern: Was nützte es uns, wenn wir unsern Bruder erschlügen und sein Blut zudeckten?',
        27: 'Kommt, wir wollen ihn an die Ismaeliter verkaufen, aber uns nicht an ihm vergreifen; er ist doch unser Bruder und unser Fleisch. Und seine Brüder hörten auf ihn.',
        28: 'Es kamen aber midianitische Kaufleute vorüber, und sie zogen Joseph aus der Zisterne herauf. Und sie verkauften Joseph um zwanzig Lot Silber an die Ismaeliter; die brachten Joseph nach Ägypten. (a) Mt 26:15',
        29: 'Als nun Ruben wieder zu der Zisterne kam, siehe, da war Joseph nicht mehr darin. Und er zerriss seine Kleider,',
        30: 'kehrte zu seinen Brüdern zurück und sprach: Der Knabe ist nicht mehr da! Wo soll ich nun hin?',
        31: 'Da nahmen sie den Rock Josephs, schlachteten einen Ziegenbock und tauchten den Rock in das Blut.',
        32: 'Dann schickten sie den Ärmelrock hin, brachten ihn ihrem Vater und sagten: Das haben wir gefunden. Sieh es an, ob es deines Sohnes Rock ist oder nicht.',
        33: 'Und als er ihn ansah, sprach er: Es ist meines Sohnes Rock. Ein wildes Tier hat ihn gefressen. Fürwahr, zerrissen ist Joseph.',
        34: 'Und Jakob zerriss seine Kleider und legte ein Trauergewand um seine Hüften; und er trug lange Zeit Leid um seinen Sohn.',
        35: 'Da erhoben sich alle seine Söhne und Töchter, ihn zu trösten. Aber er wollte sich nicht trösten lassen und sprach: Nein, trauernd werde ich zu meinem Sohn ins Totenreich hinunterfahren. So beweinte ihn sein Vater.',
        36: 'Die Midianiter aber verkauften Joseph nach Ägypten an Potiphar, den Kämmerer des Pharao, den Obersten der Leibwache.',
    },
    38: {
        1: 'UM jene Zeit begab es sich, dass Juda von seinen Brüdern wegzog und sich an einen Mann aus Adullam mit Namen Hira anschloss.',
        2: 'Und Juda sah daselbst die Tochter eines Kanaaniters namens Sua, und er nahm sie zum Weibe und wohnte ihr bei.',
        3: 'Da ward sie schwanger und gebar einen Sohn; den nannte sie Er.',
        4: 'Dann ward sie abermals schwanger und gebar einen Sohn, den nannte sie Onan.',
        5: 'Sodann gebar sie noch einen Sohn, den nannte sie Sela; sie befand sich aber in Chesib, als sie ihn gebar.',
        6: 'Und Juda freite seinem Erstgebornen Er ein Weib mit Namen Thamar.',
        7: 'Aber Er, der Erstgeborne Judas, missfiel dem Herrn; darum liess der Herr ihn sterben.',
        8: 'Da sprach Juda zu Onan: Gehe zu dem Weibe deines Bruders und vollziehe mit ihr die Pflichtehe, dass du deinem Bruder Nachkommen schaffest. (a) 5Mo 25:5',
        9: 'Da aber Onan wusste, dass die Kinder nicht als die seinen gelten sollten, liess er es, wenn er zum Weibe seines Bruders ging, auf die Erde fallen und so verderben, um seinem Bruder nicht Nachkommen zu verschaffen.',
        10: 'Aber dem Herrn missfiel, was er tat, und er liess ihn auch sterben.',
        11: 'Da sprach Juda zu seiner Schwiegertochter Thamar: Bleibe als Witwe im Hause deines Vaters, bis mein Sohn Sela gross wird. Denn er dachte: auch er könnte sterben wie seine Brüder. So ging Thamar hin und blieb im Hause ihres Vaters.',
        12: 'Und die Jahre vergingen; da starb die Tochter Suas, das Weib Judas. Als nun die Trauerzeit um war, ging Juda einst mit seinem Freunde Hira von Adullam zu seinen Schafscherern hinauf nach Thimna.',
        13: 'Nun sagte man der Thamar: Siehe, dein Schwiegervater geht hinauf nach Thimna, seine Schafe zu scheren.',
        14: 'Da legte sie ihre Witwenkleider ab, bedeckte sich mit dem Schleier und verhüllte sich; dann setzte sie sich an das Tor von Enaim, am Wege nach Thimna. Denn sie hatte gesehen, dass Sela herangewachsen war, und doch war sie ihm nicht zum Weibe gegeben worden.',
        15: 'Als Juda sie sah, hielt er sie für eine Dirne; denn sie hatte ihr Angesicht verhüllt.',
        16: 'Und er bog zu ihr ab am Wege und sprach: Lass mich dir beiwohnen. Denn er wusste nicht, dass es seine Schwiegertochter war. Sie antwortete: Was gibst du mir, wenn du zu mir kommen darfst?',
        17: 'Er sprach: Ich will dir ein Ziegenböcklein von der Herde schicken. Sie erwiderte: Wenn du mir ein Pfand gibst, bis du es schickst.',
        18: 'Er sprach: Was willst du, dass ich dir zum Pfande gebe? Sie antwortete: Deinen Siegelring und deine Schnur und den Stab in deiner Hand. Da gab er es ihr und wohnte ihr bei, und sie ward von ihm schwanger.',
        19: 'Und sie stand auf und ging ihres Weges, legte ihren Schleier ab und zog ihre Witwenkleider wieder an.',
        20: 'Juda aber sandte das Ziegenböcklein durch seinen Freund von Adullam, um das Pfand von dem Weibe wieder zu bekommen; der aber fand sie nicht.',
        21: 'Da fragte er die Leute an dem Orte: Wo ist die geweihte Buhle, die bei Enaim am Wege sass? Sie antworteten: Es ist gar keine geweihte Buhle hier gewesen.',
        22: 'Und er kam wieder zu Juda und sprach: Ich habe sie nicht gefunden; auch sagen die Leute an dem Orte, es sei gar keine geweihte Buhle dagewesen.',
        23: 'Da sprach Juda: So mag sie es behalten, dass wir nicht ins Gerede kommen. Nun, ich habe das Böcklein geschickt, du hast sie aber nicht gefunden.',
        24: 'Etwa drei Monate später aber wurde Juda hinterbracht: Deine Schwiegertochter Thamar hat Unzucht getrieben und ist davon nun auch schwanger geworden. Da sprach Juda: Führt sie hinaus, sie soll verbrannt werden.',
        25: 'Schon wurde sie hinausgeführt, da schickte sie zu ihrem Schwiegervater und liess ihm sagen: Von dem Manne, dem dies hier gehört, bin ich schwanger. Und sie sprach: Sieh es an; wem gehören diese Dinge, der Siegelring und die Schnur und der Stab?',
        26: 'Als Juda genauer zusah, sprach er: Sie ist im Rechte gegen mich; warum habe ich sie meinem Sohne Sela nicht gegeben! Doch verkehrte er nicht mehr mit ihr.',
        27: 'Als nun die Zeit kam, dass sie gebären sollte, siehe, da hatte sie Zwillinge.',
        28: 'Bei der Geburt aber streckte einer eine Hand vor; die Hebamme ergriff sie und band einen roten Faden darum. Das wollte sagen: Der ist zuerst gekommen.',
        29: 'Als er aber seine Hand zurückzog, da kam sein Bruder heraus. Und sie sprach: Wie hast du dir doch einen Riss gerissen! Und man nannte ihn Perez. (1) d.i. Riss.',
        30: 'Darnach kam sein Bruder heraus, der den roten Faden um die Hand hatte; den nannte man Serah.',
    },
    39: {
        1: 'ALS aber Joseph nach Ägypten hinabgeführt worden war, kaufte ihn Potiphar, der Kämmerer des Pharao, der Oberste der Leibwache, ein Ägypter, von den Ismaelitern, die ihn dorthin gebracht hatten. (a) 1Mo 37:36',
        2: 'Und der Herr war mit Joseph, und es geriet ihm alles wohl, sodass er im Hause seines Gebieters, des Ägypters, bleiben durfte.',
        3: 'Als nun sein Gebieter sah, dass der Herr mit ihm war und dass der Herr alles, was er tat, in seiner Hand wohl gelingen liess,',
        4: 'kam Joseph in grosse Gunst bei ihm und wurde sein Leibdiener; und er setzte ihn über sein Haus, und alles, was er hatte, übergab er ihm.',
        5: 'Und von der Zeit an, da er ihn über sein Haus und alle seine Güter gesetzt hatte, segnete der Herr das Haus des Ägypters um Josephs willen, und der Segen des Herrn ruhte auf allem, was er hatte, in Haus und Feld.',
        6: 'Darum überliess er Joseph alles, was er hatte, und kümmerte sich neben ihm um nichts als um die Speise, die er ass. Joseph aber war schön von Gestalt und schön von Aussehen.',
        7: 'Darnach begab es sich, dass die Frau seines Herrn ihre Augen auf Joseph warf und sprach: Lege dich zu mir!',
        8: 'Er aber weigerte sich und sprach zu der Frau seines Herrn: Sieh, mein Herr kümmert sich neben mir um nichts im Hause, und alles, was er besitzt, hat er mir übergeben.',
        9: 'Er selbst ist in diesem Hause nicht grösser als ich; er hat mir nichts vorenthalten als dich, weil du sein Weib bist. Wie sollte ich da ein so grosses Unrecht begehen und wider Gott sündigen?',
        10: 'Und ob sie auch täglich Joseph zuredete, hörte er nicht auf sie, dass er sich zu ihr gelegt hätte, um mit ihr Umgang zu pflegen.',
        11: 'Es begab sich aber eines Tages, dass Joseph ins Haus kam, seine Geschäfte zu besorgen, als gerade niemand vom Gesinde zugegen war.',
        12: 'Da fasste sie ihn beim Kleide und sprach: Lege dich zu mir! Er aber liess sein Kleid in ihrer Hand und floh und lief zum Hause hinaus.',
        13: 'Als sie nun sah, dass er sein Kleid in ihrer Hand gelassen hatte und zum Hause hinaus geflohen war,',
        14: 'rief sie ihr Gesinde und sprach zu ihnen: Seht, da hat er uns einen Hebräer ins Haus gebracht, dass der seinen Mutwillen mit uns treibe. Er kam zu mir herein, um sich zu mir zu legen; aber ich schrie laut.',
        15: 'Und als er hörte, dass ich ein Geschrei erhob und rief, liess er sein Kleid neben mir und floh und lief zum Hause hinaus.',
        16: 'Und sie liess sein Kleid neben sich liegen, bis sein Herr heimkam.',
        17: 'Da erzählte sie ihm dieselbe Geschichte und sprach: Der hebräische Sklave, den du uns ins Haus gebracht hast, dass er seinen Mutwillen mit mir treibe, ist zu mir hereingekommen.',
        18: 'Wie ich aber ein Geschrei erhob und rief, liess er sein Kleid neben mir und floh zum Hause hinaus.',
        19: 'Als sein Herr die Geschichte hörte, die ihm seine Frau erzählte, indem sie sagte: "So und so hat dein Sklave an mir getan", ward er sehr zornig,',
        20: 'und er nahm Joseph und legte ihn in das Gefängnis, wo die Gefangenen des Königs in Gewahrsam lagen. Und er blieb daselbst im Gefängnis.',
        21: 'Der Herr aber war mit Joseph und machte ihn beliebt und erwarb ihm die Gunst des Aufsehers über das Gefängnis,',
        22: 'also dass ihm dieser alle Gefangenen im Gefängnis anvertraute; alles, was dort geschah, geschah durch ihn.',
        23: 'Der Aufseher über das Gefängnis kümmerte sich um nichts, was in seiner Hand lag, weil der Herr mit ihm war; und der Herr gab Glück zu allem, was er tat.',
    },
    40: {
        1: 'DARNACH begab es sich, dass der Mundschenk und der Bäcker des Königs von Ägypten sich wider ihren Herrn, den König von Ägypten, vergingen.',
        2: 'Da ward der Pharao zornig über seine zwei Hofbeamten, über den Obermundschenken und über den Oberbäcker,',
        3: 'und er gab sie in Gewahrsam in das Haus des Obersten der Leibwache, in das Gefängnis, wo Joseph gefangenlag.',
        4: 'Und der Oberste der Leibwache gab ihnen Joseph bei, dass er sie bediene; so waren sie eine Zeitlang im Gefängnis.',
        5: 'Da hatten sie beide in derselben Nacht einen Traum, jeder einen andern, jeder einen Traum von besonderer Bedeutung, der Mundschenk und der Bäcker des Königs von Ägypten, die im Gefängnis lagen.',
        6: 'Als nun Joseph am Morgen zu ihnen hereinkam, sah er, dass sie verdriesslich waren.',
        7: 'Da fragte er die Hofbeamten des Pharao, die bei ihm im Hause seines Herrn in Gewahrsam lagen: Warum seht ihr heute so missmutig aus?',
        8: 'Sie antworteten ihm: Es hat uns geträumt, und wir haben niemand, der es uns auslegt. Joseph sprach zu ihnen: Traumdeutung steht bei Gott. Doch erzählt mir einmal. (a) 1Mo 41:16; Da 2:28',
        9: 'Da erzählte der Obermundschenk dem Joseph seinen Traum und sprach zu ihm: Mir träumte, ich sehe einen Weinstock vor mir',
        10: 'und an dem Weinstock drei Schosse, und sobald er trieb, stand er auch schon in voller Blüte, und seine Trauben hatten reife Beeren.',
        11: 'Ich aber hielt den Becher des Pharao in der Hand, und ich nahm die Beeren und zerdrückte sie in den Becher des Pharao und gab dem Pharao den Becher in die Hand.',
        12: 'Joseph sprach zu ihm: Dies ist die Bedeutung: die drei Schosse sind drei Tage;',
        13: 'in drei Tagen wird der Pharao dein Haupt erhöhen und dich wieder in dein Amt einsetzen, dass du dem Pharao den Becher reichen darfst wie früher, als du sein Mundschenk warst.',
        14: 'Aber gedenke meiner, wenn es dir wohlgeht, und erweise mir die Liebe, dass du beim Pharao ein gutes Wort für mich einlegst, und hilf mir, dass ich aus diesem Hause komme.',
        15: 'Denn ich bin schmählich aus dem Lande der Hebräer gestohlen worden, und auch hier habe ich es mit nichts verschuldet, dass sie mich in den Kerker geworfen haben.',
        16: 'Als der Oberbäcker sah, dass Joseph eine günstige Deutung gegeben hatte, sprach er zu ihm: Auch mir hat geträumt; mir war, ich trage drei Körbe voll Weissbrot auf dem Kopfe,',
        17: 'und im obersten Korbe war allerlei Speise, Backwerk für den Pharao; aber die Vögel frassen es aus dem Korb auf meinem Kopfe.',
        18: 'Joseph antwortete und sprach: Dies ist die Bedeutung: die drei Körbe sind drei Tage;',
        19: 'in drei Tagen wird der Pharao dein Haupt erhöhen und dich an den Pfahl hängen lassen, und die Vögel werden das Fleisch von dir wegfressen.',
        20: 'Und es geschah am dritten Tage, am Geburtstag des Pharao, da gab er allen seinen Dienern ein Mahl, und er erhöhte das Haupt des Obermundschenken und des Oberbäckers inmitten seiner Diener:',
        21: 'den Obermundschenken setzte er wieder in sein Amt ein, dass er dem Pharao den Becher reichen durfte,',
        22: 'den Oberbäcker aber liess er hängen; wie Joseph es ihnen gedeutet hatte.',
        23: 'Aber der Obermundschenk gedachte Josephs nicht, sondern vergass ihn.',
    },
    41: {
        1: 'NACH zwei Jahren hatte der Pharao einen Traum: er stand am Nil',
        2: 'und sah sieben schöne, fette Kühe aus dem Nil emporsteigen; die weideten im Grase.',
        3: 'Nach ihnen sah er aus dem Nil sieben andre Kühe steigen, hässlich und mager; die traten neben die Kühe am Ufer des Nil.',
        4: 'Und die hässlichen, magern Kühe frassen die sieben schönen, fetten Kühe. Da erwachte der Pharao.',
        5: 'Dann schlief er wieder ein und träumte abermals: sieben Ähren wuchsen auf einem Halme, dick und schön;',
        6: 'nach ihnen sah er sieben dünne Ähren sprossen, die der Ostwind versengt hatte.',
        7: 'Und die dünnen Ähren verschlangen die sieben dicken, vollen Ähren. Da erwachte der Pharao, und siehe, es war ein Traum.',
        8: 'Am Morgen aber wurde sein Geist beunruhigt. Darum sandte er hin und liess alle Wahrsager und alle Weisen von Ägypten rufen und erzählte ihnen seinen Traum; aber es war keiner, der ihn dem Pharao auslegen konnte.',
        9: 'Da sprach der Obermundschenk zum Pharao: Ich muss heute an meine Verfehlung erinnern.',
        10: 'Als der Pharao über seine Knechte zornig ward und sie in das Haus des Obersten der Leibwache in Gewahrsam gab, mich und den Oberbäcker,',
        11: 'da hatten wir in derselben Nacht einen Traum, ich und er; jeder hatte einen Traum von besonderer Bedeutung.',
        12: 'Nun war dort ein hebräischer Jüngling bei uns, ein Sklave des Obersten der Leibwache; dem erzählten wir es, und er legte uns unsre Träume aus, einem jeden legte er seinen Traum besonders aus.',
        13: 'Und wie er es uns ausgelegt, so ist es gekommen: mich hat man wieder in mein Amt eingesetzt, und ihn hat man gehängt.',
        14: 'Da sandte der Pharao hin und liess Joseph rufen, und man holte ihn eilends aus dem Kerker. Er liess sich scheren und wechselte die Kleider, und dann erschien er vor dem Pharao.',
        15: 'Da sprach der Pharao zu Joseph: Ich habe einen Traum gehabt, und niemand kann ihn auslegen; ich habe aber von dir sagen hören, wenn du einen Traum nur hörest, so könnest du ihn auslegen.',
        16: 'Joseph antwortete dem Pharao und sprach: Bei mir steht das nicht; Gott wird dem Pharao Heil verkünden. (a) 1Mo 40:8; Da 2:28',
        17: 'Nun sprach der Pharao zu Joseph: Mir träumte, ich stehe am Ufer des Nil.',
        18: 'Da stiegen aus dem Nil sieben fette, schöne Kühe und weideten im Grase.',
        19: 'Nach ihnen stiegen sieben andre Kühe herauf, dürr und überaus hässlich und mager; ich habe in ganz Ägypten nie so hässliche gesehen.',
        20: 'Und nun frassen die magern, hässlichen Kühe die sieben ersten, fetten Kühe auf;',
        21: 'und wie sie die hineingefressen, merkte man ihnen gar nicht an, dass sie sie verschlungen hatten; sie waren noch so hässlich wie zuvor. Da erwachte ich.',
        22: 'Dann hatte ich (nochmals) einen Traum: sieben Ähren wuchsen auf einem Halme, voll und schön;',
        23: 'nach ihnen sprossten sieben harte, dünne Ähren, vom Ostwind versengt,',
        24: 'und die dünnen Ähren verschlangen die sieben schönen Ähren. Das habe ich den Wahrsagern erzählt, aber keiner kann es mir erklären.',
        25: 'Da sprach Joseph zum Pharao: Beide Träume des Pharao bedeuten dasselbe. Gott hat dem Pharao verkündet, was er tun will.',
        26: 'Die sieben schönen Kühe sind sieben Jahre, und die sieben schönen Ähren sind sieben Jahre; es ist ein und derselbe Traum.',
        27: 'Die sieben magern, hässlichen Kühe, die nach ihnen heraufstiegen, sind sieben Jahre; und die sieben leeren, vom Ostwind versengten Ähren werden sieben Hungerjahre sein.',
        28: 'Das meinte ich, als ich zum Pharao sagte: "Gott hat dem Pharao gezeigt, was er tun will."',
        29: 'Siehe, es werden sieben Jahre kommen mit grosser Fülle in ganz Ägypten.',
        30: 'Und nach ihnen werden sieben Hungerjahre kommen; da wird all die Fülle in Ägypten vergessen sein: der Hunger wird das Land verzehren,',
        31: 'dass man nichts mehr spüren wird von der Fülle im Lande ob der Hungersnot, die hernach kommt; denn sie wird sehr schwer sein.',
        32: 'Dass aber dem Pharao zweimal geträumt hat, das bedeutet, dass die Sache bei Gott fest beschlossen ist und dass Gott es alsbald tun wird.',
        33: 'Nun sehe sich der Pharao nach einem verständigen und weisen Manne um, den er über das Land Ägypten setze;',
        34: 'und der Pharao greife ein und bestelle Amtleute über das Land, um in den sieben Jahren der Fülle den Fünften zu erheben vom Lande Ägypten.',
        35: 'Sie sollen alles Getreide dieser guten Jahre, die nun kommen werden, sammeln und das Korn aufspeichern zur Verfügung des Pharao; sie sollen das Getreide in die Städte schaffen und es dort verwahren.',
        36: 'So wird das Getreide dem Land als Vorrat dienen in den sieben Hungerjahren, die über das Land Ägypten kommen werden, dass nicht das Land vor Hunger verderbe.',
        37: 'Diese Rede gefiel dem Pharao und allen seinen Dienern wohl.',
        38: 'Und der Pharao sprach zu seinen Dienern: Könnten wir wohl einen Mann finden, in dem der Geist Gottes wäre wie in diesem? (a) Da 5:11',
        39: 'Und zu Joseph sprach der Pharao: Nachdem dir Gott das alles kundgetan hat, ist niemand so verständig und weise wie du.',
        40: 'Du sollst über mein Haus gesetzt sein, und deinem Worte soll mein ganzes Volk gehorchen; nur um den Thron will ich höher sein als du.',
        41: 'Dann sprach der Pharao zu Joseph: Siehe, ich setze dich hiemit über das ganze Land Ägypten.',
        42: 'Und der Pharao zog seinen Siegelring vom Finger und steckte ihn Joseph an die Hand, kleidete ihn in Gewänder von Byssus und hängte ihm die goldene Kette um den Hals.',
        43: 'Dann liess er ihn auf seinem zweiten Wagen fahren, und man rief vor ihm her: Abrek! So setzte er ihn über das ganze Land Ägypten. (1) d.h. vlt: Auf die Kniee!',
        44: 'Und der Pharao sprach zu Joseph: Ich bin der Pharao, und ohne deinen Willen soll niemand im ganzen Lande Ägypten die Hand oder den Fuss regen.',
        45: 'Und der Pharao nannte Joseph hinfort Zaphnath-Paneah und gab ihm Asnath, die Tochter Potipheras, des Priesters von On, zum Weibe. So gebot Joseph über das Land Ägypten.',
        46: 'Joseph war dreissig Jahre alt, als er vor den Pharao, den König von Ägypten, trat. Und Joseph zog vom Pharao hinweg und fuhr durch das ganze Land Ägypten.',
        47: 'Das Land aber trug in den sieben Jahren der Fülle Korn im Überfluss.',
        48: 'Da sammelte er alles Getreide der sieben Jahre, in denen Überfluss herrschte im Lande Ägypten, und schaffte das Getreide in die Städte; in eine jede Stadt tat er das Getreide von den Feldern rings um sie her.',
        49: 'So speicherte Joseph das Korn auf, über die Massen viel, wie Sand am Meer, sodass er davon abstand, es zu messen; denn es war unermesslich viel.',
        50: 'Und Joseph wurden zwei Söhne geboren, ehe das Hungerjahr kam; die gebar ihm Asnath, die Tochter Potipheras, des Priesters von On.',
        51: 'Und Joseph nannte den Erstgebornen Manasse; denn (sprach er) Gott hat mich all meine Mühsal und meines Vaters ganzes Haus vergessen lassen. (1) vgl. Anm. zu 1Mo 29:32.',
        52: 'Den zweiten nannte er Ephraim; denn (sprach er) Gott hat mich fruchtbar gemacht im Lande meines Elends. (1) vgl. Anm. zu 1Mo 29:32.',
        53: 'Als die sieben Jahre der Fülle im Lande Ägypten um waren,',
        54: 'begannen die sieben Hungerjahre, wie Joseph gesagt hatte, und es kam eine Hungersnot über alle Länder; im ganzen Lande Ägypten jedoch war Brot.',
        55: 'Als aber ganz Ägypten Hunger litt, schrie das Volk zum Pharao um Brot. Da sprach der Pharao zu allen Ägyptern: Geht zu Joseph; was der euch sagt, das tut.',
        56: 'Die Hungersnot aber herrschte auf der ganzen Erde. Nun öffnete Joseph alle Kornspeicher und verkaufte den Ägyptern Getreide. Und die Hungersnot wurde drückend im Lande Ägypten.',
        57: 'Und alle Welt kam zu Joseph nach Ägypten, um Korn zu kaufen; denn die Hungersnot war drückend in aller Welt.',
    },
    42: {
        1: 'ALS aber Jakob sah, dass in Ägypten Korn feil war, sprach er zu seinen Söhnen: Was schaut ihr einander an?',
        2: 'Ich höre doch, sprach er, dass in Ägypten Korn feil ist. Zieht hinab und kauft uns dort Getreide, dass wir zu leben haben und nicht sterben.',
        3: 'Da zogen die Brüder Josephs, ihrer zehn Mann, hinab, um in Ägypten Korn zu kaufen.',
        4: 'Aber Benjamin, den Bruder Josephs, liess Jakob nicht mit seinen Brüdern ziehen; denn er dachte, es könnte ihm ein Unfall zustossen.',
        5: 'So kamen unter den Leuten, die hinzogen, auch die Söhne Israels, um Korn zu kaufen; denn es herrschte Hungersnot im Lande Kanaan.',
        6: 'Nun war Joseph der Regent im Lande; er war es, der allem Volk im Lande Korn verkaufte. Als aber die Brüder Josephs zu ihm kamen, warfen sie sich vor ihm zur Erde nieder.',
        7: 'Sobald Joseph seine Brüder sah, erkannte er sie; aber er stellte sich fremd gegen sie und redete hart mit ihnen und fragte sie: Wo kommt ihr her? Sie sprachen: Aus dem Lande Kanaan, um Speise zu kaufen.',
        8: 'Während aber Joseph seine Brüder erkannte, erkannten sie ihn nicht.',
        9: 'Da gedachte Joseph der Träume, die er von ihnen geträumt hatte. Und er sprach zu ihnen: Ihr seid Kundschafter! Die Blösse des Landes zu erspähen, seid ihr gekommen. (a) 1Mo 37:5-11',
        10: 'Sie erwiderten ihm: Nicht doch, Herr! Deine Knechte sind gekommen, Speise zu kaufen.',
        11: 'Wir sind alle eines Mannes Söhne; wir sind ehrliche Leute, deine Knechte sind keine Kundschafter.',
        12: 'Aber er sprach zu ihnen: Nichts da! ihr seid gekommen, die Blösse des Landes zu erspähen.',
        13: 'Sie antworteten: Wir, deine Knechte, waren unser zwölf. Wir sind Brüder, Söhne eines Mannes im Lande Kanaan. Der jüngste ist jetzt noch bei unserm Vater, und einer ist nicht mehr da.',
        14: 'Joseph aber sprach zu ihnen: Es ist so, wie ich euch gesagt habe: Kundschafter seid ihr!',
        15: 'Daran will ich euch erproben: So wahr der Pharao lebt, ihr sollt nicht von hinnen ziehen, es komme denn euer jüngster Bruder her.',
        16: 'Sendet einen von euch hin, dass er euren Bruder hole; ihr aber bleibt gefangen. So will ich eure Rede prüfen, ob ihr mit der Wahrheit umgeht; wo nicht, so seid ihr Kundschafter, so wahr der Pharao lebt.',
        17: 'Und er tat sie alle zusammen in Gewahrsam, drei Tage lang.',
        18: 'Am dritten Tage aber sprach Joseph zu ihnen: Wollt ihr am Leben bleiben, so tut dies - denn ich bin gottesfürchtig -:',
        19: 'seid ihr ehrliche Leute, so lasst einen von euch Brüdern hier im Gefängnis gebunden liegen, ihr aber ziehet hin und nehmt genug Getreide heim, den Hunger eurer Familien zu stillen.',
        20: 'Dann bringt euern jüngsten Bruder zu mir, dass eure Worte sich als wahr erweisen und ihr nicht sterben müsset.',
        21: 'Da sprachen sie untereinander: Wahrlich, das haben wir an unserm Bruder verschuldet; denn wir sahen die Not seiner Seele, als er uns anflehte, aber wir hörten nicht auf ihn. Darum kommt nun diese Not über uns.',
        22: 'Ruben antwortete ihnen: Habe ich euch nicht gesagt: "Versündigt euch nicht an dem Knaben!" Doch ihr wolltet nicht hören; und nun, seht ihr, wird sein Blut gefordert. (a) 1Mo 37:21 22',
        23: 'Sie wussten aber nicht, dass Joseph sie verstand; denn er redete durch einen Dolmetscher mit ihnen.',
        24: 'Nun ging er von ihnen hinweg und weinte. Dann kehrte er zu ihnen zurück und redete mit ihnen; und er nahm den Simeon von ihnen weg und liess ihn vor ihren Augen binden.',
        25: 'Darnach befahl er, dass man ihre Säcke mit Korn fülle und einem jeden das Geld wieder in seinen Sack lege und dass man ihnen Zehrung auf den Weg mitgebe. Das tat man ihnen.',
        26: 'Sie aber luden ihr Korn auf ihre Esel und zogen von dannen.',
        27: 'Als nun einer in der Herberge seinen Sack auftat, um seinem Esel Futter zu geben, sah er sein Geld oben im Sacke liegen.',
        28: 'Da sprach er zu seinen Brüdern: Mein Geld ist wieder da; hier in meinem Sacke ist es. Da entfiel ihnen der Mut, und sie sahen einander erschrocken an und sprachen: Was hat uns Gott da angetan!',
        29: 'Als sie nun heim zu ihrem Vater Jakob ins Land Kanaan kamen, erzählten sie ihm alles, was ihnen begegnet war, und sprachen:',
        30: 'Der Mann, der Herr im Lande ist, hat mit uns hart geredet und uns ins Gefängnis gelegt, als wären wir Kundschafter.',
        31: 'Da sprachen wir zu ihm: "Wir sind ehrliche Leute, wir sind keine Kundschafter.',
        32: 'Wir sind unser zwölf Brüder, Söhne unsres Vaters; einer ist nicht mehr da, und der jüngste ist jetzt noch bei unserm Vater im Lande Kanaan."',
        33: 'Nun sprach der Mann, der Herr des Landes, zu uns: "Daran will ich erkennen, dass ihr ehrliche Leute seid: lasst einen von euch Brüdern bei mir und nehmt genug Getreide mit, den Hunger eurer Familien zu stillen.',
        34: 'Bringt mir aber euren jüngsten Bruder her, damit ich erkenne, dass ihr keine Kundschafter, sondern ehrliche Leute seid; dann will ich euch euren Bruder wieder geben, und ihr mögt frei im Lande umherziehen."',
        35: 'Und als sie die Säcke leerten, siehe, da fand ein jeder den Beutel mit seinem Geld in seinem Sacke. Als sie aber, sie und ihr Vater, die Beutel mit dem Gelde sahen, fürchteten sie sich.',
        36: 'Da sprach ihr Vater Jakob zu ihnen: Mich beraubt ihr der Kinder. Joseph ist nicht mehr, Simeon ist nicht mehr, und Benjamin wollt ihr auch wegnehmen; über mich kommt dieses alles.',
        37: 'Da erwiderte Ruben seinem Vater: Meine beiden Söhne magst du töten, wenn ich ihn dir nicht wieder bringe. Überlass ihn mir; ich bringe ihn dir wieder.',
        38: 'Aber er sprach: Mein Sohn soll nicht mit euch hinabziehen; denn sein Bruder ist tot, und er ist allein noch übrig. Wenn ihm ein Unfall zustiesse auf dem Wege, den ihr zieht, so würdet ihr meine grauen Haare mit Kummer ins Totenreich hinunterbringen.',
    },
    43: {
        1: 'DIE Hungersnot aber lastete schwer auf dem Lande.',
        2: 'Als sie nun das Korn, das sie aus Ägypten gebracht, aufgegessen hatten, sprach ihr Vater zu ihnen: Zieht wieder hin und kauft uns ein wenig Speise.',
        3: 'Da erwiderte ihm Juda: Der Mann hat uns nachdrücklich eingeschärft: "Ihr dürft mir nicht mehr unter die Augen treten, wenn euer jüngster Bruder nicht bei euch ist." (a) 1Mo 42:20',
        4: 'Willst du also unsern Bruder mit uns gehen lassen, so wollen wir hinabziehen und dir zu essen kaufen.',
        5: 'Willst du ihn aber nicht mitgehen lassen, so ziehen wir nicht hinab; denn der Mann hat zu uns gesagt: "Ihr dürft mir nicht mehr unter die Augen treten, wenn euer Bruder nicht bei euch ist."',
        6: 'Israel sprach: Warum habt ihr mir das zuleide getan und dem Mann gesagt, dass ihr noch einen Bruder habt?',
        7: 'Sie antworteten: Der Mann hat so genau nach uns und unsrer Verwandtschaft geforscht und uns gefragt: "Lebt euer Vater noch? Habt ihr noch einen Bruder?" Da sagten wir es ihm, wie die Dinge stehen. Konnten wir den wissen, dass er sagen würde: "Bringt euren Bruder her!"',
        8: 'Dann sprach Juda zu seinem Vater Israel: Gib mir den Knaben mit, so wollen wir uns aufmachen und hinziehen, damit wir zu leben haben und nicht sterben, wir und du und unsre Kindlein.',
        9: 'Ich will Bürge für ihn sein, von meiner Hand sollst du ihn fordern; wenn ich ihn dir nicht wieder bringe und vor Augen stelle, so will ich vor dir mein Leben lang die Schuld tragen.',
        10: 'Fürwahr, wenn wir nicht gezögert hätten, so wären wir jetzt schon zweimal wieder zurück.',
        11: 'Da sprach ihr Vater Israel zu ihnen: Muss es denn sein, so tut dies: nehmt von den besten Früchten des Landes in eure Säcke und bringt es dem Manne als Geschenk, ein wenig Balsam und ein wenig Honig, Gummi und Harz und Pistaziennüsse und Mandeln.',
        12: 'Und nehmt den doppelten Betrag an Geld mit euch: das Geld, das wieder oben in eure Säcke gelegt worden ist, müsst ihr auch mit zurücknehmen; vielleicht ist da ein Irrtum geschehen.',
        13: 'Dazu nehmt euren Bruder, macht euch auf und geht wieder zu dem Manne.',
        14: 'Der allmächtige Gott lasse euch Barmherzigkeit finden vor dem Manne, dass er euren andern Bruder mit euch ziehen lasse und den Benjamin! Ich aber, wie ich nun einmal verwaist bin, so bin ich, ach, verwaist!',
        15: 'Da nahmen die Männer das Geschenk, auch den doppelten Betrag an Geld nahmen sie mit sich, dazu Benjamin, machten sich auf, zogen hinab nach Ägypten und traten vor Joseph.',
        16: 'Als Joseph den Benjamin bei ihnen sah, sprach er zu seinem Hausverwalter: Führe diese Männer ins Haus hinein, schlachte und richte zu, denn sie sollen mit mir zu Mittag essen.',
        17: 'Der Mann tat, wie Joseph befohlen hatte, und führte die Männer in Josephs Haus.',
        18: 'Sie aber fürchteten sich, weil sie in Josephs Haus geführt wurden, und sprachen: Wir werden hier hereingeführt um des Geldes willen, welches das erste Mal wieder in unsre Säcke gekommen ist: man will auf uns eindringen und über uns herfallen und uns zu Sklaven machen und uns die Esel wegnehmen.',
        19: 'Darum traten sie zu dem Manne, der über Josephs Haus gesetzt war, und redeten mit ihm an der Pforte',
        20: 'und sprachen: Lieber Herr, wir sind schon einmal herabgekommen, um Speise zu kaufen.',
        21: 'Als wir nun in die Herberge kamen und unsre Säcke aufmachten, siehe, da lag eines jeden Geld oben in seinem Sacke, unser Geld nach seinem vollen Gewichte; das haben wir nun wieder mitgebracht.',
        22: 'Wir haben aber auch noch andres Geld bei uns, um Speise zu kaufen. Wir wissen nicht, wer unser Geld in unsre Säcke gelegt hat.',
        23: 'Er aber sprach: Seid getrost, fürchtet euch nicht! Euer Gott und eures Vaters Gott hat euch einen Schatz in die Säcke getan; euer Geld ist mir zugekommen. Und er brachte den Simeon zu ihnen heraus. (a) 1Mo 42:24',
        24: 'Dann führte er die Männer in Josephs Haus, reichte ihnen Wasser, ihre Füsse zu waschen, und gab ihren Eseln Futter.',
        25: 'Sie aber machten das Geschenk bereit, bis Joseph am Mittag käme; denn sie hatten gehört, dass sie dort essen sollten.',
        26: 'Als Joseph nun nach Hause kam, brachten sie ihm das Geschenk, das sie bei sich hatten, hinein und warfen sich vor ihm zur Erde nieder.',
        27: 'Er aber begrüsste sie und sprach: Geht es eurem alten Vater wohl, von dem ihr erzählt habt? Ist er noch am Leben?',
        28: 'Sie antworteten: Es geht deinem Knechte, unserm Vater, wohl; er ist noch am Leben. Und sie verneigten sich und warfen sich nieder. (a) 1Mo 37:7',
        29: 'Und als er seine Augen erhob und seinen Bruder Benjamin, den Sohn seiner Mutter, sah, sprach er: Ist das euer jüngster Bruder, von dem ihr mir erzählt habt? Darnach sprach er: Gott sei dir gnädig, mein Sohn!',
        30: 'Dann aber ging Joseph schnell in seine Kammer - denn sein Herz war tief bewegt beim Anblick seines Bruders, und das Weinen kam ihn an -, und er weinte daselbst.',
        31: 'Und als er sein Angesicht gewaschen hatte, kam er wieder heraus und nahm sich zusammen und sprach: Tragt das Essen auf!',
        32: 'Und man trug ihm besonders auf und ihnen besonders, und ebenso den Ägyptern, die mit ihm assen. Denn die Ägypter dürfen nicht mit den Hebräern essen; das ist den Ägyptern ein Greuel.',
        33: 'Man setzte sie aber ihm gegenüber, vom Erstgebornen bis zum Jüngsten, genau nach dem Alter; darob sahen sich die Männer verwundert an.',
        34: 'Und er liess ihnen Gerichte auftragen von seinem Tische; dem Benjamin aber wurde fünfmal mehr aufgetragen als den andern. Und sie tranken mit ihm und wurden guter Dinge.',
    },
    44: {
        1: 'DANN gebot Joseph seinem Hausverwalter: Fülle den Männern die Säcke mit Getreide, so viel sie mitführen können, und lege einem jeden sein Geld oben in den Sack.',
        2: 'Meinen silbernen Becher aber lege oben in des Jüngsten Sack samt dem Geld für das Korn. Und er tat, wie ihm Joseph gesagt hatte.',
        3: 'Am Morgen, als es Tag ward, liess man die Männer mit den Eseln ziehen.',
        4: 'Kaum aber waren sie zur Stadt hinaus und noch nicht weit gekommen, da sprach Joseph zu seinem Hausverwalter: Auf, jage den Männern nach, und wenn du sie eingeholt hast, so sprich zu ihnen: Warum habt ihr Gutes mit Bösem vergolten und meinen silbernen Becher gestohlen?',
        5: 'Ist das nicht der, aus dem mein Herr trinkt und aus dem er weissagt? Daran habt ihr übelgetan.',
        6: 'Als er sie nun eingeholt hatte, redete er solche Worte mit ihnen.',
        7: 'Sie antworteten: Warum redet mein Herr solche Worte? Ferne sei es von deinen Knechten, solches zu tun!',
        8: 'Das Geld, das wir oben in unsern Säcken gefunden, haben wir dir doch aus dem Lande Kanaan zurückgebracht; wie sollten wir da aus dem Hause deines Herrn Silber oder Gold stehlen?',
        9: 'Der unter deinen Knechten, bei dem es gefunden wird, der sei des Todes; wir aber wollen überdies meines Herrn Knechte sein.',
        10: 'Er sprach zu ihnen: Ja, es sei, wie ihr gesagt habt: der, bei dem es gefunden wird, der soll mein Knecht sein; ihr aber geht frei aus.',
        11: 'Und eilends liess ein jeder seinen Sack auf die Erde herab und machte ihn auf.',
        12: 'Er aber suchte nach: beim Ältesten fing er an, und beim Jüngsten hörte er auf; und der Becher fand sich in Benjamins Sack.',
        13: 'Da zerrissen sie ihre Kleider, luden die Säcke wieder auf die Esel und kehrten in die Stadt zurück.',
        14: 'Und Juda trat mit seinen Brüdern in das Haus Josephs, der noch da war, und sie warfen sich vor ihm zur Erde.',
        15: 'Da sprach Joseph zu ihnen: Was ist das für eine Tat, die ihr begangen habt! Wusstet ihr nicht, dass ein Mann wie ich es gewiss erkunden würde?',
        16: 'Juda antwortete: Was sollen wir meinem Herrn sagen? wie sollen wir reden und womit uns rechtfertigen? Gott hat die Schuld deiner Knechte an den Tag gebracht. Siehe, wir sind meines Herrn Knechte, wir sowohl als der, bei dem sich der Becher gefunden hat.',
        17: 'Er aber sprach: Das sei ferne von mir, solches zu tun! Nur der, bei dem sich der Becher gefunden hat, soll mein Knecht sein; ihr aber mögt in Frieden hinauf zu eurem Vater ziehen!',
        18: 'Da trat Juda zu ihm heran und sprach: Mit Verlaub, Herr, lass doch deinen Knecht ein Wort reden vor deinen Ohren, und dein Zorn entbrenne nicht über deinen Knecht; denn du bist wie der Pharao.',
        19: 'Mein Herr hat seine Knechte gefragt: Habt ihr noch einen Vater oder einen Bruder?',
        20: 'Da antworteten wir meinem Herrn: Wir haben noch unsern alten Vater und einen Knaben, der ihm im Alter geboren wurde; sein Bruder ist tot, und so ist er allein von seiner Mutter übriggeblieben, und der Vater hat ihn lieb. (a) 1Mo 42:13',
        21: 'Da sprachst du zu deinen Knechten: Bringt ihn herab zu mir, dass ich ihn zu Gesicht bekomme.',
        22: 'Wir aber antworteten meinem Herrn: Der Knabe kann seinen Vater nicht verlassen; wenn er seinen Vater verliesse, so würde dieser sterben.',
        23: 'Da sprachst du zu deinen Knechten: Wenn euer jüngster Bruder nicht mit euch herabkommt, so dürft ihr mir nicht mehr unter die Augen treten.',
        24: 'Als wir nun zu deinem Knechte, meinem Vater, hinaufkamen, taten wir ihm die Worte meines Herrn kund.',
        25: 'Darnach sprach unser Vater: Zieht wieder hin und kauft uns ein wenig Speise.',
        26: 'Wir aber sprachen: Wir können nicht hinabziehen; nur wenn unser jüngster Bruder bei uns ist, ziehen wir hinab. Denn wir dürfen dem Manne nicht unter die Augen treten, wenn unser jüngster Bruder nicht bei uns ist. (a) 1Mo 43:3',
        27: 'Da sprach dein Knecht, mein Vater, zu uns: Ihr wisst ja selbst, dass mir mein Weib nur zwei Söhne geboren hat.',
        28: 'Der eine ist von mir gegangen, sodass ich mir sagen musste: "Er ist gewiss zerrissen worden", und ich habe ihn bis heute nicht wiedergesehen.',
        29: 'Nehmt ihr nun diesen auch von mir, und es stösst ihm ein Unfall zu, so bringt ihr meine grauen Haare mit Jammer ins Totenreich hinunter. (a) 1Mo 42:38',
        30: 'Und nun, wenn ich zu deinem Knechte, meinem Vater, heimkäme und der Knabe wäre nicht bei uns, an dem er doch mit ganzer Seele hängt,',
        31: 'so stirbt er, wenn er sieht, dass der Knabe nicht mehr bei uns ist. So würden deine Knechte die grauen Haare deines Knechtes, unsres Vaters, mit Kummer ins Totenreich hinunterbringen.',
        32: 'Denn dein Knecht ist für den Knaben Bürge geworden bei meinem Vater und hat gesprochen: "Wenn ich ihn dir nicht wiederbringe, so will ich mein Leben lang die Schuld tragen vor meinem Vater." (a) 1Mo 43 9',
        33: 'Darum erlaube jetzt, dass dein Knecht an des Knaben Statt hier bleibe als Sklave meines Herrn; der Knabe aber möge mit seinen Brüdern hinaufziehen.',
        34: 'Denn wie könnte ich zu meinem Vater hinaufziehen, wenn der Knabe nicht bei mir wäre? Ich möchte den Jammer nicht mitansehen, der über meinen Vater kommen würde.',
    },
    45: {
        1: 'DA konnte sich Joseph nicht mehr länger halten vor allen, die um ihn her standen, und er rief: Lasst jedermann von mir hinausgehen! So war niemand sonst bei Joseph, als er sich seinen Brüdern zu erkennen gab.',
        2: 'Und er weinte laut, dass es die Ägypter hörten und man im Haus des Pharao davon vernahm.',
        3: 'Und Joseph sprach zu seinen Brüdern: Ich bin Joseph; lebt mein Vater noch? Aber seine Brüder konnten ihm nicht antworten, so erschraken sie vor ihm.',
        4: 'Dann sprach Joseph zu seinen Brüdern: Tretet doch zu mir heran! Und sie traten herzu. Da sprach er: Ich bin Joseph, euer Bruder, den ihr nach Ägypten verkauft habt. (a) 1Mo 37:28',
        5: 'Doch nun grämt euch nicht und lasst es euch nicht leid sein, dass ihr mich hierher verkauft habt; denn um (viele) am Leben zu erhalten, hat mich Gott vor euch her gesandt. (a) 1Mo 50:20',
        6: 'Zwei Jahre ist ja nun schon die Hungersnot im Lande, und noch fünf Jahre lang wird kein Pflügen und Ernten sein.',
        7: 'Darum hat mich Gott vor euch her gesandt, um euch Nachkommenschaft zu sichern und von euch viele zu retten und am Leben zu erhalten.',
        8: 'So habt nicht ihr mich hierher gesandt, sondern Gott; er hat mich dem Pharao zum Vater gesetzt und zum Herrn über sein ganzes Haus und zum Herrscher über das ganze Land Ägypten. (a) 1Mo 41:40',
        9: 'Nun eilt und zieht hinauf zu meinem Vater und sagt ihm: Das lässt dir dein Sohn Joseph sagen: "Gott hat mich zum Herrn über ganz Ägypten gemacht. Komm herab zu mir und säume nicht!',
        10: 'Du sollst im Lande Gosen wohnen und nahe bei mir sein, du und deine Kinder und deine Kindeskinder samt deinen Schafen und Rindern und allem, was dein ist.',
        11: 'Ich will daselbst für dich sorgen - denn noch fünf Jahre dauert die Hungersnot -, dass du nicht in Armut gerätst, du und dein Haus samt allem, was dein ist."',
        12: 'Ihr seht es ja mit eigenen Augen, und auch mein Bruder Benjamin sieht, dass ich selbst es bin, der mit euch redet.',
        13: 'Erzählt denn meinem Vater von all meinen Ehren in Ägypten und von alledem, was ihr gesehen habt. Dann kommt eilends mit meinem Vater hierher.',
        14: 'Und nun fiel er seinem Bruder Benjamin um den Hals und weinte; und auch Benjamin weinte an seinem Halse.',
        15: 'Und er küsste alle seine Brüder und weinte, indem er sie umarmte. Darnach redeten seine Brüder mit ihm.',
        16: 'Die Kunde davon kam auch in das Haus des Pharao; es hiess: Josephs Brüder sind gekommen. Das gefiel dem Pharao und seinen Dienern wohl.',
        17: 'Und der Pharao gab Joseph Weisung, zu seinen Brüdern zu sagen: Tut also: beladet eure Tiere und zieht heim ins Land Kanaan.',
        18: 'Dann nehmt euren Vater und eure Familien und kommt zu mir; ich will euch das Beste geben, was das Land Ägypten bietet, dass ihr das Fett des Landes essen sollt.',
        19: 'Auch liess er ihnen sagen: Tut also: nehmt euch aus Ägypten Wagen für eure Kinder und Frauen und bringt euren Vater hierher.',
        20: 'Und lasst euch euren Hausrat nicht reuen; denn das Beste, was das ganze Land Ägypten bietet, soll euer sein.',
        21: 'Die Söhne Israels taten so, und Joseph gab ihnen Wagen nach dem Befehl des Pharao; auch gab er ihnen Zehrung auf den Weg,',
        22: 'und einem jeden schenkte er ein Feierkleid, dem Benjamin aber schenkte er dreihundert Lot Silber und fünf Feierkleider.',
        23: 'Ebenso sandte er seinem Vater zehn Esel, mit Gut aus Ägypten beladen, und zehn Eselinnen mit Korn, Brot und (andrer) Speise für seinen Vater auf den Weg.',
        24: 'Damit entliess er seine Brüder, und sie zogen fort; und er sprach zu ihnen: Ereifert euch nicht unterwegs!',
        25: 'So zogen sie aus Ägypten hinauf und kamen zu ihrem Vater Jakob ins Land Kanaan.',
        26: 'Und sie erstatteten ihm Bericht und sprachen: Joseph ist noch am Leben; ja, er ist Herr über das ganze Land Ägypten. Aber sein Herz blieb kalt; denn er glaubte ihnen nicht.',
        27: 'Da erzählten sie ihm alles, was Joseph zu ihnen geredet hatte. Und als er die Wagen sah, die Joseph gesandt hatte, um ihn hinzuführen, da lebte ihr Vater Jakob wieder auf.',
        28: 'Und Israel sprach: Genug! mein Sohn Joseph lebt noch! Ich will hin und ihn sehen, ehe ich sterbe.',
    },
    46: {
        1: 'UND Israel brach auf mit allem, was er hatte, und als er nach Beerseba kam, brachte er dem Gott seines Vaters Isaak Opfer dar. (a) 1Mo 26:23-25',
        2: 'Da redete Gott in einer nächtlichen Erscheinung mit Israel und sprach: Jakob! Jakob! Er antwortete: Hier bin ich.',
        3: 'Und er sprach: Ich bin Gott, der Gott deines Vaters. Fürchte dich nicht, nach Ägypten hinabzuziehen; denn ich will dich dort zu einem grossen Volke machen.',
        4: 'Ich selber ziehe mit dir hinab nach Ägypten, und ich werde dich auch wieder heraufführen, und Joseph soll dir die Augen zudrücken.',
        5: 'Da machte sich Jakob auf von Beerseba; und die Söhne Israels hoben ihren Vater Jakob, ihre Kinder und Frauen auf die Wagen, die der Pharao gesandt hatte, um ihn hinzuführen. (a) 1Mo 45:19',
        6: 'Und sie nahmen ihre Herden und ihre Habe, die sie im Lande Kanaan erworben hatten, und kamen so nach Ägypten, Jakob und sein ganzes Geschlecht mit ihm:',
        7: 'seine Söhne und seine Enkel, seine Töchter und seine Enkelinnen und sein ganzes Geschlecht brachte er mit sich nach Ägypten.',
        8: 'Dies sind die Namen der Söhne Israels, die nach Ägypten kamen: Jakob und seine Söhne. Ruben, Jakobs Erstgeborner.',
        9: 'Die Söhne Rubens: Henoch, Pallu, Hezron und Charmi.',
        10: 'Die Söhne Simeons: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn der Kanaaniterin.',
        11: 'Die Söhne Levis: Gerson, Kahath und Merari.',
        12: 'Die Söhne Judas: Er, Onan, Sela, Perez und Serah. Aber Er und Onan starben im Lande Kanaan. Die Söhne des Perez waren Hezron und Hamul.',
        13: 'Die Söhne Issaschars: Thola, Puwa, Jasub und Simron.',
        14: 'Die Söhne Sebulons: Sered, Elon und Jahleel.',
        15: 'Das sind die Söhne Leas, die sie dem Jakob in Mesopotamien gebar, samt seiner Tochter Dina. Die machen zusammen, Söhne und Töchter, 33 Seelen aus.',
        16: 'Die Söhne Gads: Zephon, Haggi, Suni, Ezbon, Eri, Arodi und Areli.',
        17: 'Die Söhne Assers: Jimna, Jiswa, Jiswi und Beria, und ihre Schwester Serah. Die Söhne Berias: Heber und Malchiel.',
        18: 'Das sind die Söhne der Silpa, die Laban seiner Tochter Lea gab; diese gebar sie dem Jakob, sechzehn Seelen. (a) 1Mo 29:24',
        19: 'Die Söhne Rahels, des Weibes Jakobs: Joseph und Benjamin.',
        20: 'Dem Joseph wurden im Lande Ägypten Manasse und Ephraim geboren, die ihm Asnath gebar, die Tochter Potipheras, des Priesters von On. (a) 1Mo 41:50',
        21: 'Die Söhne Benjamins: Bela, Becher, Asbel, Gera, Naeman, Ahiram, Supham, Hupham und Ard.',
        22: 'Das sind die Söhne Rahels, die sie dem Jakob gebar, zusammen vierzehn Seelen.',
        23: 'Die Söhne Dans: Husim.',
        24: 'Die Söhne Naphthalis: Jahzeel, Guni, Jezer und Sillem.',
        25: 'Das sind die Söhne der Bilha, die Laban seiner Tochter Rahel gab; diese gebar sie dem Jakob, zusammen sieben Seelen. (a) 1Mo 29:29',
        26: 'Alle Seelen aus dem Geschlechte Jakobs, die nach Ägypten kamen, alle seine Nachkommen, nicht gerechnet die Frauen der Söhne Jakobs, waren zusammen 66 Seelen.',
        27: 'Und die Söhne Josephs, die ihm in Ägypten geboren wurden, waren zwei Seelen. Alle Seelen des Hauses Jakobs, die nach Ägypten kamen, waren siebzig.',
        28: 'Den Juda aber sandte er vor sich her zu Joseph, damit dieser vor seiner Ankunft nach Gosen Weisung gebe. Als sie nun ins Land Gosen kamen,',
        29: 'liess Joseph seinen Wagen anspannen und zog nach Gosen, seinem Vater Israel entgegen; und als er ihn sah, fiel er ihm um den Hals und weinte lange an seinem Halse.',
        30: 'Dann sprach Israel zu Joseph: Jetzt will ich gerne sterben, nachdem ich dein Angesicht geschaut und gesehen habe, dass du noch am Leben bist.',
        31: 'Joseph aber sprach zu seinen Brüdern und zu seines Vaters Hause: Ich will hingehen und es dem Pharao melden und zu ihm sprechen: "Meine Brüder und meines Vaters Haus, die im Lande Kanaan waren, sind zu mir gekommen.',
        32: 'Die Männer sind Schafhirten - denn sie waren Viehzüchter -, und ihre Schafe und Rinder und alles, was sie besitzen, haben sie mitgebracht."',
        33: 'Wenn euch nun der Pharao rufen lässt und fragt: "Was ist euer Gewerbe?"',
        34: 'so sagt: "Deine Knechte sind Viehzüchter gewesen von Jugend an bis jetzt, wir wie unsre Väter", damit ihr im Lande Gosen wohnen dürft. - Alle Schafhirten sind nämlich den Ägyptern ein Greuel.',
    },
    47: {
        1: 'SO ging denn Joseph hinein und meldete es dem Pharao und sprach: Mein Vater und meine Brüder sind mit ihren Schafen und Rindern und ihrer ganzen Habe aus dem Lande Kanaan gekommen, und nun sind sie im Lande Gosen.',
        2: 'Aus der Zahl seiner Brüder aber hatte er fünf mit sich genommen; die stellte er dem Pharao vor.',
        3: 'Da sprach der Pharao zu seinen Brüdern: Was ist euer Gewerbe? Sie antworteten dem Pharao: Deine Knechte sind Schafhirten, wir wie unsre Väter.',
        4: 'Dann sagten sie zum Pharao: Wir sind gekommen, als Fremdlinge im Lande zu wohnen; denn deine Knechte haben keine Weide für ihre Schafe, so schwer ist die Hungersnot im Lande Kanaan. So lass doch nun deine Knechte im Lande Gosen bleiben.',
        5: 'Da sprach der Pharao zu Joseph: Dein Vater und deine Brüder sind also zu dir gekommen.',
        6: 'Das Land Ägypten steht dir offen. Lass deinen Vater und deine Brüder im besten Teil des Landes wohnen; sie mögen im Lande Gosen bleiben. Und wenn du weisst, dass tüchtige Leute unter ihnen sind, so setze sie zu Aufsehern über meine eignen Herden.',
        7: 'Joseph brachte auch seinen Vater Jakob hinein und stellte ihn dem Pharao vor, und Jakob entbot dem Pharao den Segensgruss.',
        8: 'Und der Pharao fragte Jakob: Wie alt bist du?',
        9: 'Jakob antwortete dem Pharao: Die ganze Zeit meiner Pilgerschaft ist 130 Jahre. Kurz und voll Leid war die Zeit meiner Lebensjahre, und sie reicht nicht an die Zeit der Lebensjahre, die meinen Vätern in den Tagen ihrer Pilgerschaft beschieden war.',
        10: 'Dann nahm Jakob mit Segenswunsch Abschied vom Pharao und ging von ihm hinaus.',
        11: 'Joseph aber verschaffte seinem Vater und seinen Brüdern Wohnsitze und gab ihnen eigenen Besitz im Lande Ägypten, im besten Teil des Landes, im Gebiet von Ramses, wie der Pharao geboten hatte.',
        12: 'Und Joseph versorgte seinen Vater und seine Brüder und das ganze Haus seines Vaters mit Speise nach der Zahl der Kinder.',
        13: 'ES war aber im ganzen Lande kein Brot; denn die Hungersnot war sehr schwer, sodass das Land Ägypten und das Land Kanaan vor Hunger verschmachteten.',
        14: 'So brachte Joseph alles Geld zusammen, das sich im Lande Ägypten und im Lande Kanaan fand, für das Korn, das die Leute kauften. Und Joseph lieferte das Geld in das Haus des Pharao ab.',
        15: 'Als nun im Lande Ägypten und im Lande Kanaan das Geld ausgegangen war, kamen alle Ägypter zu Joseph und sprachen: Verschaffe uns Brot! Warum lässest du uns vor deinen Augen sterben? Denn das Geld ist zu Ende.',
        16: 'Joseph sprach: Gebt euer Vieh her, so will ich euch Brot dafür geben, wenn das Geld zu Ende ist.',
        17: 'Da brachten sie dem Joseph ihr Vieh, und er gab ihnen Brot dafür, für die Pferde, die Schafherden, die Rinderherden und die Esel. So versorgte er sie in jenem Jahr mit Brot um den Preis all ihres Viehs.',
        18: 'Als dieses Jahr verflossen war, kamen sie im zweiten Jahre wieder und sprachen zu ihm: Wir können es unserm Herrn nicht verhehlen: das Geld ist zu Ende. Auch die Viehherden gehören unserm Herrn; so bleibt denn zur Verfügung unsers Herrn nichts mehr als unser Leib und unser Feld.',
        19: 'Warum sollen wir vor deinen Augen zugrunde gehen, wir und unser Feld? Kaufe uns und unser Feld um Brot, so wollen wir samt unserm Felde dem Pharao dienstbar werden. Gib uns Saatgut, dass wir am Leben bleiben und nicht sterben und das Feld nicht veröde.',
        20: 'So kaufte Joseph für den Pharao alles Ackerland in Ägypten auf; denn die Ägypter verkauften ein jeder seinen Acker, weil die Hungersnot sie hart drückte, und so ward das Land Eigentum des Pharao.',
        21: 'Das Volk aber machte er ihm dienstbar von einem Ende Ägyptens bis zum andern.',
        22: 'Nur das Ackerland der Priester kaufte er nicht; denn die Priester hatten vom Pharao ein festes Einkommen, und sie nährten sich von diesem Einkommen, das der Pharao ihnen gab; darum brauchten sie ihr Ackerland nicht zu verkaufen.',
        23: 'Und Joseph sprach zum Volke: Damit habe ich euch und euer Ackerland heute für den Pharao gekauft; da habt ihr Saatgut, nun besät das Feld.',
        24: 'Aber vom Ertrage müsst ihr dem Pharao den Fünften geben; die andern vier Teile sollen euer sein, das Feld zu besäen und damit ihr zu essen habt samt euren Hausgenossen und euren Kindern.',
        25: 'Sie sprachen: Du hast uns das Leben erhalten; wenn wir nur Gnade finden vor unserm Herrn, so wollen wir gerne dem Pharao dienstbar sein.',
        26: 'So machte Joseph dies zum Gesetz bis auf den heutigen Tag für das Ackerland der Ägypter, dass sie dem Pharao den Fünften geben müssen. Nur das Ackerland der Priester wurde nicht Eigentum des Pharao.',
        27: 'ALSO blieb Israel im Lande Ägypten, im Lande Gosen; und sie setzten sich darin fest und mehrten sich und wurden sehr zahlreich.',
        28: 'Und Jakob lebte noch siebzehn Jahre im Lande Ägypten, sodass die Zahl der Lebensjahre Jakobs 147 betrug.',
        29: 'Als nun die Zeit kam, dass Israel sterben sollte, liess er seinen Sohn Joseph rufen und sprach zu ihm: Willst du mir einen Gefallen tun, so lege deine Hand unter meine Hüfte und erweise mir die Liebe und Treue, dass du mich nicht in Ägypten begräbst;',
        30: 'sondern wenn ich mich nun zu meinen Vätern lege, so bringe mich aus Ägypten hinweg und begrabe mich in ihrer Grabstätte. Er sprach: Ich will tun, wie du gesagt hast. (a) 1Mo 50:5',
        31: 'Er aber sprach: So schwöre mir! Und er schwur ihm. Da verneigte sich Israel zu Häupten des Bettes.',
    },
    48: {
        1: 'Darnach begab es sich, dass dem Joseph berichtet ward: Siehe, dein Vater ist krank. Da nahm er seine beiden Söhne Manasse und Ephraim mit sich und kam zu Jakob.',
        2: 'Und man meldete Jakob: Siehe, dein Sohn Joseph kommt zu dir. Da raffte sich Israel zusammen und setzte sich im Bette auf.',
        3: 'Und Jakob sprach zu Joseph: Der allmächtige Gott erschien mir zu Lus im Lande Kanaan, segnete mich (a) 1Mo 35:6 11 12',
        4: 'und sprach zu mir: "Siehe, ich will dich fruchtbar machen und dich mehren, will dich zu einer Gemeinde von Völkern machen und deinem Geschlechte dieses Land zum ewigen Besitze geben."',
        5: 'Und nun sollen deine beiden Söhne, die dir in Ägypten geboren wurden, ehe ich zu dir nach Ägypten kam, die meinen sein; wie Ruben und Simeon sollen Manasse und Ephraim mir gelten. (a) 1Mo 41:50-52',
        6: 'Die Kinder aber, die du nach ihnen gezeugt hast, sollen dein sein; nach dem Namen ihrer Brüder sollen sie benannt sein auf ihrem Erbteil.',
        7: 'Als ich aus Mesopotamien kam, starb mir Rahel im Lande Kanaan auf dem Wege, als es nur noch ein Stück weit bis Ephrath war, und ich begrub sie daselbst am Wege nach Ephrath - das ist Bethlehem. (a) 1Mo 35:19',
        8: 'Als nun Israel die Söhne Josephs sah, sprach er: Wer sind diese?',
        9: 'Joseph antwortete seinem Vater: Es sind meine Söhne, die Gott mir hier gegeben hat. Da sprach er: Bringe sie her zu mir, dass ich sie segne.',
        10: 'Israels Augen aber waren vor Alter schwach geworden, sodass er nicht mehr sehen konnte. Und er führte sie nahe zu ihm hin; er aber küsste und umarmte sie.',
        11: 'Da sprach Israel zu Joseph: Ich hätte nicht gedacht, dass ich dein Angesicht je wiedersehen würde; und nun hat Gott mich sogar deine Kinder schauen lassen.',
        12: 'Dann zog sie Joseph von seinen Knieen zurück und verneigte sich mit dem Angesicht zur Erde.',
        13: 'Darnach nahm Joseph die beiden, den Ephraim an seiner rechten Hand zur Linken Israels und den Manasse an seiner linken Hand zur Rechten Israels, und führte sie nahe zu ihm hin.',
        14: 'Aber Israel streckte seine Rechte aus und legte sie auf Ephraims, des Jüngern, Haupt und seine Linke auf das Haupt Manasses, indem er die Arme kreuzte; Manasse war nämlich der Erstgeborne.',
        15: 'Und er segnete Joseph und sprach: Der Gott, vor dem meine Väter Abraham und Isaak gewandelt, / der Gott, der mein Hirte gewesen mein Leben lang, bis auf diesen Tag, /',
        16: 'der Engel, der mich aus aller Not erlöst hat: / er segne diese Knaben, dass in ihnen mein Name fortlebe / und der Name meiner Väter Abraham und Isaak, / dass sie wachsen und zahlreich werden auf der Erde.',
        17: 'Als aber Joseph sah, dass sein Vater die rechte Hand auf Ephraims Haupt legte, missfiel es ihm, und er fasste seines Vaters Hand, um sie vom Haupte Ephraims auf Manasses Haupt zu legen;',
        18: 'und Joseph sprach zu seinem Vater: Nicht also, mein Vater! dieser ist der Erstgeborne, lege deine Rechte auf sein Haupt.',
        19: 'Aber sein Vater weigerte sich und sprach: Ich weiss, mein Sohn, ich weiss wohl. Auch dieser wird zu einem Volke werden, und auch er wird gross sein; aber sein jüngerer Bruder wird grösser sein als er, und sein Geschlecht wird eine Menge von Völkern werden.',
        20: 'So segnete er sie an jenem Tage und sprach: Mit eurem Namen wird man in Israel Segen wünschen und sprechen: Gott mache dich wie Ephraim und wie Manasse! und gab damit Ephraim den Vorrang vor Manasse. (a) 1Mo 12:2 3; 18:18',
        21: 'Dann sprach Israel zu Joseph: Siehe, ich sterbe nun; Gott aber wird mit euch sein und wird euch wieder in das Land eurer Väter bringen.',
        22: 'Und ich gebe dir als Vorzug vor deinen Brüdern einen Bergrücken, den ich den Amoritern abgenommen habe mit meinem Schwert und Bogen. (1) d.i. Sichem.',
    },
    49: {
        1: 'UND Jakob berief seine Söhne und sprach: Versammelt euch, dass ich euch verkünde, was euch am Ende der Tage begegnen wird.',
        2: 'Kommet zusammen, ihr Söhne Jakobs, / und höret auf Israel, euren Vater! /',
        3: 'Ruben, mein Erstgeborner bist du, / meine Kraft, der Erstling meiner Stärke; / überragend an Hoheit, überragend an Macht, /',
        4: 'walltest du über wie Wasser, sollst der Erste nicht sein. / Denn du bestiegst deines Vaters Lager, / entweihtest damals das Bette, das du bestiegen. / (a) 1Mo 35:22',
        5: 'Simeon und Levi sind Brüder, / Werkzeuge des Frevels sind ihre Waffen. /',
        6: 'Ihrem Rat bleibe fern meine Seele, / mit ihrer Versammlung eine sich nicht mein Herz; / denn im Zorne töten sie Männer, / und im Mutwillen verstümmeln sie Stiere. / (a) 1Mo 34:25',
        7: 'Fluch über ihren Zorn, dass er so heftig, / und über ihren Grimm, dass er so grausam ist! / Ich will sie zerteilen in Jakob, / will sie zerstreuen in Israel. /',
        8: 'Juda, dich preisen deine Brüder! / Deine Hand packt die Feinde im Nacken, / vor dir neigen sich die Söhne deines Vaters. /',
        9: 'Ein junger Löwe ist Juda; / vom Raube, mein Sohn, wardst du gross. / Er hat sich gekauert, gelagert wie ein Leu, / wie eine Löwin - wer will ihn aufstören? /',
        10: 'Nie weicht das Szepter von Juda, / noch der Führerstab von seinen Füssen, / bis dass der Herrscher kommt, / dem die Völker gehorchen. /',
        11: 'Er bindet seinen Esel an den Weinstock / und an die Rebe das Füllen seiner Eselin, / er wäscht sein Gewand in Wein / und in Traubenblut seinen Mantel, /',
        12: 'seine Augen funkeln von Wein, / und seine Zähne sind weiss von Milch. /',
        13: 'Sebulon wohnt am Ufer des Meeres; / er liegt am Gestade der Schiffe / und lehnt seinen Rücken an Sidon. /',
        14: 'Issaschar ist ein knochiger Esel, / der zwischen den Viehhürden lagert. /',
        15: 'Und da er sah, dass die Ruhe so schön sei / und das Land so lieblich, / beugte er seinen Rücken zum Tragen / und ward ein fronender Knecht. /',
        16: 'Dan schafft Recht seinem Volke, / wie nur irgendein Stamm in Israel. /',
        17: 'Dan sei eine Schlange am Wege, / eine Otter auf dem Pfade, / die das Ross in die Fersen beisst, / dass sein Reiter rücklings stürzt. /',
        18: 'Deiner Hilfe harre ich, Herr! /',
        19: 'Gad wird von Drängern bedrängt; / er aber drängt ihnen nach. /',
        20: 'Assers Brot ist fett; / ja, Königsleckerbissen spendet er. /',
        21: 'Naphthali ist eine flüchtige Hindin; / von ihm kommen liebliche Reden. /',
        22: 'Ein junger Fruchtbaum ist Joseph, / ein junger Fruchtbaum am Quell; / (seine) Schosse ranken über die Mauer. /',
        23: 'Es reizten ihn und schossen, / es befeindeten ihn Pfeilschützen; /',
        24: 'doch fest blieb sein Bogen / und gelenk die Kraft seiner Hände / durch die Hilfe des Starken Jakobs, / durch den Namen des Hirten Israels, /',
        25: 'durch deines Vaters Gott, der dir helfe, / durch den allmächtigen Gott, der dich segne / mit Segensfülle vom Himmel droben, / mit Segensfülle aus der Flut, die drunten lagert, / mit Segensfülle aus Brüsten und Mutterschoss. /',
        26: 'Die Segnungen deines Vaters sind reicher / als die Segensfülle der ewigen Berge, / als die Lust der uralten Höhen. / Das alles komme auf das Haupt Josephs, / auf den Scheitel des Geweihten unter seinen Brüdern! /',
        27: 'Benjamin ist ein reissender Wolf; / am Morgen verzehrt er Raub, / und am Abend verteilt er Beute.',
        28: "Das sind die zwölf Stämme Israels insgesamt, und das ist's, was ihr Vater zu ihnen geredet hat. UND er segnete sie; einen jeden segnete er mit einem besonderen Segen.",
        29: 'Und er gab ihnen Weisung und sprach zu ihnen: Wenn ich nun versammelt werde zu meinen Stammesgenossen, so begrabet mich bei meinen Vätern in der Höhle auf dem Grundstück des Hethiters Ephron, (a) 1Mo 23:7-18',
        30: 'in der Höhle auf dem Grundstück Machpela, gegenüber Mamre, im Lande Kanaan, dem Grundstück, das Abraham von dem Hethiter Ephron als Grabstätte zu eigen erworben hat.',
        31: 'Dort haben sie Abraham und sein Weib Sara begraben, dort haben sie Isaak und sein Weib Rebekka begraben, und dort habe ich Lea begraben, (a) 1Mo 23:19; 25:9; 35:29',
        32: 'auf dem Grundstück mit der Höhle darauf, das den Hethitern abgekauft wurde.',
        33: 'Als nun Jakob seinen Söhnen alle diese Weisungen gegeben hatte, zog er seine Füsse auf das Bett zurück, verschied und ward versammelt zu seinen Stammesgenossen.',
    },
    50: {
        1: 'Da warf sich Joseph über seinen Vater und weinte über ihm und küsste ihn.',
        2: 'Dann befahl Joseph seinen Dienern, den Ärzten, seinen Vater einzubalsamieren; und die Ärzte balsamierten Israel ein.',
        3: 'Darüber vergingen volle vierzig Tage; denn so lange währt das Einbalsamieren. Und die Ägypter beweinten ihn siebzig Tage lang.',
        4: 'Als nun die Trauerzeit vorbei war, sprach Joseph zum Hof des Pharao: Wollt ihr mir einen Gefallen tun, so redet für mich vor dem Pharao und sagt zu ihm:',
        5: 'Mein Vater hat einen Eid von mir genommen und gesagt: "Wenn ich nun sterbe, so begrabe mich in meiner Gruft, die ich mir im Lande Kanaan gegraben habe." So will ich denn hinaufziehen und meinen Vater begraben und dann zurückkommen. (a) 1Mo 47:29 30',
        6: 'Der Pharao sprach: So ziehe hinauf und begrabe deinen Vater, wie er dich hat schwören lassen.',
        7: 'Da zog Joseph hinauf, seinen Vater zu begraben, und es zogen mit ihm alle Diener des Pharao, die Ältesten seines Hauses und alle Ältesten des Landes Ägypten,',
        8: 'dazu das ganze Haus Josephs, seine Brüder und seines Vaters Haus; nur ihre kleinen Kinder und ihre Rinder und Schafe liessen sie im Lande Gosen.',
        9: 'Auch Wagen und Reiter zogen mit ihm hinauf, und es war ein sehr grosser Heerzug.',
        10: 'Als sie nun nach Goren-Atad kamen, das jenseits des Jordan liegt, hielten sie daselbst eine gar grosse und feierliche Totenklage, und er veranstaltete eine Trauerfeier für seinen Vater, sieben Tage lang. (1) d.i. die Dornentenne.',
        11: 'Und als die Leute im Lande, die Kanaaniter, die Trauerfeier in Goren-Atad sahen, sprachen sie: Da halten die Ägypter eine grosse Trauerfeier. Daher nennt man den Ort Abel-Mizraim; das liegt jenseits des Jordan. (1) d.i. Trauer der Ägypter.',
        12: 'Und seine Söhne taten mit ihm so, wie er ihnen befohlen hatte:',
        13: 'sie brachten ihn in das Land Kanaan und begruben ihn gegenüber Mamre in der Höhle auf dem Grundstück Machpela, das Abraham von dem Hethiter Ephron als Grabstätte zu eigen erworben hatte. (a) 1Mo 23:7-18',
        14: 'Nachdem so Joseph seinen Vater begraben hatte, kehrte er nach Ägypten zurück, er und seine Brüder und alle, die mit ihm hinaufgezogen waren, seinen Vater zu begraben.',
        15: 'ALS nun die Brüder Josephs sahen, dass ihr Vater gestorben war, sprachen sie: Wie? wenn nun Joseph feindselig gegen uns auftritt und uns all das Böse vergilt, das wir ihm angetan haben?',
        16: 'Darum liessen sie dem Joseph sagen: Dein Vater hat vor seinem Tod befohlen:',
        17: '"So sollt ihr zu Joseph sagen: Ach, vergib doch deinen Brüdern ihre Missetat und Sünde, dass sie so übel an dir gehandelt haben." So vergib uns nun unsre Missetat, da wir (doch auch) dem Gotte deines Vaters dienen. Joseph aber weinte, als sie ihm das sagen liessen.',
        18: 'Dann gingen seine Brüder selbst hin, fielen vor ihm nieder und sprachen: Da nimm uns hin, als deine Knechte!',
        19: 'Joseph sprach zu ihnen: Fürchtet euch nicht! Bin ich denn an Gottes Statt?',
        20: 'Ihr zwar gedachtet mir Böses zu tun, aber Gott hat es zum Guten gewendet, dass er täte, was jetzt am Tage ist: ein grosses Volk am Leben zu erhalten.',
        21: 'So fürchtet euch nun nicht! Ich will für euch und eure Kindlein sorgen. Und er tröstete sie und redete ihnen freundlich zu.',
        22: 'So blieb Joseph in Ägypten, er und seines Vaters Haus, und er lebte 110 Jahre.',
        23: 'Und Joseph sah von Ephraim Nachkommen bis ins dritte Geschlecht; auch wurden die Söhne Machirs, des Sohnes Manasses, von Joseph an Kindesstatt angenommen.',
        24: 'Dann sprach Joseph zu seinen Brüdern: Ich sterbe nun; Gott aber wird sich euer annehmen und euch aus diesem Lande hinaufführen in das Land, das er Abraham, Isaak und Jakob zugeschworen hat.',
        25: 'Und Joseph nahm einen Eid von den Söhnen Israels und sprach: Wenn sich Gott euer annehmen wird, so führet meine Gebeine von hier mit hinauf. (a) 2Mo 13:19; Jos 24:32',
        26: 'Darnach starb Joseph, 110 Jahre alt; und man balsamierte ihn ein und legte ihn in Ägypten in einen Sarg.',
    },
}
